// Simple arena-based DOM used by the HTML parser, the asset embedder and the serializer.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ns {
    Html,
    Svg,
    MathMl,
    None,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum AttrNs {
    None,
    XLink,
    Xml,
    XmlNs,
}

#[derive(Clone, Debug)]
pub struct Attr {
    pub ns: AttrNs,
    pub prefix: Option<String>,
    pub name: String,
    pub value: String,
}

impl Attr {
    pub fn new(name: &str, value: &str) -> Attr {
        Attr { ns: AttrNs::None, prefix: None, name: name.to_string(), value: value.to_string() }
    }
}

#[derive(Clone, Debug)]
pub enum NodeData {
    Document,
    Doctype { name: String, public_id: String, system_id: String },
    Text(String),
    Comment(String),
    Element {
        ns: Ns,
        name: String,
        attrs: Vec<Attr>,
        template_contents: Option<usize>,
        mathml_aixp: bool,
    },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub data: NodeData,
}

pub struct Dom {
    pub nodes: Vec<Node>,
    pub quirks: bool,
}

pub const DOCUMENT: usize = 0;

impl Dom {
    pub fn new() -> Dom {
        Dom { nodes: vec![Node { parent: None, children: vec![], data: NodeData::Document }], quirks: false }
    }

    pub fn create(&mut self, data: NodeData) -> usize {
        self.nodes.push(Node { parent: None, children: vec![], data });
        self.nodes.len() - 1
    }

    pub fn create_element(&mut self, ns: Ns, name: &str, attrs: Vec<Attr>) -> usize {
        let id = self.create(NodeData::Element { ns, name: name.to_string(), attrs, template_contents: None, mathml_aixp: false });
        if ns == Ns::Html && name == "template" {
            let frag = self.create(NodeData::Document);
            if let NodeData::Element { template_contents, .. } = &mut self.nodes[id].data {
                *template_contents = Some(frag);
            }
        }
        id
    }

    pub fn append(&mut self, parent: usize, child: usize) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.push(child);
    }

    pub fn prepend(&mut self, parent: usize, child: usize) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.insert(0, child);
    }

    pub fn insert_before(&mut self, parent: usize, child: usize, before: usize) {
        self.detach(child);
        let idx = self.nodes[parent].children.iter().position(|&c| c == before).unwrap_or(self.nodes[parent].children.len());
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.insert(idx, child);
    }

    pub fn detach(&mut self, child: usize) {
        if let Some(p) = self.nodes[child].parent {
            self.nodes[p].children.retain(|&c| c != child);
            self.nodes[child].parent = None;
        }
    }

    pub fn is_element(&self, id: usize) -> bool {
        matches!(self.nodes[id].data, NodeData::Element { .. })
    }

    pub fn elem_name(&self, id: usize) -> Option<(Ns, &str)> {
        match &self.nodes[id].data {
            NodeData::Element { ns, name, .. } => Some((*ns, name.as_str())),
            _ => None,
        }
    }

    pub fn is_html(&self, id: usize, n: &str) -> bool {
        match &self.nodes[id].data {
            NodeData::Element { ns: Ns::Html, name, .. } => name == n,
            _ => false,
        }
    }

    pub fn local_name(&self, id: usize) -> &str {
        match &self.nodes[id].data {
            NodeData::Element { name, .. } => name.as_str(),
            _ => "",
        }
    }

    pub fn attrs(&self, id: usize) -> &[Attr] {
        match &self.nodes[id].data {
            NodeData::Element { attrs, .. } => attrs,
            _ => &[],
        }
    }

    pub fn attrs_mut(&mut self, id: usize) -> Option<&mut Vec<Attr>> {
        match &mut self.nodes[id].data {
            NodeData::Element { attrs, .. } => Some(attrs),
            _ => None,
        }
    }

    // Returns value of the first attribute whose local name matches
    pub fn get_attr(&self, id: usize, name: &str) -> Option<String> {
        for a in self.attrs(id) {
            if a.name == name {
                return Some(a.value.clone());
            }
        }
        None
    }

    pub fn has_attr(&self, id: usize, name: &str) -> bool {
        self.attrs(id).iter().any(|a| a.name == name)
    }

    // Sets value of first attribute with given local name, or appends a new attribute;
    // None removes all attributes with given name.
    pub fn set_attr(&mut self, id: usize, name: &str, value: Option<&str>) {
        if let Some(attrs) = self.attrs_mut(id) {
            match value {
                Some(v) => {
                    for a in attrs.iter_mut() {
                        if a.name == name {
                            a.value = v.to_string();
                            return;
                        }
                    }
                    attrs.push(Attr::new(name, v));
                }
                None => {
                    attrs.retain(|a| a.name != name);
                }
            }
        }
    }

    pub fn template_contents(&self, id: usize) -> Option<usize> {
        match &self.nodes[id].data {
            NodeData::Element { template_contents, .. } => *template_contents,
            _ => None,
        }
    }

    pub fn text_content(&self, id: usize) -> String {
        let mut s = String::new();
        self.collect_text(id, &mut s);
        s
    }

    fn collect_text(&self, id: usize, s: &mut String) {
        match &self.nodes[id].data {
            NodeData::Text(t) => s.push_str(t),
            _ => {
                for &c in &self.nodes[id].children {
                    self.collect_text(c, s);
                }
            }
        }
    }

    pub fn find_child_element(&self, parent: usize, name: &str) -> Option<usize> {
        for &c in &self.nodes[parent].children {
            if let Some((_, n)) = self.elem_name(c) {
                if n == name {
                    return Some(c);
                }
            }
        }
        None
    }
}
EOF
echo ok"}

