    pub fn detach(&mut self, child: usize) {
        if let Some(p) = self.nodes[child].parent {
            self.nodes[p].children.retain(|&c| c != child);
            self.nodes[child].parent = None;
        }
    }

    pub fn is_element(&self, id: usize) -> bool {
        matches!(self.nodes[id].data, NodeData::Element { .. })
    }

    pub fn elem_name(&self, id: usize) -> Option<(Ns, &str)> {
        match &self.nodes[id].data {
            NodeData::Element { ns, name, .. } => Some((*ns, name.as_str())),
            _ => None,
        }
    }

    pub fn is_html(&self, id: usize, n: &str) -> bool {
        match &self.nodes[id].data {
            NodeData::Element { ns: Ns::Html, name, .. } => name == n,
            _ => false,
        }
    }

    pub fn local_name(&self, id: usize) -> &str {
        match &self.nodes[id].data {
            NodeData::Element { name, .. } => name.as_str(),
            _ => "",
        }
    }

    pub fn attrs(&self, id: usize) -> &[Attr] {
        match &self.nodes[id].data {
            NodeData::Element { attrs, .. } => attrs,
            _ => &[],
        }
    }

    pub fn attrs_mut(&mut self, id: usize) -> Option<&mut Vec<Attr>> {
        match &mut self.nodes[id].data {
            NodeData::Element { attrs, .. } => Some(attrs),
            _ => None,
        }
    }

    // Returns value of the first attribute whose local name matches
    pub fn get_attr(&self, id: usize, name: &str) -> Option<String> {
        for a in self.attrs(id) {
            if a.name == name {
                return Some(a.value.clone());
            }
        }
        None
    }

    pub fn has_attr(&self, id: usize, name: &str) -> bool {
        self.attrs(id).iter().any(|a| a.name == name)
    }

    // Sets value of first attribute with given local name, or appends a new attribute;
    // None removes all attributes with given name.
    pub fn set_attr(&mut self, id: usize, name: &str, value: Option<&str>) {
        if let Some(attrs) = self.attrs_mut(id) {
            match value {
                Some(v) => {
                    for a in attrs.iter_mut() {
                        if a.name == name {
                            a.value = v.to_string();
                            return;
                        }
                    }
                    attrs.push(Attr::new(name, v));
                }
                None => {
                    attrs.retain(|a| a.name != name);
                }
            }
        }
    }

    pub fn template_contents(&self, id: usize) -> Option<usize> {
        match &self.nodes[id].data {
            NodeData::Element { template_contents, .. } => *template_contents,
            _ => None,
        }
    }

    pub fn text_content(&self, id: usize) -> String {
        let mut s = String::new();
        self.collect_text(id, &mut s);
        s
    }

    fn collect_text(&self, id: usize, s: &mut String) {
        match &self.nodes[id].data {
            NodeData::Text(t) => s.push_str(t),
            _ => {
                for &c in &self.nodes[id].children {
                    self.collect_text(c, s);
                }
            }
        }
    }

    pub fn find_child_element(&self, parent: usize, name: &str) -> Option<usize> {
        for &c in &self.nodes[parent].children {
            if let Some((_, n)) = self.elem_name(c) {
                if n == name {
                    return Some(c);
                }
            }
        }
        None
    }
}
