pub struct Tokenizer {
    input: Vec<char>,
    pos: usize,
    pub state: State,
    queue: VecDeque<Token>,
    text: String,
    // current tag
    tag_name: String,
    tag_is_end: bool,
    tag_self_closing: bool,
    tag_attrs: Vec<Attr>,
    attr_name: String,
