}

fn is_ws(c: char) -> bool {
    c == '\t' || c == '\n' || c == '\x0C' || c == ' '
}

fn lower(c: char) -> char {
    c.to_ascii_lowercase()
}

fn lookup_entity(name: &str) -> Option<&'static str> {
    match ENTITIES.binary_search_by(|(k, _)| (*k).cmp(name)) {
        Ok(i) => Some(ENTITIES[i].1),
        Err(_) => None,
    }
}

fn c1_replacement(n: u32) -> Option<u32> {
    let r = match n {
        0x80 => 0x20AC,
        0x82 => 0x201A,
        0x83 => 0x0192,
        0x84 => 0x201E,
        0x85 => 0x2026,
        0x86 => 0x2020,
        0x87 => 0x2021,
        0x88 => 0x02C6,
        0x89 => 0x2030,
        0x8A => 0x0160,
        0x8B => 0x2039,
        0x8C => 0x0152,
        0x8E => 0x017D,
        0x91 => 0x2018,
        0x92 => 0x2019,
        0x93 => 0x201C,
        0x94 => 0x201D,
        0x95 => 0x2022,
        0x96 => 0x2013,
        0x97 => 0x2014,
        0x98 => 0x02DC,
        0x99 => 0x2122,
        0x9A => 0x0161,
        0x9B => 0x203A,
        0x9C => 0x0153,
        0x9E => 0x017E,
        0x9F => 0x0178,
        _ => return None,
    };
    Some(r)
}

impl Tokenizer {
    pub fn new(input: &str) -> Tokenizer {
        // Normalize newlines
        let mut chars: Vec<char> = Vec::with_capacity(input.len());
        let mut it = input.chars().peekable();
        let mut first = true;
        while let Some(c) = it.next() {
            if first {
                first = false;
                if c == '\u{FEFF}' {
                    continue;
                }
            }
            if c == '\r' {
                if it.peek() == Some(&'\n') {
                    it.next();
                }
                chars.push('\n');
            } else {
                chars.push(c);
            }
        }
        Tokenizer {
            input: chars,
            pos: 0,
            state: State::Data,
            queue: VecDeque::new(),
            text: String::new(),
            tag_name: String::new(),
            tag_is_end: false,
            tag_self_closing: false,
            tag_attrs: vec![],
            attr_name: String::new(),
            attr_value: String::new(),
            attr_active: false,
            last_start_tag: String::new(),
            temp_buf: String::new(),
            comment: String::new(),
            doctype: Doctype::default(),
            allow_cdata: false,
            eof_emitted: false,
        }
    }

    fn next_char(&mut self) -> Option<char> {
        if self.pos < self.input.len() {
            let c = self.input[self.pos];
            self.pos += 1;
            Some(c)
        } else {
            self.pos += 1; // allow reconsume of EOF
            None
        }
    }

    fn reconsume(&mut self) {
        self.pos -= 1;
    }

    fn peek_str_ci(&self, s: &str) -> bool {
        let n = s.chars().count();
        if self.pos + n > self.input.len() {
            return false;
        }
        for (i, c) in s.chars().enumerate() {
            if lower(self.input[self.pos + i]) != c {
                return false;
            }
        }
        true
    }

    fn peek_str(&self, s: &str) -> bool {
        let n = s.chars().count();
        if self.pos + n > self.input.len() {
            return false;
        }
        for (i, c) in s.chars().enumerate() {
            if self.input[self.pos + i] != c {
                return false;
            }
        }
        true
    }

    fn emit_char(&mut self, c: char) {
        self.text.push(c);
    }

    fn emit_str(&mut self, s: &str) {
        self.text.push_str(s);
    }

    fn flush_text(&mut self) {
        if !self.text.is_empty() {
            let t = std::mem::take(&mut self.text);
            self.queue.push_back(Token::Chars(t));
        }
    }

    fn emit(&mut self, t: Token) {
        self.flush_text();
        self.queue.push_back(t);
    }

    fn emit_null(&mut self) {
        self.emit(Token::NullChar);
    }

    fn start_tag(&mut self, is_end: bool) {
        self.tag_name.clear();
        self.tag_is_end = is_end;
        self.tag_self_closing = false;
        self.tag_attrs.clear();
        self.attr_active = false;
    }

    fn start_attr(&mut self) {
        self.finish_attr();
        self.attr_name.clear();
        self.attr_value.clear();
        self.attr_active = true;
    }

    fn finish_attr(&mut self) {
        if self.attr_active {
            self.attr_active = false;
            let name = std::mem::take(&mut self.attr_name);
            let value = std::mem::take(&mut self.attr_value);
            if !self.tag_attrs.iter().any(|a| a.name == name) {
                self.tag_attrs.push(Attr::new(&name, &value));
            }
        }
    }

    fn emit_tag(&mut self) {
        self.finish_attr();
        let tag = Tag {
            name: std::mem::take(&mut self.tag_name),
            attrs: std::mem::take(&mut self.tag_attrs),
            self_closing: self.tag_self_closing,
        };
        if self.tag_is_end {
            self.emit(Token::EndTag(tag));
        } else {
            self.last_start_tag = tag.name.clone();
            self.emit(Token::StartTag(tag));
        }
    }

    fn emit_comment(&mut self) {
        let c = std::mem::take(&mut self.comment);
        self.emit(Token::Comment(c));
    }

    fn emit_doctype(&mut self) {
        let d = std::mem::take(&mut self.doctype);
        self.emit(Token::Doctype(d));
    }

    fn appropriate_end_tag(&self) -> bool {
        self.tag_is_end && self.tag_name == self.last_start_tag
    }

    fn is_attr_return(state: State) -> bool {
        matches!(state, State::AttrValueDq | State::AttrValueSq | State::AttrValueUnq)
    }

    fn push_char_ref_result(&mut self, return_state: State, s: &str) {
        if Self::is_attr_return(return_state) {
            self.attr_value.push_str(s);
        } else {
            self.emit_str(s);
        }
    }

    // Called right after '&' was consumed
    fn char_ref(&mut self, return_state: State) {
        let in_attr = Self::is_attr_return(return_state);
        let c = if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None };
        match c {
            Some(c) if c.is_ascii_alphanumeric() => {
                // named reference
                let mut run = String::new();
                let mut i = self.pos;
                while i < self.input.len() && self.input[i].is_ascii_alphanumeric() && run.len() < 40 {
                    run.push(self.input[i]);
                    i += 1;
                }
                let has_semi = i < self.input.len() && self.input[i] == ';' && run.len() < 40;
                let mut candidate = run.clone();
                if has_semi {
                    candidate.push(';');
                }
                // find longest prefix
                let chars: Vec<char> = candidate.chars().collect();
                let mut found: Option<(usize, &'static str)> = None;
                for len in (1..=chars.len()).rev() {
                    let name: String = chars[..len].iter().collect();
                    if let Some(v) = lookup_entity(&name) {
                        found = Some((len, v));
                        break;
                    }
                }
                match found {
                    Some((len, v)) => {
                        let last = chars[len - 1];
                        let next = if self.pos + len < self.input.len() { Some(self.input[self.pos + len]) } else { None };
                        if in_attr && last != ';' && matches!(next, Some(n) if n == '=' || n.is_ascii_alphanumeric()) {
                            let name: String = chars[..len].iter().collect();
                            self.pos += len;
                            let mut s = String::from("&");
                            s.push_str(&name);
                            self.push_char_ref_result(return_state, &s);
                        } else {
                            self.pos += len;
                            self.push_char_ref_result(return_state, v);
                        }
                    }
                    None => {
                        // ambiguous ampersand: emit '&' and the alnum run
                        self.pos += run.chars().count();
                        let mut s = String::from("&");
                        s.push_str(&run);
                        self.push_char_ref_result(return_state, &s);
                    }
                }
            }
            Some('#') => {
                let start = self.pos;
                self.pos += 1;
                let mut hex = false;
                if self.pos < self.input.len() && (self.input[self.pos] == 'x' || self.input[self.pos] == 'X') {
                    hex = true;
                    self.pos += 1;
                }
                let digits_start = self.pos;
                let mut val: u64 = 0;
                while self.pos < self.input.len() {
                    let d = self.input[self.pos];
                    let dv = if hex { d.to_digit(16) } else { d.to_digit(10) };
                    match dv {
                        Some(v) => {
                            val = val * if hex { 16 } else { 10 } + v as u64;
                            if val > 0x10FFFF {
                                val = 0x110000;
                            }
                            self.pos += 1;
                        }
                        None => break,
                    }
                }
                if self.pos == digits_start {
                    // no digits: flush consumed characters
                    let consumed: String = self.input[start..self.pos].iter().collect();
                    let mut s = String::from("&");
                    s.push_str(&consumed);
                    self.push_char_ref_result(return_state, &s);
                    return;
                }
                if self.pos < self.input.len() && self.input[self.pos] == ';' {
                    self.pos += 1;
                }
                let mut n = val as u32;
                if n == 0 || n > 0x10FFFF || (0xD800..=0xDFFF).contains(&n) {
                    n = 0xFFFD;
                } else if let Some(r) = c1_replacement(n) {
                    n = r;
                }
                let ch = char::from_u32(n).unwrap_or('\u{FFFD}');
                let mut s = String::new();
                s.push(ch);
                self.push_char_ref_result(return_state, &s);
            }
            _ => {
                self.push_char_ref_result(return_state, "&");
            }
        }
    }

    pub fn next_token(&mut self) -> Token {
        loop {
            if let Some(t) = self.queue.pop_front() {
                return t;
            }
            if self.eof_emitted {
                return Token::Eof;
            }
            self.step();
        }
    }

    fn step(&mut self) {
        // process characters until something is in the queue
        while self.queue.is_empty() && !self.eof_emitted {
            self.run_state();
        }
    }

    fn eof(&mut self) {
        self.flush_text();
        self.queue.push_back(Token::Eof);
        self.eof_emitted = true;
    }

    fn run_state(&mut self) {
        use State::*;
        match self.state {
            Data => {
                // fast path for text
                loop {
                    match self.next_char() {
                        Some('&') => {
                            self.char_ref(Data);
                        }
                        Some('<') => {
                            self.state = TagOpen;
                            return;
                        }
                        Some('\0') => {
                            self.emit_null();
                            return;
                        }
                        None => {
                            self.eof();
                            return;
                        }
                        Some(c) => self.emit_char(c),
                    }
                }
            }
            RcData => loop {
                match self.next_char() {
                    Some('&') => self.char_ref(RcData),
                    Some('<') => {
                        self.state = RcDataLt;
                        return;
                    }
                    Some('\0') => self.emit_char('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.emit_char(c),
                }
            },
            RawText => loop {
                match self.next_char() {
                    Some('<') => {
                        self.state = RawTextLt;
                        return;
                    }
                    Some('\0') => self.emit_char('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.emit_char(c),
                }
            },
            ScriptData => loop {
                match self.next_char() {
                    Some('<') => {
                        self.state = ScriptDataLt;
                        return;
                    }
                    Some('\0') => self.emit_char('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.emit_char(c),
                }
            },
            PlainText => loop {
                match self.next_char() {
                    Some('\0') => self.emit_char('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.emit_char(c),
                }
            },
            TagOpen => match self.next_char() {
                Some('!') => self.state = MarkupDeclOpen,
                Some('/') => self.state = EndTagOpen,
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(false);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('?') => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                None => {
                    self.emit_char('<');
                    self.eof();
                }
                Some(_) => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Data;
                }
            },
            EndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('>') => {
                    self.state = Data;
                }
                None => {
                    self.emit_str("</");
                    self.eof();
                }
                Some(_) => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
            },
            TagName => loop {
                match self.next_char() {
                    Some(c) if is_ws(c) => {
                        self.state = BeforeAttrName;
                        return;
                    }
                    Some('/') => {
                        self.state = SelfClosingStartTag;
                        return;
                    }
                    Some('>') => {
                        self.state = Data;
                        self.emit_tag();
                        return;
                    }
                    Some('\0') => self.tag_name.push('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.tag_name.push(lower(c)),
                }
            },
            RcDataLt => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RcDataEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = RcData;
                }
            },
            RcDataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = RcDataEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = RcData;
                }
            },
            RcDataEndTagName | RawTextEndTagName | ScriptDataEndTagName | ScriptDataEscapedEndTagName => {
                let back = match self.state {
                    RcDataEndTagName => RcData,
                    RawTextEndTagName => RawText,
                    ScriptDataEndTagName => ScriptData,
                    _ => ScriptDataEscaped,
                };
                let c = self.next_char();
                match c {
                    Some(c) if is_ws(c) && self.appropriate_end_tag() => self.state = BeforeAttrName,
                    Some('/') if self.appropriate_end_tag() => self.state = SelfClosingStartTag,
                    Some('>') if self.appropriate_end_tag() => {
                        self.state = Data;
                        self.emit_tag();
                    }
                    Some(c) if c.is_ascii_alphabetic() => {
                        self.tag_name.push(lower(c));
                        self.temp_buf.push(c);
                    }
                    _ => {
                        self.emit_str("</");
                        let tb = self.temp_buf.clone();
                        self.emit_str(&tb);
                        self.reconsume();
                        self.state = back;
                    }
                }
            }
            RawTextLt => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RawTextEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = RawText;
                }
            },
            RawTextEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = RawTextEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = RawText;
                }
            },
            ScriptDataLt => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEndTagOpen;
                }
                Some('!') => {
                    self.emit_str("<!");
                    self.state = ScriptDataEscapeStart;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = ScriptDataEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStart => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataEscapeStartDash;
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStartDash => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataEscapedDashDash;
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscaped => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataEscapedDash;
                }
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('\0') => self.emit_char('\u{FFFD}'),
                None => self.eof(),
                Some(c) => self.emit_char(c),
            },
            ScriptDataEscapedDash => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataEscapedDashDash;
                }
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('\0') => {
                    self.emit_char('\u{FFFD}');
                    self.state = ScriptDataEscaped;
                }
                None => self.eof(),
                Some(c) => {
                    self.emit_char(c);
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => self.state = ScriptDataEscapedLt,
                Some('>') => {
                    self.emit_char('>');
                    self.state = ScriptData;
                }
                Some('\0') => {
                    self.emit_char('\u{FFFD}');
                    self.state = ScriptDataEscaped;
                }
                None => self.eof(),
                Some(c) => {
                    self.emit_char(c);
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedLt => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEscapedEndTagOpen;
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.clear();
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataDoubleEscapeStart;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag(true);
                    self.reconsume();
                    self.state = ScriptDataEscapedEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscapeStart => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataDoubleEscaped;
                    } else {
                        self.state = ScriptDataEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(lower(c));
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscaped => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataDoubleEscapedDash;
                }
                Some('<') => {
                    self.emit_char('<');
                    self.state = ScriptDataDoubleEscapedLt;
                }
                Some('\0') => self.emit_char('\u{FFFD}'),
                None => self.eof(),
                Some(c) => self.emit_char(c),
            },
            ScriptDataDoubleEscapedDash => match self.next_char() {
                Some('-') => {
                    self.emit_char('-');
                    self.state = ScriptDataDoubleEscapedDashDash;
                }
                Some('<') => {
                    self.emit_char('<');
                    self.state = ScriptDataDoubleEscapedLt;
                }
                Some('\0') => {
                    self.emit_char('\u{FFFD}');
                    self.state = ScriptDataDoubleEscaped;
                }
                None => self.eof(),
                Some(c) => {
                    self.emit_char(c);
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => {
                    self.emit_char('<');
                    self.state = ScriptDataDoubleEscapedLt;
                }
                Some('>') => {
                    self.emit_char('>');
                    self.state = ScriptData;
                }
                Some('\0') => {
                    self.emit_char('\u{FFFD}');
                    self.state = ScriptDataDoubleEscaped;
                }
                None => self.eof(),
                Some(c) => {
                    self.emit_char(c);
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapedLt => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.emit_char('/');
                    self.state = ScriptDataDoubleEscapeEnd;
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapeEnd => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataEscaped;
                    } else {
                        self.state = ScriptDataDoubleEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(lower(c));
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            BeforeAttrName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') | Some('>') | None => {
                    self.reconsume();
                    self.state = AfterAttrName;
                }
                Some('=') => {
                    self.start_attr();
                    self.attr_name.push('=');
                    self.state = AttrName;
                }
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttrName;
                }
            },
            AttrName => loop {
                match self.next_char() {
                    Some(c) if is_ws(c) || c == '/' || c == '>' => {
                        self.reconsume();
                        self.state = AfterAttrName;
                        return;
                    }
                    None => {
                        self.reconsume();
                        self.state = AfterAttrName;
                        return;
                    }
                    Some('=') => {
                        self.state = BeforeAttrValue;
                        return;
                    }
                    Some('\0') => self.attr_name.push('\u{FFFD}'),
                    Some(c) => self.attr_name.push(lower(c)),
                }
            },
            AfterAttrName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') => self.state = SelfClosingStartTag,
                Some('=') => self.state = BeforeAttrValue,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.eof(),
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttrName;
                }
            },
            BeforeAttrValue => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('"') => self.state = AttrValueDq,
                Some('\'') => self.state = AttrValueSq,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                _ => {
                    self.reconsume();
                    self.state = AttrValueUnq;
                }
            },
            AttrValueDq => loop {
                match self.next_char() {
                    Some('"') => {
                        self.state = AfterAttrValueQuoted;
                        return;
                    }
                    Some('&') => self.char_ref(AttrValueDq),
                    Some('\0') => self.attr_value.push('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.attr_value.push(c),
                }
            },
            AttrValueSq => loop {
                match self.next_char() {
                    Some('\'') => {
                        self.state = AfterAttrValueQuoted;
                        return;
                    }
                    Some('&') => self.char_ref(AttrValueSq),
                    Some('\0') => self.attr_value.push('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.attr_value.push(c),
                }
            },
            AttrValueUnq => loop {
                match self.next_char() {
                    Some(c) if is_ws(c) => {
                        self.state = BeforeAttrName;
                        return;
                    }
                    Some('&') => self.char_ref(AttrValueUnq),
                    Some('>') => {
                        self.state = Data;
                        self.emit_tag();
                        return;
                    }
                    Some('\0') => self.attr_value.push('\u{FFFD}'),
                    None => {
                        self.eof();
                        return;
                    }
                    Some(c) => self.attr_value.push(c),
                }
            },
            AfterAttrValueQuoted => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttrName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttrName;
                }
            },
            SelfClosingStartTag => match self.next_char() {
                Some('>') => {
                    self.tag_self_closing = true;
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttrName;
                }
            },
            BogusComment => loop {
                match self.next_char() {
                    Some('>') => {
                        self.state = Data;
                        self.emit_comment();
                        return;
                    }
                    None => {
                        self.emit_comment();
                        self.eof();
                        return;
                    }
                    Some('\0') => self.comment.push('\u{FFFD}'),
                    Some(c) => self.comment.push(c),
                }
            },
            MarkupDeclOpen => {
                if self.peek_str("--") {
                    self.pos += 2;
                    self.comment.clear();
                    self.state = CommentStart;
                } else if self.peek_str_ci("doctype") {
                    self.pos += 7;
                    self.state = Doctype;
                } else if self.peek_str("[CDATA[") {
                    self.pos += 7;
                    if self.allow_cdata {
                        self.state = CdataSection;
                    } else {
                        self.comment.clear();
                        self.comment.push_str("[CDATA[");
                        self.state = BogusComment;
                    }
                } else {
                    self.comment.clear();
                    self.state = BogusComment;
                }
            }
            CommentStart => match self.next_char() {
                Some('-') => self.state = CommentStartDash,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                _ => {
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentStartDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Comment => loop {
                match self.next_char() {
                    Some('<') => {
                        self.comment.push('<');
                        self.state = CommentLt;
                        return;
                    }
                    Some('-') => {
                        self.state = CommentEndDash;
                        return;
                    }
                    Some('\0') => self.comment.push('\u{FFFD}'),
                    None => {
                        self.emit_comment();
                        self.eof();
                        return;
                    }
                    Some(c) => self.comment.push(c),
                }
            },
            CommentLt => match self.next_char() {
                Some('!') => {
                    self.comment.push('!');
                    self.state = CommentLtBang;
                }
                Some('<') => self.comment.push('<'),
                _ => {
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentLtBang => match self.next_char() {
                Some('-') => self.state = CommentLtBangDash,
                _ => {
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentLtBangDash => match self.next_char() {
                Some('-') => self.state = CommentLtBangDashDash,
                _ => {
                    self.reconsume();
                    self.state = CommentEndDash;
                }
            },
            CommentLtBangDashDash => {
                self.next_char();
                self.reconsume();
                self.state = CommentEnd;
            }
            CommentEndDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                None => {
                    self.emit_comment();
                    self.eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEnd => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                Some('!') => self.state = CommentEndBang,
                Some('-') => self.comment.push('-'),
                None => {
                    self.emit_comment();
                    self.eof();
                }
                Some(_) => {
                    self.comment.push_str("--");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEndBang => match self.next_char() {
                Some('-') => {
                    self.comment.push_str("--!");
                    self.state = CommentEndDash;
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.eof();
                }
                Some(_) => {
                    self.comment.push_str("--!");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Doctype => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeDoctypeName,
                Some('>') => {
                    self.reconsume();
                    self.state = BeforeDoctypeName;
                }
                None => {
                    self.doctype = Default::default();
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeDoctypeName;
                }
            },
            BeforeDoctypeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('\0') => {
                    self.doctype = Default::default();
                    self.doctype.name = Some("\u{FFFD}".to_string());
                    self.state = DoctypeName;
                }
                Some('>') => {
                    self.doctype = Default::default();
                    self.doctype.force_quirks = true;
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype = Default::default();
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(c) => {
                    self.doctype = Default::default();
                    self.doctype.name = Some(lower(c).to_string());
                    self.state = DoctypeName;
                }
            },
            DoctypeName => match self.next_char() {
                Some(c) if is_ws(c) => self.state = AfterDoctypeName,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('\0') => self.doctype.name.as_mut().unwrap().push('\u{FFFD}'),
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(c) => self.doctype.name.as_mut().unwrap().push(lower(c)),
            },
            AfterDoctypeName => {
                match self.next_char() {
                    Some(c) if is_ws(c) => {}
                    Some('>') => {
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.eof();
                    }
                    Some(_) => {
                        self.reconsume();
                        if self.peek_str_ci("public") {
                            self.pos += 6;
                            self.state = AfterDoctypePublicKw;
                        } else if self.peek_str_ci("system") {
                            self.pos += 6;
                            self.state = AfterDoctypeSystemKw;
                        } else {
                            self.pos += 1;
                            self.doctype.force_quirks = true;
                            self.state = BogusDoctype;
                        }
                    }
                }
            }
            AfterDoctypePublicKw | AfterDoctypeSystemKw => {
                let public = self.state == AfterDoctypePublicKw;
                match self.next_char() {
                    Some(c) if is_ws(c) => {
                        self.state = if public { BeforeDoctypePublicId } else { BeforeDoctypeSystemId };
                    }
                    Some('"') => {
                        self.set_doctype_id(public);
                        self.state = if public { DoctypePublicIdDq } else { DoctypeSystemIdDq };
                    }
                    Some('\'') => {
                        self.set_doctype_id(public);
                        self.state = if public { DoctypePublicIdSq } else { DoctypeSystemIdSq };
                    }
                    Some('>') => {
                        self.doctype.force_quirks = true;
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.eof();
                    }
                    Some(_) => {
                        self.doctype.force_quirks = true;
                        self.reconsume();
                        self.state = BogusDoctype;
                    }
                }
            }
            BeforeDoctypePublicId | BeforeDoctypeSystemId => {
                let public = self.state == BeforeDoctypePublicId;
                match self.next_char() {
                    Some(c) if is_ws(c) => {}
                    Some('"') => {
                        self.set_doctype_id(public);
                        self.state = if public { DoctypePublicIdDq } else { DoctypeSystemIdDq };
                    }
                    Some('\'') => {
                        self.set_doctype_id(public);
                        self.state = if public { DoctypePublicIdSq } else { DoctypeSystemIdSq };
                    }
                    Some('>') => {
                        self.doctype.force_quirks = true;
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.eof();
                    }
                    Some(_) => {
                        self.doctype.force_quirks = true;
                        self.reconsume();
                        self.state = BogusDoctype;
                    }
                }
            }
            DoctypePublicIdDq | DoctypePublicIdSq | DoctypeSystemIdDq | DoctypeSystemIdSq => {
                let public = matches!(self.state, DoctypePublicIdDq | DoctypePublicIdSq);
                let quote = if matches!(self.state, DoctypePublicIdDq | DoctypeSystemIdDq) { '"' } else { '\'' };
                match self.next_char() {
                    Some(c) if c == quote => {
                        self.state = if public { AfterDoctypePublicId } else { AfterDoctypeSystemId };
                    }
                    Some('\0') => self.push_doctype_id(public, '\u{FFFD}'),
                    Some('>') => {
                        self.doctype.force_quirks = true;
                        self.state = Data;
                        self.emit_doctype();
                    }
                    None => {
                        self.doctype.force_quirks = true;
                        self.emit_doctype();
                        self.eof();
                    }
                    Some(c) => self.push_doctype_id(public, c),
                }
            }
            AfterDoctypePublicId => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BetweenDoctypePublicSystem,
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.set_doctype_id(false);
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.set_doctype_id(false);
                    self.state = DoctypeSystemIdSq;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BetweenDoctypePublicSystem => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                Some('"') => {
                    self.set_doctype_id(false);
                    self.state = DoctypeSystemIdDq;
                }
                Some('\'') => {
                    self.set_doctype_id(false);
                    self.state = DoctypeSystemIdSq;
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(_) => {
                    self.doctype.force_quirks = true;
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            AfterDoctypeSystemId => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.eof();
                }
                Some(_) => {
                    self.reconsume();
                    self.state = BogusDoctype;
                }
            },
            BogusDoctype => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_doctype();
                }
                None => {
                    self.emit_doctype();
                    self.eof();
                }
                _ => {}
            },
            CdataSection => loop {
                match self.next_char() {
                    Some(']') => {
                        self.state = CdataSectionBracket;
                        return;
                    }
                    None => {
                        self.eof();
                        return;
                    }
                    Some('\0') => {
                        // emitted as NUL char token
                        self.emit_null();
                        return;
                    }
                    Some(c) => self.emit_char(c),
                }
            },
            CdataSectionBracket => match self.next_char() {
                Some(']') => self.state = CdataSectionEnd,
                _ => {
                    self.emit_char(']');
                    self.reconsume();
                    self.state = CdataSection;
                }
            },
            CdataSectionEnd => match self.next_char() {
                Some(']') => self.emit_char(']'),
                Some('>') => self.state = Data,
                _ => {
                    self.emit_str("]]");
                    self.reconsume();
                    self.state = CdataSection;
                }
            },
        }
    }

    fn set_doctype_id(&mut self, public: bool) {
        if public {
            self.doctype.public_id = Some(String::new());
        } else {
            self.doctype.system_id = Some(String::new());
        }
    }

    fn push_doctype_id(&mut self, public: bool, c: char) {
        if public {
            self.doctype.public_id.as_mut().unwrap().push(c);
        } else {
            self.doctype.system_id.as_mut().unwrap().push(c);
        }
    }
}
EOF
echo ok"}

