cd /workspace/src && cat > tokenizer.rs <<'EOF'
// HTML5 tokenizer (WHATWG spec)
use crate::dom::Attr;
use crate::entities::ENTITIES;
use std::collections::VecDeque;

#[derive(Debug, Clone)]
pub struct Tag {
    pub name: String,
    pub attrs: Vec<Attr>,
    pub self_closing: bool,
}

#[derive(Debug, Clone, Default)]
pub struct Doctype {
    pub name: Option<String>,
    pub public_id: Option<String>,
    pub system_id: Option<String>,
    pub force_quirks: bool,
}

#[derive(Debug, Clone)]
pub enum Token {
    Doctype(Doctype),
    StartTag(Tag),
    EndTag(Tag),
    Comment(String),
    Chars(String),
    NullChar,
    Eof,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Data,
    RcData,
    RawText,
    ScriptData,
