        "patternunits" => "patternUnits",
        "pointsatx" => "pointsAtX",
        "pointsaty" => "pointsAtY",
        "pointsatz" => "pointsAtZ",
        "preservealpha" => "preserveAlpha",
        "preserveaspectratio" => "preserveAspectRatio",
        "primitiveunits" => "primitiveUnits",
        "refx" => "refX",
        "refy" => "refY",
        "repeatcount" => "repeatCount",
        "repeatdur" => "repeatDur",
        "requiredextensions" => "requiredExtensions",
        "requiredfeatures" => "requiredFeatures",
        "specularconstant" => "specularConstant",
        "specularexponent" => "specularExponent",
        "spreadmethod" => "spreadMethod",
        "startoffset" => "startOffset",
        "stddeviation" => "stdDeviation",
        "stitchtiles" => "stitchTiles",
        "surfacescale" => "surfaceScale",
        "systemlanguage" => "systemLanguage",
        "tablevalues" => "tableValues",
        "targetx" => "targetX",
        "targety" => "targetY",
        "textlength" => "textLength",
        "viewbox" => "viewBox",
        "viewtarget" => "viewTarget",
        "xchannelselector" => "xChannelSelector",
        "ychannelselector" => "yChannelSelector",
        "zoomandpan" => "zoomAndPan",
        _ => name,
    }
}

fn adjust_foreign_attrs(attrs: &mut Vec<Attr>) {
    for a in attrs.iter_mut() {
        let (ns, prefix, local): (AttrNs, Option<&str>, &str) = match a.name.as_str() {
            "xlink:actuate" => (AttrNs::XLink, Some("xlink"), "actuate"),
            "xlink:arcrole" => (AttrNs::XLink, Some("xlink"), "arcrole"),
            "xlink:href" => (AttrNs::XLink, Some("xlink"), "href"),
            "xlink:role" => (AttrNs::XLink, Some("xlink"), "role"),
            "xlink:show" => (AttrNs::XLink, Some("xlink"), "show"),
            "xlink:title" => (AttrNs::XLink, Some("xlink"), "title"),
            "xlink:type" => (AttrNs::XLink, Some("xlink"), "type"),
            "xml:lang" => (AttrNs::Xml, Some("xml"), "lang"),
            "xml:space" => (AttrNs::Xml, Some("xml"), "space"),
            "xmlns" => (AttrNs::XmlNs, None, "xmlns"),
            "xmlns:xlink" => (AttrNs::XmlNs, Some("xmlns"), "xlink"),
            _ => continue,
        };
        a.ns = ns;
        a.prefix = prefix.map(|s| s.to_string());
        a.name = local.to_string();
    }
}

fn adjust_svg_attrs(attrs: &mut Vec<Attr>) {
    for a in attrs.iter_mut() {
        let n = svg_attr_adjust(&a.name).to_string();
        a.name = n;
    }
}

fn adjust_mathml_attrs(attrs: &mut Vec<Attr>) {
    for a in attrs.iter_mut() {
        if a.name == "definitionurl" {
            a.name = "definitionURL".to_string();
        }
    }
}

enum Step {
    Done,
    Reprocess(Mode, Token),
    ReprocessForeign(Token),
}

impl TreeBuilder {
    pub fn new(input: &str) -> TreeBuilder {
        TreeBuilder {
            dom: Dom::new(),
            tok: Tokenizer::new(input),
            mode: Mode::Initial,
            orig_mode: Mode::Initial,
            template_modes: vec![],
            open: vec![],
            afe: vec![],
            head: None,
            form: None,
            frameset_ok: true,
            foster: false,
            pending_table_text: vec![],
            scripting: true,
            ignore_lf: false,
            stop: false,
        }
    }

    pub fn run(mut self) -> Dom {
        loop {
            // CDATA allowed if adjusted current node is foreign
            self.tok.allow_cdata = match self.adjusted_current() {
                Some(n) => self.ns_of(n) != Ns::Html,
                None => false,
            };
            let mut t = self.tok.next_token();
            if self.ignore_lf {
                self.ignore_lf = false;
                if let Token::Chars(s) = &t {
                    if let Some(rest) = s.strip_prefix('\n') {
                        if rest.is_empty() {
                            continue;
                        }
                        t = Token::Chars(rest.to_string());
                    }
                }
            }
            let is_eof = matches!(t, Token::Eof);
            self.dispatch(t);
            if is_eof || self.stop {
                break;
            }
        }
        self.dom
    }

    // ---------- helpers ----------
    fn ns_of(&self, n: usize) -> Ns {
        match &self.dom.nodes[n].data {
            NodeData::Element { ns, .. } => *ns,
            _ => Ns::Html,
        }
    }

    fn name_of(&self, n: usize) -> &str {
        self.dom.local_name(n)
    }

    fn is_html_named(&self, n: usize, names: &[&str]) -> bool {
        match &self.dom.nodes[n].data {
            NodeData::Element { ns: Ns::Html, name, .. } => names.contains(&name.as_str()),
            _ => false,
        }
    }

    fn current(&self) -> Option<usize> {
        self.open.last().copied()
    }

    fn current_is(&self, names: &[&str]) -> bool {
        match self.current() {
            Some(n) => self.is_html_named(n, names),
            None => false,
        }
    }

    fn adjusted_current(&self) -> Option<usize> {
        // no fragment parsing context
        self.current()
    }

    fn is_special(&self, n: usize) -> bool {
        match &self.dom.nodes[n].data {
            NodeData::Element { ns: Ns::Html, name, .. } => SPECIAL_HTML.contains(&name.as_str()),
            NodeData::Element { ns: Ns::MathMl, name, .. } => matches!(name.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml"),
            NodeData::Element { ns: Ns::Svg, name, .. } => matches!(name.as_str(), "foreignObject" | "desc" | "title"),
            _ => false,
        }
    }

    fn is_scope_boundary(&self, n: usize, extra: &[&str]) -> bool {
        match &self.dom.nodes[n].data {
            NodeData::Element { ns: Ns::Html, name, .. } => {
                matches!(name.as_str(), "applet" | "caption" | "html" | "table" | "td" | "th" | "marquee" | "object" | "template") || extra.contains(&name.as_str())
            }
            NodeData::Element { ns: Ns::MathMl, name, .. } => matches!(name.as_str(), "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml"),
            NodeData::Element { ns: Ns::Svg, name, .. } => matches!(name.as_str(), "foreignObject" | "desc" | "title"),
            _ => false,
        }
    }

    fn in_scope_generic(&self, target: &[&str], boundary: &dyn Fn(&Self, usize) -> bool) -> bool {
        for &n in self.open.iter().rev() {
            if self.is_html_named(n, target) {
                return true;
            }
            if boundary(self, n) {
                return false;
            }
        }
        false
    }

    fn in_scope(&self, name: &str) -> bool {
        self.in_scope_generic(&[name], &|s, n| s.is_scope_boundary(n, &[]))
    }

    fn in_scope_any(&self, names: &[&str]) -> bool {
        self.in_scope_generic(names, &|s, n| s.is_scope_boundary(n, &[]))
    }

    fn in_list_item_scope(&self, name: &str) -> bool {
        self.in_scope_generic(&[name], &|s, n| s.is_scope_boundary(n, &["ol", "ul"]))
    }

    fn in_button_scope(&self, name: &str) -> bool {
        self.in_scope_generic(&[name], &|s, n| s.is_scope_boundary(n, &["button"]))
    }

    fn in_table_scope(&self, name: &str) -> bool {
        self.in_scope_generic(&[name], &|s, n| s.is_html_named(n, &["html", "table", "template"]))
    }

    fn in_table_scope_any(&self, names: &[&str]) -> bool {
        self.in_scope_generic(names, &|s, n| s.is_html_named(n, &["html", "table", "template"]))
    }

    fn in_select_scope(&self, name: &str) -> bool {
        self.in_scope_generic(&[name], &|s, n| !s.is_html_named(n, &["optgroup", "option"]))
    }

    fn node_in_scope(&self, node: usize) -> bool {
        for &n in self.open.iter().rev() {
            if n == node {
                return true;
            }
            if self.is_scope_boundary(n, &[]) {
                return false;
            }
        }
        false
    }

    fn generate_implied_end_tags(&mut self, except: Option<&str>) {
        loop {
            let c = match self.current() {
                Some(c) => c,
                None => return,
            };
            if self.is_html_named(c, &["dd", "dt", "li", "optgroup", "option", "p", "rb", "rp", "rt", "rtc"]) {
                if let Some(e) = except {
                    if self.name_of(c) == e {
                        return;
                    }
                }
                self.open.pop();
            } else {
                return;
            }
        }
    }

    fn generate_all_implied_end_tags(&mut self) {
        while let Some(c) = self.current() {
            if self.is_html_named(c, &["caption", "colgroup", "dd", "dt", "li", "optgroup", "option", "p", "rb", "rp", "rt", "rtc", "tbody", "td", "tfoot", "th", "thead", "tr"]) {
                self.open.pop();
            } else {
                return;
            }
        }
    }

    fn pop_until(&mut self, names: &[&str]) {
        while let Some(n) = self.open.pop() {
            if self.is_html_named(n, names) {
                return;
            }
        }
    }

    fn pop_until_node(&mut self, node: usize) {
        while let Some(n) = self.open.pop() {
            if n == node {
                return;
            }
        }
    }

    fn remove_from_open(&mut self, node: usize) {
        self.open.retain(|&n| n != node);
    }

    // Appropriate place for inserting: (parent, before)
    fn insertion_place(&self, override_target: Option<usize>) -> (usize, Option<usize>) {
        let target = override_target.or(self.current()).unwrap_or(DOCUMENT);
        let mut place: (usize, Option<usize>);
        if self.foster && self.is_html_named(target, &["table", "tbody", "tfoot", "thead", "tr"]) {
            let last_template = self.open.iter().rposition(|&n| self.dom.is_html(n, "template"));
            let last_table = self.open.iter().rposition(|&n| self.dom.is_html(n, "table"));
            if let Some(lt) = last_template {
                if last_table.is_none() || lt > last_table.unwrap() {
                    let tc = self.dom.template_contents(self.open[lt]).unwrap();
                    return (tc, None);
                }
            }
            match last_table {
                None => {
                    place = (self.open[0], None);
                }
                Some(ti) => {
                    let table = self.open[ti];
                    if let Some(p) = self.dom.nodes[table].parent {
                        place = (p, Some(table));
                    } else {
                        place = (self.open[ti - 1], None);
                    }
                }
            }
        } else {
            place = (target, None);
        }
        if place.1.is_none() && self.dom.is_html(place.0, "template") {
            place = (self.dom.template_contents(place.0).unwrap(), None);
        }
        place
    }

    fn insert_at(&mut self, place: (usize, Option<usize>), node: usize) {
        match place.1 {
            Some(before) => self.dom.insert_before(place.0, node, before),
            None => self.dom.append(place.0, node),
        }
    }

    fn insert_text(&mut self, s: &str) {
        if s.is_empty() {
            return;
        }
        let place = self.insertion_place(None);
        if place.0 == DOCUMENT {
            return;
        }
        // merge with previous text sibling
        let prev = match place.1 {
            Some(before) => {
                let ch = &self.dom.nodes[place.0].children;
                let idx = ch.iter().position(|&c| c == before).unwrap();
                if idx > 0 {
                    Some(ch[idx - 1])
                } else {
                    None
                }
            }
            None => self.dom.nodes[place.0].children.last().copied(),
        };
        if let Some(p) = prev {
            if let NodeData::Text(t) = &mut self.dom.nodes[p].data {
                t.push_str(s);
                return;
            }
        }
        let n = self.dom.create(NodeData::Text(s.to_string()));
        self.insert_at(place, n);
    }

    fn insert_comment(&mut self, s: &str, parent: Option<usize>) {
        let n = self.dom.create(NodeData::Comment(s.to_string()));
        match parent {
            Some(p) => self.dom.append(p, n),
            None => {
                let place = self.insertion_place(None);
                self.insert_at(place, n);
            }
        }
    }

    fn create_for_token(&mut self, tag: &Tag, ns: Ns) -> usize {
        let mut attrs = tag.attrs.clone();
        let mut name = tag.name.clone();
        match ns {
            Ns::Svg => {
                adjust_svg_attrs(&mut attrs);
                adjust_foreign_attrs(&mut attrs);
                name = svg_tag_adjust(&name).to_string();
            }
            Ns::MathMl => {
                adjust_mathml_attrs(&mut attrs);
                adjust_foreign_attrs(&mut attrs);
            }
            _ => {}
        }
        let id = self.dom.create_element(ns, &name, attrs);
        if ns == Ns::MathMl && name == "annotation-xml" {
            if let Some(enc) = tag.attrs.iter().find(|a| a.name == "encoding") {
                let v = enc.value.to_ascii_lowercase();
                if v == "text/html" || v == "application/xhtml+xml" {
                    if let NodeData::Element { mathml_aixp, .. } = &mut self.dom.nodes[id].data {
                        *mathml_aixp = true;
                    }
                }
            }
        }
        id
    }

    fn insert_element(&mut self, tag: &Tag, ns: Ns) -> usize {
        let place = self.insertion_place(None);
        let id = self.create_for_token(tag, ns);
        // form association is irrelevant for serialization
        self.insert_at(place, id);
        self.open.push(id);
        id
    }

    fn insert_html(&mut self, tag: &Tag) -> usize {
        self.insert_element(tag, Ns::Html)
    }

    fn insert_html_named(&mut self, name: &str) -> usize {
        let tag = Tag { name: name.to_string(), attrs: vec![], self_closing: false };
        self.insert_html(&tag)
    }

    // ---------- active formatting elements ----------
    fn push_afe(&mut self, node: usize, tag: &Tag) {
        // Noah's Ark clause
        let mut count = 0;
        let mut earliest: Option<usize> = None;
        for i in (0..self.afe.len()).rev() {
            match &self.afe[i] {
                Fmt::Marker => break,
                Fmt::Elem(n, t) => {
                    if self.name_of(*n) == tag.name && self.ns_of(*n) == Ns::Html && same_attrs(&t.attrs, &tag.attrs) {
                        count += 1;
                        earliest = Some(i);
                    }
                }
            }
        }
        if count >= 3 {
            self.afe.remove(earliest.unwrap());
        }
        self.afe.push(Fmt::Elem(node, tag.clone()));
    }

    fn reconstruct_afe(&mut self) {
        if self.afe.is_empty() {
            return;
        }
        let last = self.afe.len() - 1;
        match &self.afe[last] {
            Fmt::Marker => return,
            Fmt::Elem(n, _) => {
                if self.open.contains(n) {
                    return;
                }
            }
        }
        let mut i = last;
        loop {
            if i == 0 {
                break;
            }
            i -= 1;
            let stop = match &self.afe[i] {
                Fmt::Marker => true,
                Fmt::Elem(n, _) => self.open.contains(n),
            };
            if stop {
                i += 1;
                break;
            }
        }
        // create
        while i <= last {
            let tag = match &self.afe[i] {
                Fmt::Elem(_, t) => t.clone(),
                Fmt::Marker => unreachable!(),
            };
            let n = self.insert_html(&tag);
            self.afe[i] = Fmt::Elem(n, tag);
            i += 1;
        }
    }

    fn clear_afe_to_marker(&mut self) {
        while let Some(e) = self.afe.pop() {
            if let Fmt::Marker = e {
                return;
            }
        }
    }

    fn afe_position(&self, node: usize) -> Option<usize> {
        self.afe.iter().position(|e| matches!(e, Fmt::Elem(n, _) if *n == node))
    }

    // adoption agency algorithm; returns true if "any other end tag" should be run
    fn adoption_agency(&mut self, subject: &str) -> bool {
        if let Some(c) = self.current() {
            if self.dom.is_html(c, subject) && self.afe_position(c).is_none() {
                self.open.pop();
                return false;
            }
        }
        for _outer in 0..8 {
            // formatting element
            let mut fe_idx: Option<usize> = None;
            for i in (0..self.afe.len()).rev() {
                match &self.afe[i] {
                    Fmt::Marker => break,
                    Fmt::Elem(n, _) => {
                        if self.dom.is_html(*n, subject) {
                            fe_idx = Some(i);
                            break;
                        }
                    }
                }
            }
            let fe_idx = match fe_idx {
                Some(i) => i,
                None => return true,
            };
            let (fe, fe_tag) = match &self.afe[fe_idx] {
                Fmt::Elem(n, t) => (*n, t.clone()),
                _ => unreachable!(),
            };
            let fe_open = match self.open.iter().position(|&n| n == fe) {
                Some(p) => p,
                None => {
                    self.afe.remove(fe_idx);
                    return false;
                }
            };
            if !self.node_in_scope(fe) {
                return false;
            }
            // furthest block
            let mut fb_open: Option<usize> = None;
            for i in fe_open + 1..self.open.len() {
                if self.is_special(self.open[i]) {
                    fb_open = Some(i);
                    break;
                }
            }
            let fb_open = match fb_open {
                None => {
                    self.open.truncate(fe_open);
                    self.afe.remove(fe_idx);
                    return false;
                }
                Some(i) => i,
            };
            let fb = self.open[fb_open];
            let common_ancestor = self.open[fe_open - 1];
            let mut bookmark = fe_idx;
            let mut node_idx = fb_open;
            let mut last_node = fb;
            let mut inner = 0;
            loop {
                inner += 1;
                node_idx -= 1;
                let node = self.open[node_idx];
                if node == fe {
                    break;
                }
                let node_afe = self.afe_position(node);
                if inner > 3 {
                    if let Some(p) = node_afe {
                        self.afe.remove(p);
                        if p < bookmark {
                            bookmark -= 1;
                        }
                        self.open.remove(node_idx);
                        continue;
                    }
                }
                let node_afe = match node_afe {
                    None => {
                        self.open.remove(node_idx);
                        continue;
                    }
                    Some(p) => p,
                };
                let tag = match &self.afe[node_afe] {
                    Fmt::Elem(_, t) => t.clone(),
                    _ => unreachable!(),
                };
                let new_el = self.create_for_token(&tag, Ns::Html);
                self.afe[node_afe] = Fmt::Elem(new_el, tag);
                self.open[node_idx] = new_el;
                let node = new_el;
                if last_node == fb {
                    bookmark = node_afe + 1;
                }
                self.dom.append(node, last_node);
                last_node = node;
            }
            // insert last_node at appropriate place with common ancestor as override
            self.dom.detach(last_node);
            let place = self.insertion_place(Some(common_ancestor));
            self.insert_at(place, last_node);
            let new_el = self.create_for_token(&fe_tag, Ns::Html);
            let children: Vec<usize> = self.dom.nodes[fb].children.clone();
            for c in children {
                self.dom.append(new_el, c);
            }
            self.dom.append(fb, new_el);
            // afe: remove fe, insert new at bookmark
            let cur_fe_idx = self.afe_position(fe).unwrap();
            self.afe.remove(cur_fe_idx);
            if cur_fe_idx < bookmark {
                bookmark -= 1;
            }
            if bookmark > self.afe.len() {
                bookmark = self.afe.len();
            }
            self.afe.insert(bookmark, Fmt::Elem(new_el, fe_tag));
            // open stack
            self.remove_from_open(fe);
            let fb_pos = self.open.iter().position(|&n| n == fb).unwrap();
            self.open.insert(fb_pos + 1, new_el);
        }
        false
    }

    fn reset_insertion_mode(&mut self) {
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let node = self.open[i];
            let last = i == 0;
            let name = self.name_of(node).to_string();
            if self.ns_of(node) != Ns::Html {
                if last {
                    self.mode = Mode::InBody;
                    return;
                }
                continue;
            }
            match name.as_str() {
                "select" => {
                    if !last {
                        let mut j = i;
                        while j > 0 {
                            j -= 1;
                            let anc = self.open[j];
                            if self.dom.is_html(anc, "template") {
                                break;
                            }
                            if self.dom.is_html(anc, "table") {
                                self.mode = Mode::InSelectInTable;
                                return;
                            }
                        }
                    }
                    self.mode = Mode::InSelect;
                    return;
                }
                "td" | "th" if !last => {
                    self.mode = Mode::InCell;
                    return;
                }
                "tr" => {
                    self.mode = Mode::InRow;
                    return;
                }
                "tbody" | "thead" | "tfoot" => {
                    self.mode = Mode::InTableBody;
                    return;
                }
                "caption" => {
                    self.mode = Mode::InCaption;
                    return;
                }
                "colgroup" => {
                    self.mode = Mode::InColumnGroup;
                    return;
                }
                "table" => {
                    self.mode = Mode::InTable;
                    return;
                }
                "template" => {
                    self.mode = *self.template_modes.last().unwrap_or(&Mode::InBody);
                    return;
                }
                "head" if !last => {
                    self.mode = Mode::InHead;
                    return;
                }
                "body" => {
                    self.mode = Mode::InBody;
                    return;
                }
                "frameset" => {
                    self.mode = Mode::InFrameset;
                    return;
                }
                "html" => {
                    if self.head.is_none() {
                        self.mode = Mode::BeforeHead;
                    } else {
                        self.mode = Mode::AfterHead;
                    }
                    return;
                }
                _ => {}
            }
            if last {
                self.mode = Mode::InBody;
                return;
            }
        }
        self.mode = Mode::InBody;
    }

    fn generic_raw_text(&mut self, tag: &Tag, state: State) {
        self.insert_html(tag);
        self.tok.state = state;
        self.orig_mode = self.mode;
        self.mode = Mode::Text;
    }

    fn close_p(&mut self) {
        self.generate_implied_end_tags(Some("p"));
        self.pop_until(&["p"]);
    }

    fn close_p_if_in_button_scope(&mut self) {
        if self.in_button_scope("p") {
            self.close_p();
        }
    }

    // ---------- dispatch ----------
    fn dispatch(&mut self, token: Token) {
        let mut tok = token;
        let mut mode_override: Option<Mode> = None;
        loop {
            let use_foreign = mode_override.is_none() && self.should_use_foreign(&tok);
            let step = if use_foreign {
                self.foreign(tok)
            } else {
                let m = mode_override.take().unwrap_or(self.mode);
                self.step(m, tok)
            };
            match step {
                Step::Done => return,
                Step::Reprocess(m, t) => {
                    tok = t;
                    if m == self.mode {
                        mode_override = None;
                    } else {
                        mode_override = Some(m);
                        // when reprocessing in a "using the rules for" sense; normal reprocess uses self.mode
                    }
                    // A reprocess with explicit mode equal to the mode we just switched to is common
                    if mode_override == Some(self.mode) {
                        mode_override = None;
                    }
                }
                Step::ReprocessForeign(t) => {
                    tok = t;
                    mode_override = None;
                }
            }
        }
    }

    fn should_use_foreign(&self, tok: &Token) -> bool {
        let acn = match self.adjusted_current() {
            None => return false,
            Some(n) => n,
        };
        let ns = self.ns_of(acn);
        if ns == Ns::Html {
            return false;
        }
        if matches!(tok, Token::Eof) {
            return false;
        }
        let name = self.name_of(acn);
        let mathml_text_ip = ns == Ns::MathMl && matches!(name, "mi" | "mo" | "mn" | "ms" | "mtext");
        let html_ip = match &self.dom.nodes[acn].data {
            NodeData::Element { ns: Ns::MathMl, mathml_aixp, .. } => *mathml_aixp,
            NodeData::Element { ns: Ns::Svg, name, .. } => matches!(name.as_str(), "foreignObject" | "desc" | "title"),
            _ => false,
        };
        match tok {
            Token::StartTag(t) => {
                if mathml_text_ip && t.name != "mglyph" && t.name != "malignmark" {
                    return false;
                }
                if ns == Ns::MathMl && name == "annotation-xml" && t.name == "svg" {
                    return false;
                }
                if html_ip {
                    return false;
                }
                true
            }
            Token::Chars(_) | Token::NullChar => !(mathml_text_ip || html_ip),
            _ => true,
        }
    }

    // Rules for parsing tokens in foreign content
    fn foreign(&mut self, tok: Token) -> Step {
        match tok {
            Token::NullChar => {
                self.insert_text("\u{FFFD}");
                Step::Done
            }
            Token::Chars(s) => {
                if !all_ws(&s) {
                    self.frameset_ok = false;
                }
                self.insert_text(&s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => {
                let breakout = matches!(
                    t.name.as_str(),
                    "b" | "big" | "blockquote" | "body" | "br" | "center" | "code" | "dd" | "div" | "dl" | "dt" | "em" | "embed" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "head" | "hr" | "i" | "img" | "li" | "listing" | "menu" | "meta" | "nobr" | "ol" | "p" | "pre" | "ruby" | "s" | "small" | "span" | "strong" | "strike" | "sub" | "sup" | "table" | "tt" | "u" | "ul" | "var"
                ) || (t.name == "font" && t.attrs.iter().any(|a| a.name == "color" || a.name == "face" || a.name == "size"));
                if breakout {
                    while let Some(c) = self.current() {
                        if self.ns_of(c) == Ns::Html || self.is_mathml_text_ip(c) || self.is_html_ip(c) {
                            break;
                        }
                        self.open.pop();
                    }
                    let m = self.mode;
                    return Step::Reprocess(m, Token::StartTag(t));
                }
                let acn = self.adjusted_current().unwrap();
                let ns = self.ns_of(acn);
                let _ = self.insert_element(&t, ns);
                if t.self_closing {
                    self.open.pop();
                }
                Step::Done
            }
            Token::EndTag(t) => {
                // script end tag in svg: just pop
                let mut i = self.open.len() - 1;
                let mut node = self.open[i];
                if self.name_of(node).to_ascii_lowercase() != t.name {
                    // parse error
                }
                loop {
                    if i == 0 {
                        return Step::Done;
                    }
                    if self.name_of(node).to_ascii_lowercase() == t.name {
                        self.pop_until_node(node);
                        return Step::Done;
                    }
                    i -= 1;
                    node = self.open[i];
                    if self.ns_of(node) == Ns::Html {
                        let m = self.mode;
                        return Step::Reprocess(m, Token::EndTag(t)).into_html();
                    }
                }
            }
            Token::Eof => Step::Done,
        }
    }

    fn is_mathml_text_ip(&self, n: usize) -> bool {
        self.ns_of(n) == Ns::MathMl && matches!(self.name_of(n), "mi" | "mo" | "mn" | "ms" | "mtext")
    }

    fn is_html_ip(&self, n: usize) -> bool {
        match &self.dom.nodes[n].data {
            NodeData::Element { ns: Ns::MathMl, mathml_aixp, .. } => *mathml_aixp,
            NodeData::Element { ns: Ns::Svg, name, .. } => matches!(name.as_str(), "foreignObject" | "desc" | "title"),
            _ => false,
        }
    }

    fn step(&mut self, mode: Mode, tok: Token) -> Step {
        match mode {
            Mode::Initial => self.mode_initial(tok),
            Mode::BeforeHtml => self.mode_before_html(tok),
            Mode::BeforeHead => self.mode_before_head(tok),
            Mode::InHead => self.mode_in_head(tok),
            Mode::InHeadNoscript => self.mode_in_head_noscript(tok),
            Mode::AfterHead => self.mode_after_head(tok),
            Mode::InBody => self.mode_in_body(tok),
            Mode::Text => self.mode_text(tok),
            Mode::InTable => self.mode_in_table(tok),
            Mode::InTableText => self.mode_in_table_text(tok),
            Mode::InCaption => self.mode_in_caption(tok),
            Mode::InColumnGroup => self.mode_in_column_group(tok),
            Mode::InTableBody => self.mode_in_table_body(tok),
            Mode::InRow => self.mode_in_row(tok),
            Mode::InCell => self.mode_in_cell(tok),
            Mode::InSelect => self.mode_in_select(tok),
            Mode::InSelectInTable => self.mode_in_select_in_table(tok),
            Mode::InTemplate => self.mode_in_template(tok),
            Mode::AfterBody => self.mode_after_body(tok),
            Mode::InFrameset => self.mode_in_frameset(tok),
            Mode::AfterFrameset => self.mode_after_frameset(tok),
            Mode::AfterAfterBody => self.mode_after_after_body(tok),
            Mode::AfterAfterFrameset => self.mode_after_after_frameset(tok),
        }
    }

    // split leading whitespace from chars token
    fn split_ws(s: &str) -> (String, String) {
        let idx = s.find(|c: char| !is_ws_char(c)).unwrap_or(s.len());
        (s[..idx].to_string(), s[idx..].to_string())
    }

    fn mode_initial(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let (_ws, rest) = Self::split_ws(&s);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.dom.quirks = true;
                self.mode = Mode::BeforeHtml;
                Step::Reprocess(Mode::BeforeHtml, Token::Chars(rest))
            }
            Token::Comment(c) => {
                self.insert_comment(&c, Some(DOCUMENT));
                Step::Done
            }
            Token::Doctype(d) => {
                let n = self.dom.create(NodeData::Doctype {
                    name: d.name.clone().unwrap_or_default(),
                    public_id: d.public_id.clone().unwrap_or_default(),
                    system_id: d.system_id.clone().unwrap_or_default(),
                });
                self.dom.append(DOCUMENT, n);
                if is_quirks(&d) {
                    self.dom.quirks = true;
                }
                self.mode = Mode::BeforeHtml;
                Step::Done
            }
            t => {
                self.dom.quirks = true;
                self.mode = Mode::BeforeHtml;
                Step::Reprocess(Mode::BeforeHtml, t)
            }
        }
    }

    fn mode_before_html(&mut self, tok: Token) -> Step {
        match tok {
            Token::Doctype(_) => Step::Done,
            Token::Comment(c) => {
                self.insert_comment(&c, Some(DOCUMENT));
                Step::Done
            }
            Token::Chars(s) => {
                let (_ws, rest) = Self::split_ws(&s);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.before_html_anything_else(Token::Chars(rest))
            }
            Token::StartTag(t) if t.name == "html" => {
                let n = self.create_for_token(&t, Ns::Html);
                self.dom.append(DOCUMENT, n);
                self.open.push(n);
                self.mode = Mode::BeforeHead;
                Step::Done
            }
            Token::EndTag(t) if !matches!(t.name.as_str(), "head" | "body" | "html" | "br") => Step::Done,
            t => self.before_html_anything_else(t),
        }
    }

    fn before_html_anything_else(&mut self, t: Token) -> Step {
        let n = self.dom.create_element(Ns::Html, "html", vec![]);
        self.dom.append(DOCUMENT, n);
        self.open.push(n);
        self.mode = Mode::BeforeHead;
        Step::Reprocess(Mode::BeforeHead, t)
    }

    fn mode_before_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let (_ws, rest) = Self::split_ws(&s);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.before_head_anything_else(Token::Chars(rest))
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) if t.name == "html" => self.mode_in_body(Token::StartTag(t)),
            Token::StartTag(t) if t.name == "head" => {
                let h = self.insert_html(&t);
                self.head = Some(h);
                self.mode = Mode::InHead;
                Step::Done
            }
            Token::EndTag(t) if !matches!(t.name.as_str(), "head" | "body" | "html" | "br") => Step::Done,
            t => self.before_head_anything_else(t),
        }
    }

    fn before_head_anything_else(&mut self, t: Token) -> Step {
        let h = self.insert_html_named("head");
        self.head = Some(h);
        self.mode = Mode::InHead;
        Step::Reprocess(Mode::InHead, t)
    }

    fn mode_in_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                self.insert_text(&ws);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.in_head_anything_else(Token::Chars(rest))
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => match t.name.as_str() {
                "html" => self.mode_in_body(Token::StartTag(t)),
                "base" | "basefont" | "bgsound" | "link" | "meta" => {
                    self.insert_html(&t);
                    self.open.pop();
                    Step::Done
                }
                "title" => {
                    self.generic_raw_text(&t, State::RcData);
                    Step::Done
                }
                "noscript" if self.scripting => {
                    self.generic_raw_text(&t, State::RawText);
                    Step::Done
                }
                "noframes" | "style" => {
                    self.generic_raw_text(&t, State::RawText);
                    Step::Done
                }
                "noscript" => {
                    self.insert_html(&t);
                    self.mode = Mode::InHeadNoscript;
                    Step::Done
                }
                "script" => {
                    let place = self.insertion_place(None);
                    let n = self.create_for_token(&t, Ns::Html);
                    self.insert_at(place, n);
                    self.open.push(n);
                    self.tok.state = State::ScriptData;
                    self.orig_mode = self.mode;
                    self.mode = Mode::Text;
                    Step::Done
                }
                "template" => {
                    self.insert_html(&t);
                    self.afe.push(Fmt::Marker);
                    self.frameset_ok = false;
                    self.mode = Mode::InTemplate;
                    self.template_modes.push(Mode::InTemplate);
                    Step::Done
                }
                "head" => Step::Done,
                _ => self.in_head_anything_else(Token::StartTag(t)),
            },
            Token::EndTag(t) => match t.name.as_str() {
                "head" => {
                    self.open.pop();
                    self.mode = Mode::AfterHead;
                    Step::Done
                }
                "body" | "html" | "br" => self.in_head_anything_else(Token::EndTag(t)),
                "template" => {
                    if !self.open.iter().any(|&n| self.dom.is_html(n, "template")) {
                        return Step::Done;
                    }
                    self.generate_all_implied_end_tags();
                    self.pop_until(&["template"]);
                    self.clear_afe_to_marker();
                    self.template_modes.pop();
                    self.reset_insertion_mode();
                    Step::Done
                }
                _ => Step::Done,
            },
            t => self.in_head_anything_else(t),
        }
    }

    fn in_head_anything_else(&mut self, t: Token) -> Step {
        self.open.pop();
        self.mode = Mode::AfterHead;
        Step::Reprocess(Mode::AfterHead, t)
    }

    fn mode_in_head_noscript(&mut self, tok: Token) -> Step {
        match tok {
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) if t.name == "html" => self.mode_in_body(Token::StartTag(t)),
            Token::EndTag(t) if t.name == "noscript" => {
                self.open.pop();
                self.mode = Mode::InHead;
                Step::Done
            }
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                if !ws.is_empty() {
                    self.mode_in_head(Token::Chars(ws));
                }
                if rest.is_empty() {
                    return Step::Done;
                }
                self.in_head_noscript_anything_else(Token::Chars(rest))
            }
            Token::Comment(c) => self.mode_in_head(Token::Comment(c)),
            Token::StartTag(t) if matches!(t.name.as_str(), "basefont" | "bgsound" | "link" | "meta" | "noframes" | "style") => self.mode_in_head(Token::StartTag(t)),
            Token::StartTag(t) if matches!(t.name.as_str(), "head" | "noscript") => Step::Done,
            Token::EndTag(t) if t.name != "br" => Step::Done,
            t => self.in_head_noscript_anything_else(t),
        }
    }

    fn in_head_noscript_anything_else(&mut self, t: Token) -> Step {
        self.open.pop();
        self.mode = Mode::InHead;
        Step::Reprocess(Mode::InHead, t)
    }

    fn mode_after_head(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                self.insert_text(&ws);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.after_head_anything_else(Token::Chars(rest))
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => match t.name.as_str() {
                "html" => self.mode_in_body(Token::StartTag(t)),
                "body" => {
                    self.insert_html(&t);
                    self.frameset_ok = false;
                    self.mode = Mode::InBody;
                    Step::Done
                }
                "frameset" => {
                    self.insert_html(&t);
                    self.mode = Mode::InFrameset;
                    Step::Done
                }
                "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template" | "title" => {
                    let head = self.head.unwrap();
                    self.open.push(head);
                    let r = self.mode_in_head(Token::StartTag(t));
                    self.remove_from_open(head);
                    r
                }
                "head" => Step::Done,
                _ => self.after_head_anything_else(Token::StartTag(t)),
            },
            Token::EndTag(t) => match t.name.as_str() {
                "template" => self.mode_in_head(Token::EndTag(t)),
                "body" | "html" | "br" => self.after_head_anything_else(Token::EndTag(t)),
                _ => Step::Done,
            },
            t => self.after_head_anything_else(t),
        }
    }

    fn after_head_anything_else(&mut self, t: Token) -> Step {
        self.insert_html_named("body");
        self.mode = Mode::InBody;
        Step::Reprocess(Mode::InBody, t)
    }

    fn mode_text(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                self.insert_text(&s);
                Step::Done
            }
            Token::NullChar => Step::Done,
            Token::Eof => {
                self.open.pop();
                self.mode = self.orig_mode;
                let m = self.mode;
                Step::Reprocess(m, Token::Eof)
            }
            Token::EndTag(_) => {
                self.open.pop();
                self.mode = self.orig_mode;
                Step::Done
            }
            _ => Step::Done,
        }
    }

    fn any_other_end_tag(&mut self, name: &str) {
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let node = self.open[i];
            if self.dom.is_html(node, name) {
                self.generate_implied_end_tags(Some(name));
                self.open.truncate(i);
                return;
            }
            if self.is_special(node) {
                return;
            }
        }
    }

    fn mode_in_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::NullChar => Step::Done,
            Token::Chars(s) => {
                self.reconstruct_afe();
                self.insert_text(&s);
                if !all_ws(&s) {
                    self.frameset_ok = false;
                }
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => self.in_body_start(t),
            Token::EndTag(t) => self.in_body_end(t),
            Token::Eof => {
                if !self.template_modes.is_empty() {
                    return self.mode_in_template(Token::Eof);
                }
                self.stop = true;
                Step::Done
            }
        }
    }

    fn in_body_start(&mut self, t: Tag) -> Step {
        let name = t.name.clone();
        match name.as_str() {
            "html" => {
                if self.open.iter().any(|&n| self.dom.is_html(n, "template")) {
                    return Step::Done;
                }
                let html = self.open[0];
                if let Some(attrs) = self.dom.attrs_mut(html) {
                    for a in &t.attrs {
                        if !attrs.iter().any(|x| x.name == a.name) {
                            attrs.push(a.clone());
                        }
                    }
                }
                Step::Done
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template" | "title" => self.mode_in_head(Token::StartTag(t)),
            "body" => {
                if self.open.len() < 2 || !self.dom.is_html(self.open[1], "body") || self.open.iter().any(|&n| self.dom.is_html(n, "template")) {
                    return Step::Done;
                }
                self.frameset_ok = false;
                let body = self.open[1];
                if let Some(attrs) = self.dom.attrs_mut(body) {
                    for a in &t.attrs {
                        if !attrs.iter().any(|x| x.name == a.name) {
                            attrs.push(a.clone());
                        }
                    }
                }
                Step::Done
            }
            "frameset" => {
                if self.open.len() < 2 || !self.dom.is_html(self.open[1], "body") {
                    return Step::Done;
                }
                if !self.frameset_ok {
                    return Step::Done;
                }
                let body = self.open[1];
                self.dom.detach(body);
                self.open.truncate(1);
                self.insert_html(&t);
                self.mode = Mode::InFrameset;
                Step::Done
            }
            "address" | "article" | "aside" | "blockquote" | "center" | "details" | "dialog" | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "main" | "menu" | "nav" | "ol" | "p" | "search" | "section" | "summary" | "ul" => {
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                Step::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                self.close_p_if_in_button_scope();
                if self.current_is(&["h1", "h2", "h3", "h4", "h5", "h6"]) {
                    self.open.pop();
                }
                self.insert_html(&t);
                Step::Done
            }
            "pre" | "listing" => {
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                self.ignore_lf = true;
                self.frameset_ok = false;
                Step::Done
            }
            "form" => {
                let in_template = self.open.iter().any(|&n| self.dom.is_html(n, "template"));
                if self.form.is_some() && !in_template {
                    return Step::Done;
                }
                self.close_p_if_in_button_scope();
                let f = self.insert_html(&t);
                if !in_template {
                    self.form = Some(f);
                }
                Step::Done
            }
            "li" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                while i > 0 {
                    i -= 1;
                    let node = self.open[i];
                    if self.dom.is_html(node, "li") {
                        self.generate_implied_end_tags(Some("li"));
                        self.pop_until(&["li"]);
                        break;
                    }
                    if self.is_special(node) && !self.is_html_named(node, &["address", "div", "p"]) {
                        break;
                    }
                }
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                Step::Done
            }
            "dd" | "dt" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                while i > 0 {
                    i -= 1;
                    let node = self.open[i];
                    if self.is_html_named(node, &["dd", "dt"]) {
                        let nm = self.name_of(node).to_string();
                        self.generate_implied_end_tags(Some(&nm));
                        self.pop_until(&[nm.as_str()]);
                        break;
                    }
                    if self.is_special(node) && !self.is_html_named(node, &["address", "div", "p"]) {
                        break;
                    }
                }
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                Step::Done
            }
            "plaintext" => {
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                self.tok.state = State::PlainText;
                Step::Done
            }
            "button" => {
                if self.in_scope("button") {
                    self.generate_implied_end_tags(None);
                    self.pop_until(&["button"]);
                }
                self.reconstruct_afe();
                self.insert_html(&t);
                self.frameset_ok = false;
                Step::Done
            }
            "a" => {
                // look for 'a' in afe after last marker
                let mut found: Option<usize> = None;
                for i in (0..self.afe.len()).rev() {
                    match &self.afe[i] {
                        Fmt::Marker => break,
                        Fmt::Elem(n, _) => {
                            if self.dom.is_html(*n, "a") {
                                found = Some(*n);
                                break;
                            }
                        }
                    }
                }
                if let Some(a) = found {
                    self.adoption_agency("a");
                    if let Some(p) = self.afe_position(a) {
                        self.afe.remove(p);
                    }
                    self.remove_from_open(a);
                }
                self.reconstruct_afe();
                let n = self.insert_html(&t);
                self.push_afe(n, &t);
                Step::Done
            }
            "b" | "big" | "code" | "em" | "font" | "i" | "s" | "small" | "strike" | "strong" | "tt" | "u" => {
                self.reconstruct_afe();
                let n = self.insert_html(&t);
                self.push_afe(n, &t);
                Step::Done
            }
            "nobr" => {
                self.reconstruct_afe();
                if self.in_scope("nobr") {
                    self.adoption_agency("nobr");
                    self.reconstruct_afe();
                }
                let n = self.insert_html(&t);
                self.push_afe(n, &t);
                Step::Done
            }
            "applet" | "marquee" | "object" => {
                self.reconstruct_afe();
                self.insert_html(&t);
                self.afe.push(Fmt::Marker);
                self.frameset_ok = false;
                Step::Done
            }
            "table" => {
                if !self.dom.quirks {
                    self.close_p_if_in_button_scope();
                }
                self.insert_html(&t);
                self.frameset_ok = false;
                self.mode = Mode::InTable;
                Step::Done
            }
            "area" | "br" | "embed" | "img" | "keygen" | "wbr" => {
                self.reconstruct_afe();
                self.insert_html(&t);
                self.open.pop();
                self.frameset_ok = false;
                Step::Done
            }
            "input" => {
                self.reconstruct_afe();
                self.insert_html(&t);
                self.open.pop();
                let hidden = t.attrs.iter().any(|a| a.name == "type" && a.value.eq_ignore_ascii_case("hidden"));
                if !hidden {
                    self.frameset_ok = false;
                }
                Step::Done
            }
            "param" | "source" | "track" => {
                self.insert_html(&t);
                self.open.pop();
                Step::Done
            }
            "hr" => {
                self.close_p_if_in_button_scope();
                self.insert_html(&t);
                self.open.pop();
                self.frameset_ok = false;
                Step::Done
            }
            "image" => {
                let mut t2 = t.clone();
                t2.name = "img".to_string();
                self.in_body_start(t2)
            }
            "textarea" => {
                self.insert_html(&t);
                self.ignore_lf = true;
                self.tok.state = State::RcData;
                self.orig_mode = self.mode;
                self.frameset_ok = false;
                self.mode = Mode::Text;
                Step::Done
            }
            "xmp" => {
                self.close_p_if_in_button_scope();
                self.reconstruct_afe();
                self.frameset_ok = false;
                self.generic_raw_text(&t, State::RawText);
                Step::Done
            }
            "iframe" => {
                self.frameset_ok = false;
                self.generic_raw_text(&t, State::RawText);
                Step::Done
            }
            "noembed" => {
                self.generic_raw_text(&t, State::RawText);
                Step::Done
            }
            "noscript" if self.scripting => {
                self.generic_raw_text(&t, State::RawText);
                Step::Done
            }
            "select" => {
                self.reconstruct_afe();
                self.insert_html(&t);
                self.frameset_ok = false;
                if matches!(self.mode, Mode::InTable | Mode::InCaption | Mode::InTableBody | Mode::InRow | Mode::InCell) {
                    self.mode = Mode::InSelectInTable;
                } else {
                    self.mode = Mode::InSelect;
                }
                Step::Done
            }
            "optgroup" | "option" => {
                if self.current_is(&["option"]) {
                    self.open.pop();
                }
                self.reconstruct_afe();
                self.insert_html(&t);
                Step::Done
            }
            "rb" | "rtc" => {
                if self.in_scope("ruby") {
                    self.generate_implied_end_tags(None);
                }
                self.insert_html(&t);
                Step::Done
            }
            "rp" | "rt" => {
                if self.in_scope("ruby") {
                    self.generate_implied_end_tags(Some("rtc"));
                }
                self.insert_html(&t);
                Step::Done
            }
            "math" => {
                self.reconstruct_afe();
                self.insert_element(&t, Ns::MathMl);
                if t.self_closing {
                    self.open.pop();
                }
                Step::Done
            }
            "svg" => {
                self.reconstruct_afe();
                self.insert_element(&t, Ns::Svg);
                if t.self_closing {
                    self.open.pop();
                }
                Step::Done
            }
            "caption" | "col" | "colgroup" | "frame" | "head" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => Step::Done,
            _ => {
                self.reconstruct_afe();
                self.insert_html(&t);
                Step::Done
            }
        }
    }

    fn in_body_end(&mut self, t: Tag) -> Step {
        let name = t.name.clone();
        match name.as_str() {
            "template" => self.mode_in_head(Token::EndTag(t)),
            "body" => {
                if !self.in_scope("body") {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Done
            }
            "html" => {
                if !self.in_scope("body") {
                    return Step::Done;
                }
                self.mode = Mode::AfterBody;
                Step::Reprocess(Mode::AfterBody, Token::EndTag(t))
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details" | "dialog" | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header" | "hgroup" | "listing" | "main" | "menu" | "nav" | "ol" | "pre" | "search" | "section" | "summary" | "ul" => {
                if !self.in_scope(&name) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&[name.as_str()]);
                Step::Done
            }
            "form" => {
                let in_template = self.open.iter().any(|&n| self.dom.is_html(n, "template"));
                if !in_template {
                    let node = self.form.take();
                    match node {
                        None => return Step::Done,
                        Some(f) => {
                            if !self.node_in_scope(f) {
                                return Step::Done;
                            }
                            self.generate_implied_end_tags(None);
                            self.remove_from_open(f);
                        }
                    }
                } else {
                    if !self.in_scope("form") {
                        return Step::Done;
                    }
                    self.generate_implied_end_tags(None);
                    self.pop_until(&["form"]);
                }
                Step::Done
            }
            "p" => {
                if !self.in_button_scope("p") {
                    self.insert_html_named("p");
                }
                self.close_p();
                Step::Done
            }
            "li" => {
                if !self.in_list_item_scope("li") {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some("li"));
                self.pop_until(&["li"]);
                Step::Done
            }
            "dd" | "dt" => {
                if !self.in_scope(&name) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(Some(&name));
                self.pop_until(&[name.as_str()]);
                Step::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                let hs = ["h1", "h2", "h3", "h4", "h5", "h6"];
                if !self.in_scope_any(&hs) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&hs);
                Step::Done
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small" | "strike" | "strong" | "tt" | "u" => {
                if self.adoption_agency(&name) {
                    self.any_other_end_tag(&name);
                }
                Step::Done
            }
            "applet" | "marquee" | "object" => {
                if !self.in_scope(&name) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&[name.as_str()]);
                self.clear_afe_to_marker();
                Step::Done
            }
            "br" => {
                let t2 = Tag { name: "br".to_string(), attrs: vec![], self_closing: false };
                self.in_body_start(t2)
            }
            _ => {
                self.any_other_end_tag(&name);
                Step::Done
            }
        }
    }

    fn clear_to_table_context(&mut self) {
        while let Some(c) = self.current() {
            if self.is_html_named(c, &["table", "template", "html"]) {
                return;
            }
            self.open.pop();
        }
    }

    fn clear_to_table_body_context(&mut self) {
        while let Some(c) = self.current() {
            if self.is_html_named(c, &["tbody", "tfoot", "thead", "template", "html"]) {
                return;
            }
            self.open.pop();
        }
    }

    fn clear_to_table_row_context(&mut self) {
        while let Some(c) = self.current() {
            if self.is_html_named(c, &["tr", "template", "html"]) {
                return;
            }
            self.open.pop();
        }
    }

    fn mode_in_table(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(_) | Token::NullChar if self.current_is(&["table", "tbody", "template", "tfoot", "thead", "tr"]) => {
                self.pending_table_text.clear();
                self.orig_mode = self.mode;
                self.mode = Mode::InTableText;
                Step::Reprocess(Mode::InTableText, tok)
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => match t.name.as_str() {
                "caption" => {
                    self.clear_to_table_context();
                    self.afe.push(Fmt::Marker);
                    self.insert_html(&t);
                    self.mode = Mode::InCaption;
                    Step::Done
                }
                "colgroup" => {
                    self.clear_to_table_context();
                    self.insert_html(&t);
                    self.mode = Mode::InColumnGroup;
                    Step::Done
                }
                "col" => {
                    self.clear_to_table_context();
                    self.insert_html_named("colgroup");
                    self.mode = Mode::InColumnGroup;
                    Step::Reprocess(Mode::InColumnGroup, Token::StartTag(t))
                }
                "tbody" | "tfoot" | "thead" => {
                    self.clear_to_table_context();
                    self.insert_html(&t);
                    self.mode = Mode::InTableBody;
                    Step::Done
                }
                "td" | "th" | "tr" => {
                    self.clear_to_table_context();
                    self.insert_html_named("tbody");
                    self.mode = Mode::InTableBody;
                    Step::Reprocess(Mode::InTableBody, Token::StartTag(t))
                }
                "table" => {
                    if !self.in_table_scope("table") {
                        return Step::Done;
                    }
                    self.pop_until(&["table"]);
                    self.reset_insertion_mode();
                    let m = self.mode;
                    Step::Reprocess(m, Token::StartTag(t))
                }
                "style" | "script" | "template" => self.mode_in_head(Token::StartTag(t)),
                "input" => {
                    let hidden = t.attrs.iter().any(|a| a.name == "type" && a.value.eq_ignore_ascii_case("hidden"));
                    if !hidden {
                        return self.in_table_anything_else(Token::StartTag(t));
                    }
                    self.insert_html(&t);
                    self.open.pop();
                    Step::Done
                }
                "form" => {
                    if self.form.is_some() || self.open.iter().any(|&n| self.dom.is_html(n, "template")) {
                        return Step::Done;
                    }
                    let f = self.insert_html(&t);
                    self.form = Some(f);
                    self.open.pop();
                    Step::Done
                }
                _ => self.in_table_anything_else(Token::StartTag(t)),
            },
            Token::EndTag(t) => match t.name.as_str() {
                "table" => {
                    if !self.in_table_scope("table") {
                        return Step::Done;
                    }
                    self.pop_until(&["table"]);
                    self.reset_insertion_mode();
                    Step::Done
                }
                "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => Step::Done,
                "template" => self.mode_in_head(Token::EndTag(t)),
                _ => self.in_table_anything_else(Token::EndTag(t)),
            },
            Token::Eof => self.mode_in_body(Token::Eof),
            t => self.in_table_anything_else(t),
        }
    }

    fn in_table_anything_else(&mut self, t: Token) -> Step {
        self.foster = true;
        let r = self.mode_in_body(t);
        self.foster = false;
        // reprocess results should be handled in in-body context; handle inline
        match r {
            Step::Done => Step::Done,
            other => other,
        }
    }

    fn mode_in_table_text(&mut self, tok: Token) -> Step {
        match tok {
            Token::NullChar => Step::Done,
            Token::Chars(s) => {
                let ws = all_ws(&s);
                self.pending_table_text.push((ws, s));
                Step::Done
            }
            t => {
                let pending = std::mem::take(&mut self.pending_table_text);
                let any_non_ws = pending.iter().any(|(ws, _)| !ws);
                if any_non_ws {
                    for (_, s) in pending {
                        self.foster = true;
                        self.mode_in_body(Token::Chars(s));
                        self.foster = false;
                    }
                } else {
                    for (_, s) in pending {
                        self.insert_text(&s);
                    }
                }
                self.mode = self.orig_mode;
                let m = self.mode;
                Step::Reprocess(m, t)
            }
        }
    }

    fn mode_in_caption(&mut self, tok: Token) -> Step {
        match tok {
            Token::EndTag(t) if t.name == "caption" => {
                if !self.in_table_scope("caption") {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&["caption"]);
                self.clear_afe_to_marker();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr") => {
                if !self.in_table_scope("caption") {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&["caption"]);
                self.clear_afe_to_marker();
                self.mode = Mode::InTable;
                Step::Reprocess(Mode::InTable, tok)
            }
            Token::EndTag(ref t) if t.name == "table" => {
                if !self.in_table_scope("caption") {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&["caption"]);
                self.clear_afe_to_marker();
                self.mode = Mode::InTable;
                Step::Reprocess(Mode::InTable, tok)
            }
            Token::EndTag(ref t) if matches!(t.name.as_str(), "body" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr") => Step::Done,
            t => self.mode_in_body(t),
        }
    }

    fn mode_in_column_group(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                self.insert_text(&ws);
                if rest.is_empty() {
                    return Step::Done;
                }
                self.in_colgroup_anything_else(Token::Chars(rest))
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) if t.name == "html" => self.mode_in_body(Token::StartTag(t)),
            Token::StartTag(t) if t.name == "col" => {
                self.insert_html(&t);
                self.open.pop();
                Step::Done
            }
            Token::EndTag(t) if t.name == "colgroup" => {
                if !self.current_is(&["colgroup"]) {
                    return Step::Done;
                }
                self.open.pop();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::EndTag(t) if t.name == "col" => Step::Done,
            Token::StartTag(t) if t.name == "template" => self.mode_in_head(Token::StartTag(t)),
            Token::EndTag(t) if t.name == "template" => self.mode_in_head(Token::EndTag(t)),
            Token::Eof => self.mode_in_body(Token::Eof),
            t => self.in_colgroup_anything_else(t),
        }
    }

    fn in_colgroup_anything_else(&mut self, t: Token) -> Step {
        if !self.current_is(&["colgroup"]) {
            return Step::Done;
        }
        self.open.pop();
        self.mode = Mode::InTable;
        Step::Reprocess(Mode::InTable, t)
    }

    fn mode_in_table_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::StartTag(t) if t.name == "tr" => {
                self.clear_to_table_body_context();
                self.insert_html(&t);
                self.mode = Mode::InRow;
                Step::Done
            }
            Token::StartTag(t) if t.name == "th" || t.name == "td" => {
                self.clear_to_table_body_context();
                self.insert_html_named("tr");
                self.mode = Mode::InRow;
                Step::Reprocess(Mode::InRow, Token::StartTag(t))
            }
            Token::EndTag(t) if matches!(t.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_table_scope(&t.name) {
                    return Step::Done;
                }
                self.clear_to_table_body_context();
                self.open.pop();
                self.mode = Mode::InTable;
                Step::Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead") => self.table_body_exit(tok),
            Token::EndTag(ref t) if t.name == "table" => self.table_body_exit(tok),
            Token::EndTag(ref t) if matches!(t.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" | "tr") => Step::Done,
            t => self.mode_in_table(t),
        }
    }

    fn table_body_exit(&mut self, tok: Token) -> Step {
        if !self.in_table_scope_any(&["tbody", "thead", "tfoot"]) {
            return Step::Done;
        }
        self.clear_to_table_body_context();
        self.open.pop();
        self.mode = Mode::InTable;
        Step::Reprocess(Mode::InTable, tok)
    }

    fn mode_in_row(&mut self, tok: Token) -> Step {
        match tok {
            Token::StartTag(t) if t.name == "th" || t.name == "td" => {
                self.clear_to_table_row_context();
                self.insert_html(&t);
                self.mode = Mode::InCell;
                self.afe.push(Fmt::Marker);
                Step::Done
            }
            Token::EndTag(t) if t.name == "tr" => {
                if !self.in_table_scope("tr") {
                    return Step::Done;
                }
                self.clear_to_table_row_context();
                self.open.pop();
                self.mode = Mode::InTableBody;
                Step::Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr") => self.row_exit(tok),
            Token::EndTag(ref t) if t.name == "table" => self.row_exit(tok),
            Token::EndTag(ref t) if matches!(t.name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_table_scope(&t.name) {
                    return Step::Done;
                }
                if !self.in_table_scope("tr") {
                    return Step::Done;
                }
                self.clear_to_table_row_context();
                self.open.pop();
                self.mode = Mode::InTableBody;
                Step::Reprocess(Mode::InTableBody, tok)
            }
            Token::EndTag(ref t) if matches!(t.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th") => Step::Done,
            t => self.mode_in_table(t),
        }
    }

    fn row_exit(&mut self, tok: Token) -> Step {
        if !self.in_table_scope("tr") {
            return Step::Done;
        }
        self.clear_to_table_row_context();
        self.open.pop();
        self.mode = Mode::InTableBody;
        Step::Reprocess(Mode::InTableBody, tok)
    }

    fn close_cell(&mut self) {
        self.generate_implied_end_tags(None);
        self.pop_until(&["td", "th"]);
        self.clear_afe_to_marker();
        self.mode = Mode::InRow;
    }

    fn mode_in_cell(&mut self, tok: Token) -> Step {
        match tok {
            Token::EndTag(t) if t.name == "td" || t.name == "th" => {
                if !self.in_table_scope(&t.name) {
                    return Step::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&[t.name.as_str()]);
                self.clear_afe_to_marker();
                self.mode = Mode::InRow;
                Step::Done
            }
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr") => {
                if !self.in_table_scope_any(&["td", "th"]) {
                    return Step::Done;
                }
                self.close_cell();
                Step::Reprocess(Mode::InRow, tok)
            }
            Token::EndTag(ref t) if matches!(t.name.as_str(), "body" | "caption" | "col" | "colgroup" | "html") => Step::Done,
            Token::EndTag(ref t) if matches!(t.name.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") => {
                if !self.in_table_scope(&t.name) {
                    return Step::Done;
                }
                self.close_cell();
                Step::Reprocess(Mode::InRow, tok)
            }
            t => self.mode_in_body(t),
        }
    }

    fn mode_in_select(&mut self, tok: Token) -> Step {
        match tok {
            Token::NullChar => Step::Done,
            Token::Chars(s) => {
                self.insert_text(&s);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => match t.name.as_str() {
                "html" => self.mode_in_body(Token::StartTag(t)),
                "option" => {
                    if self.current_is(&["option"]) {
                        self.open.pop();
                    }
                    self.insert_html(&t);
                    Step::Done
                }
                "optgroup" => {
                    if self.current_is(&["option"]) {
                        self.open.pop();
                    }
                    if self.current_is(&["optgroup"]) {
                        self.open.pop();
                    }
                    self.insert_html(&t);
                    Step::Done
                }
                "hr" => {
                    if self.current_is(&["option"]) {
                        self.open.pop();
                    }
                    if self.current_is(&["optgroup"]) {
                        self.open.pop();
                    }
                    self.insert_html(&t);
                    self.open.pop();
                    Step::Done
                }
                "select" => {
                    if !self.in_select_scope("select") {
                        return Step::Done;
                    }
                    self.pop_until(&["select"]);
                    self.reset_insertion_mode();
                    Step::Done
                }
                "input" | "keygen" | "textarea" => {
                    if !self.in_select_scope("select") {
                        return Step::Done;
                    }
                    self.pop_until(&["select"]);
                    self.reset_insertion_mode();
                    let m = self.mode;
                    Step::Reprocess(m, Token::StartTag(t))
                }
                "script" | "template" => self.mode_in_head(Token::StartTag(t)),
                _ => Step::Done,
            },
            Token::EndTag(t) => match t.name.as_str() {
                "optgroup" => {
                    if self.current_is(&["option"]) && self.open.len() >= 2 && self.dom.is_html(self.open[self.open.len() - 2], "optgroup") {
                        self.open.pop();
                    }
                    if self.current_is(&["optgroup"]) {
                        self.open.pop();
                    }
                    Step::Done
                }
                "option" => {
                    if self.current_is(&["option"]) {
                        self.open.pop();
                    }
                    Step::Done
                }
                "select" => {
                    if !self.in_select_scope("select") {
                        return Step::Done;
                    }
                    self.pop_until(&["select"]);
                    self.reset_insertion_mode();
                    Step::Done
                }
                "template" => self.mode_in_head(Token::EndTag(t)),
                _ => Step::Done,
            },
            Token::Eof => self.mode_in_body(Token::Eof),
        }
    }

    fn mode_in_select_in_table(&mut self, tok: Token) -> Step {
        match tok {
            Token::StartTag(ref t) if matches!(t.name.as_str(), "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th") => {
                self.pop_until(&["select"]);
                self.reset_insertion_mode();
                let m = self.mode;
                Step::Reprocess(m, tok)
            }
            Token::EndTag(ref t) if matches!(t.name.as_str(), "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th") => {
                if !self.in_table_scope(&t.name) {
                    return Step::Done;
                }
                self.pop_until(&["select"]);
                self.reset_insertion_mode();
                let m = self.mode;
                Step::Reprocess(m, tok)
            }
            t => self.mode_in_select(t),
        }
    }

    fn mode_in_template(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(_) | Token::NullChar | Token::Comment(_) | Token::Doctype(_) => self.mode_in_body(tok),
            Token::StartTag(ref t) if matches!(t.name.as_str(), "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style" | "template" | "title") => self.mode_in_head(tok),
            Token::EndTag(ref t) if t.name == "template" => self.mode_in_head(tok),
            Token::StartTag(ref t) => {
                let new_mode = match t.name.as_str() {
                    "caption" | "colgroup" | "tbody" | "tfoot" | "thead" => Mode::InTable,
                    "col" => Mode::InColumnGroup,
                    "tr" => Mode::InTableBody,
                    "td" | "th" => Mode::InRow,
                    _ => Mode::InBody,
                };
                self.template_modes.pop();
                self.template_modes.push(new_mode);
                self.mode = new_mode;
                Step::Reprocess(new_mode, tok)
            }
            Token::EndTag(_) => Step::Done,
            Token::Eof => {
                if !self.open.iter().any(|&n| self.dom.is_html(n, "template")) {
                    self.stop = true;
                    return Step::Done;
                }
                self.pop_until(&["template"]);
                self.clear_afe_to_marker();
                self.template_modes.pop();
                self.reset_insertion_mode();
                let m = self.mode;
                Step::Reprocess(m, Token::Eof)
            }
        }
    }

    fn mode_after_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(ref s) if all_ws(s) => self.mode_in_body(tok),
            Token::Comment(c) => {
                let html = self.open[0];
                self.insert_comment(&c, Some(html));
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(ref t) if t.name == "html" => self.mode_in_body(tok),
            Token::EndTag(ref t) if t.name == "html" => {
                self.mode = Mode::AfterAfterBody;
                Step::Done
            }
            Token::Eof => {
                self.stop = true;
                Step::Done
            }
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                if !ws.is_empty() {
                    self.mode_in_body(Token::Chars(ws));
                }
                self.mode = Mode::InBody;
                Step::Reprocess(Mode::InBody, Token::Chars(rest))
            }
            t => {
                self.mode = Mode::InBody;
                Step::Reprocess(Mode::InBody, t)
            }
        }
    }

    fn mode_in_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let ws: String = s.chars().filter(|&c| is_ws_char(c)).collect();
                self.insert_text(&ws);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) => match t.name.as_str() {
                "html" => self.mode_in_body(Token::StartTag(t)),
                "frameset" => {
                    self.insert_html(&t);
                    Step::Done
                }
                "frame" => {
                    self.insert_html(&t);
                    self.open.pop();
                    Step::Done
                }
                "noframes" => self.mode_in_head(Token::StartTag(t)),
                _ => Step::Done,
            },
            Token::EndTag(t) if t.name == "frameset" => {
                if self.open.len() == 1 {
                    return Step::Done;
                }
                self.open.pop();
                if !self.current_is(&["frameset"]) {
                    self.mode = Mode::AfterFrameset;
                }
                Step::Done
            }
            Token::Eof => {
                self.stop = true;
                Step::Done
            }
            _ => Step::Done,
        }
    }

    fn mode_after_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Chars(s) => {
                let ws: String = s.chars().filter(|&c| is_ws_char(c)).collect();
                self.insert_text(&ws);
                Step::Done
            }
            Token::Comment(c) => {
                self.insert_comment(&c, None);
                Step::Done
            }
            Token::Doctype(_) => Step::Done,
            Token::StartTag(t) if t.name == "html" => self.mode_in_body(Token::StartTag(t)),
            Token::EndTag(t) if t.name == "html" => {
                self.mode = Mode::AfterAfterFrameset;
                Step::Done
            }
            Token::StartTag(t) if t.name == "noframes" => self.mode_in_head(Token::StartTag(t)),
            Token::Eof => {
                self.stop = true;
                Step::Done
            }
            _ => Step::Done,
        }
    }

    fn mode_after_after_body(&mut self, tok: Token) -> Step {
        match tok {
            Token::Comment(c) => {
                self.insert_comment(&c, Some(DOCUMENT));
                Step::Done
            }
            Token::Doctype(_) => self.mode_in_body(tok),
            Token::Chars(ref s) if all_ws(s) => self.mode_in_body(tok),
            Token::StartTag(ref t) if t.name == "html" => self.mode_in_body(tok),
            Token::Eof => {
                self.stop = true;
                Step::Done
            }
            Token::Chars(s) => {
                let (ws, rest) = Self::split_ws(&s);
                if !ws.is_empty() {
                    self.mode_in_body(Token::Chars(ws));
                }
                self.mode = Mode::InBody;
                Step::Reprocess(Mode::InBody, Token::Chars(rest))
            }
            t => {
                self.mode = Mode::InBody;
                Step::Reprocess(Mode::InBody, t)
            }
        }
    }

    fn mode_after_after_frameset(&mut self, tok: Token) -> Step {
        match tok {
            Token::Comment(c) => {
                self.insert_comment(&c, Some(DOCUMENT));
                Step::Done
            }
            Token::Doctype(_) => self.mode_in_body(tok),
            Token::Chars(s) => {
                let ws: String = s.chars().filter(|&c| is_ws_char(c)).collect();
                if !ws.is_empty() {
                    self.mode_in_body(Token::Chars(ws));
                }
                Step::Done
            }
            Token::StartTag(ref t) if t.name == "html" => self.mode_in_body(tok),
            Token::StartTag(ref t) if t.name == "noframes" => self.mode_in_head(tok),
            Token::Eof => {
                self.stop = true;
                Step::Done
            }
            _ => Step::Done,
        }
    }
}

impl Step {
    fn into_html(self) -> Step {
        self
    }
}

fn same_attrs(a: &[Attr], b: &[Attr]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    for x in a {
        if !b.iter().any(|y| y.name == x.name && y.value == x.value) {
            return false;
        }
    }
    true
}

fn is_quirks(d: &Doctype) -> bool {
    if d.force_quirks {
        return true;
    }
    if d.name.as_deref() != Some("html") {
        return true;
    }
    let public = d.public_id.as_deref().map(|s| s.to_ascii_lowercase());
    let system = d.system_id.as_deref().map(|s| s.to_ascii_lowercase());
    if let Some(p) = &public {
        if p == "-//w3o//dtd w3 html strict 3.0//en//" || p == "-/w3c/dtd html 4.0 transitional/en" || p == "html" {
            return true;
        }
        const PREFIXES: &[&str] = &[
            "+//silmaril//dtd html pro v0r11 19970101//",
            "-//as//dtd html 3.0 aswedit + extensions//",
            "-//advasoft ltd//dtd html 3.0 aswedit + extensions//",
            "-//ietf//dtd html 2.0 level 1//",
            "-//ietf//dtd html 2.0 level 2//",
            "-//ietf//dtd html 2.0 strict level 1//",
            "-//ietf//dtd html 2.0 strict level 2//",
            "-//ietf//dtd html 2.0 strict//",
            "-//ietf//dtd html 2.0//",
            "-//ietf//dtd html 2.1e//",
            "-//ietf//dtd html 3.0//",
            "-//ietf//dtd html 3.2 final//",
            "-//ietf//dtd html 3.2//",
            "-//ietf//dtd html 3//",
            "-//ietf//dtd html level 0//",
            "-//ietf//dtd html level 1//",
            "-//ietf//dtd html level 2//",
            "-//ietf//dtd html level 3//",
            "-//ietf//dtd html strict level 0//",
            "-//ietf//dtd html strict level 1//",
            "-//ietf//dtd html strict level 2//",
            "-//ietf//dtd html strict level 3//",
            "-//ietf//dtd html strict//",
            "-//ietf//dtd html//",
            "-//metrius//dtd metrius presentational//",
            "-//microsoft//dtd internet explorer 2.0 html strict//",
            "-//microsoft//dtd internet explorer 2.0 html//",
            "-//microsoft//dtd internet explorer 2.0 tables//",
            "-//microsoft//dtd internet explorer 3.0 html strict//",
            "-//microsoft//dtd internet explorer 3.0 html//",
            "-//microsoft//dtd internet explorer 3.0 tables//",
            "-//netscape comm. corp.//dtd html//",
            "-//netscape comm. corp.//dtd strict html//",
            "-//o'reilly and associates//dtd html 2.0//",
            "-//o'reilly and associates//dtd html extended 1.0//",
            "-//o'reilly and associates//dtd html extended relaxed 1.0//",
            "-//sq//dtd html 2.0 hotmetal + extensions//",
            "-//softquad software//dtd hotmetal pro 6.0::19990601::extensions to html 4.0//",
            "-//softquad//dtd hotmetal pro 4.0::19971010::extensions to html 4.0//",
            "-//spyglass//dtd html 2.0 extended//",
            "-//sun microsystems corp.//dtd hotjava html//",
            "-//sun microsystems corp.//dtd hotjava strict html//",
            "-//w3c//dtd html 3 1995-03-24//",
            "-//w3c//dtd html 3.2 draft//",
            "-//w3c//dtd html 3.2 final//",
            "-//w3c//dtd html 3.2//",
            "-//w3c//dtd html 3.2s draft//",
            "-//w3c//dtd html 4.0 frameset//",
            "-//w3c//dtd html 4.0 transitional//",
            "-//w3c//dtd html experimental 19960712//",
            "-//w3c//dtd html experimental 970421//",
            "-//w3c//dtd w3 html//",
            "-//w3o//dtd w3 html 3.0//",
            "-//webtechs//dtd mozilla html 2.0//",
            "-//webtechs//dtd mozilla html//",
        ];
        for pre in PREFIXES {
            if p.starts_with(pre) {
                return true;
            }
        }
        if system.is_none() && (p.starts_with("-//w3c//dtd html 4.01 frameset//") || p.starts_with("-//w3c//dtd html 4.01 transitional//")) {
            return true;
        }
    }
    if let Some(s) = &system {
        if s == "http://www.ibm.com/data/dtd/v11/ibmxhtml1-transitional.dtd" {
            return true;
        }
    }
    false
}

pub fn parse_document(input: &str) -> Dom {
    let tb = TreeBuilder::new(input);
    tb.run()
