fn adjust_foreign_attrs(attrs: &mut Vec<Attr>) {
    for a in attrs.iter_mut() {
        let (ns, prefix, local): (AttrNs, Option<&str>, &str) = match a.name.as_str() {
            "xlink:actuate" => (AttrNs::XLink, Some("xlink"), "actuate"),
            "xlink:arcrole" => (AttrNs::XLink, Some("xlink"), "arcrole"),
            "xlink:href" => (AttrNs::XLink, Some("xlink"), "href"),
            "xlink:role" => (AttrNs::XLink, Some("xlink"), "role"),
            "xlink:show" => (AttrNs::XLink, Some("xlink"), "show"),
            "xlink:title" => (AttrNs::XLink, Some("xlink"), "title"),
            "xlink:type" => (AttrNs::XLink, Some("xlink"), "type"),
            "xml:lang" => (AttrNs::Xml, Some("xml"), "lang"),
            "xml:space" => (AttrNs::Xml, Some("xml"), "space"),
            "xmlns" => (AttrNs::XmlNs, None, "xmlns"),
            "xmlns:xlink" => (AttrNs::XmlNs, Some("xmlns"), "xlink"),
            _ => continue,
        };
        a.ns = ns;
        a.prefix = prefix.map(|s| s.to_string());
        a.name = local.to_string();
    }
}

