// HTML serializer mimicking html5ever's serializer behaviour
use crate::dom::{AttrNs, Dom, NodeData, Ns};

fn escape(out: &mut String, s: &str, attr: bool) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{00A0}' => out.push_str("&nbsp;"),
            '"' if attr => out.push_str("&quot;"),
            '<' if !attr => out.push_str("&lt;"),
            '>' if !attr => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

fn is_void(name: &str) -> bool {
    matches!(
        name,
        "area" | "base" | "basefont" | "bgsound" | "br" | "col" | "embed" | "frame" | "hr" | "img" | "input" | "keygen" | "link" | "meta" | "param" | "source" | "track" | "wbr"
    )
}

pub fn serialize_node(dom: &Dom, id: usize, out: &mut String) {
    match &dom.nodes[id].data {
        NodeData::Document => {
            for &c in &dom.nodes[id].children {
                serialize_node(dom, c, out);
            }
        }
        NodeData::Doctype { name, .. } => {
            out.push_str("<!DOCTYPE ");
            out.push_str(name);
            out.push('>');
        }
        NodeData::Comment(t) => {
            out.push_str("<!--");
            out.push_str(t);
            out.push_str("-->");
        }
        NodeData::Text(t) => {
            let raw = match dom.nodes[id].parent {
                Some(p) => match &dom.nodes[p].data {
                    NodeData::Element { ns: Ns::Html, name, .. } => matches!(
                        name.as_str(),
                        "style" | "script" | "xmp" | "iframe" | "noembed" | "noframes" | "plaintext" | "noscript"
                    ),
                    _ => false,
                },
                None => false,
            };
            if raw {
                out.push_str(t);
            } else {
                escape(out, t, false);
            }
        }
        NodeData::Element { ns, name, attrs, .. } => {
            out.push('<');
            out.push_str(name);
            for a in attrs {
                out.push(' ');
                match a.ns {
                    AttrNs::None => {}
                    AttrNs::Xml => out.push_str("xml:"),
                    AttrNs::XmlNs => {
                        if a.name != "xmlns" {
                            out.push_str("xmlns:");
                        }
                    }
                    AttrNs::XLink => out.push_str("xlink:"),
                }
                out.push_str(&a.name);
                out.push_str("=\"");
                escape(out, &a.value, true);
                out.push('"');
            }
            out.push('>');
            if *ns == Ns::Html && is_void(name) {
                return;
            }
            for &c in &dom.nodes[id].children {
                serialize_node(dom, c, out);
            }
            out.push_str("</");
            out.push_str(name);
            out.push('>');
        }
    }
}

pub fn serialize_document(dom: &Dom) -> String {
    let mut out = String::new();
    serialize_node(dom, crate::dom::DOCUMENT, &mut out);
    out
}

pub fn serialize_children(dom: &Dom, id: usize) -> String {
    let mut out = String::new();
    for &c in &dom.nodes[id].children {
        serialize_node(dom, c, &mut out);
    }
    out
}
