cd /workspace/src && cat > url.rs <<'EOF'
// WHATWG URL parser (subset sufficient for this tool)

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Url {
    pub scheme: String,
    pub username: String,
    pub password: String,
    pub host: Option<String>, // serialized host
    pub port: Option<u16>,
    pub path: Vec<String>,
    pub opaque_path: Option<String>,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

fn is_special(s: &str) -> bool {
    matches!(s, "ftp" | "file" | "http" | "https" | "ws" | "wss")
}

fn default_port(s: &str) -> Option<u16> {
    match s {
        "ftp" => Some(21),
        "http" | "ws" => Some(80),
        "https" | "wss" => Some(443),
        _ => None,
    }
}

fn in_c0_control_set(c: char) -> bool {
    (c as u32) < 0x20 || (c as u32) > 0x7E
}
fn in_fragment_set(c: char) -> bool {
    in_c0_control_set(c) || matches!(c, ' ' | '"' | '<' | '>' | '`')
}
fn in_query_set(c: char) -> bool {
    in_c0_control_set(c) || matches!(c, ' ' | '"' | '#' | '<' | '>')
}
fn in_special_query_set(c: char) -> bool {
    in_query_set(c) || c == '\''
}
fn in_path_set(c: char) -> bool {
    in_query_set(c) || matches!(c, '?' | '^' | '`' | '{' | '}')
}
fn in_userinfo_set(c: char) -> bool {
    in_path_set(c) || matches!(c, '/' | ':' | ';' | '=' | '@' | '[' | '\\' | ']' | '|')
}

fn pct_encode_char(out: &mut String, c: char, set: fn(char) -> bool) {
    if set(c) {
        let mut buf = [0u8; 4];
        for b in c.encode_utf8(&mut buf).bytes() {
            out.push_str(&format!("%{:02X}", b));
        }
    } else {
        out.push(c);
    }
}

pub fn percent_decode(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 0 {
            let h = (b[i + 1] as char).to_digit(16);
            let l = (b[i + 2] as char).to_digit(16);
            if let (Some(h), Some(l)) = (h, l) {
                out.push((h * 16 + l) as u8);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    out
}

fn is_windows_drive_letter(s: &[char], normalized_only: bool) -> bool {
    s.len() == 2 && s[0].is_ascii_alphabetic() && (s[1] == ':' || (!normalized_only && s[1] == '|'))
}

fn starts_with_windows_drive_letter(s: &[char]) -> bool {
    s.len() >= 2 && is_windows_drive_letter(&s[..2], false) && (s.len() == 2 || matches!(s[2], '/' | '\\' | '?' | '#'))
}

fn is_single_dot(s: &str) -> bool {
    s == "." || s.eq_ignore_ascii_case("%2e")
}

fn is_double_dot(s: &str) -> bool {
    matches!(s.to_ascii_lowercase().as_str(), ".." | ".%2e" | "%2e." | "%2e%2e")
}

#[derive(PartialEq, Clone, Copy, Debug)]
enum St {
    SchemeStart,
    Scheme,
    NoScheme,
    SpecialRelativeOrAuthority,
    PathOrAuthority,
    Relative,
    RelativeSlash,
    SpecialAuthoritySlashes,
    SpecialAuthorityIgnoreSlashes,
    Authority,
    Host,
    Port,
    File,
    FileSlash,
    FileHost,
    PathStart,
    Path,
    OpaquePath,
    Query,
    Fragment,
}

#[derive(Debug)]
pub struct ParseError;

impl Url {
    pub fn parse(input: &str) -> Result<Url, ParseError> {
        parse_url(input, None)
    }

    pub fn join(&self, input: &str) -> Result<Url, ParseError> {
        parse_url(input, Some(self))
    }

    pub fn is_special(&self) -> bool {
        is_special(&self.scheme)
    }

    pub fn has_credentials(&self) -> bool {
        !self.username.is_empty() || !self.password.is_empty()
    }

    pub fn path_str(&self) -> String {
        if let Some(p) = &self.opaque_path {
            return p.clone();
        }
        let mut s = String::new();
        if self.host.is_none() && self.path.len() > 1 && self.path[0].is_empty() {
            s.push_str("/.");
        }
        for seg in &self.path {
            s.push('/');
            s.push_str(seg);
        }
        s
    }

    pub fn serialize(&self, exclude_fragment: bool) -> String {
        let mut s = String::new();
        s.push_str(&self.scheme);
        s.push(':');
        if let Some(h) = &self.host {
            s.push_str("//");
            if self.has_credentials() {
                s.push_str(&self.username);
                if !self.password.is_empty() {
                    s.push(':');
                    s.push_str(&self.password);
                }
                s.push('@');
            }
            s.push_str(h);
            if let Some(p) = self.port {
                s.push(':');
                s.push_str(&p.to_string());
            }
        }
        s.push_str(&self.path_str());
        if let Some(q) = &self.query {
            s.push('?');
            s.push_str(q);
        }
        if !exclude_fragment {
            if let Some(f) = &self.fragment {
                s.push('#');
                s.push_str(f);
            }
        }
        s
    }

    pub fn as_str(&self) -> String {
        self.serialize(false)
    }

    pub fn set_fragment(&mut self, f: Option<&str>) {
        match f {
            None => self.fragment = None,
            Some(f) => {
                let mut out = String::new();
                for c in f.chars() {
                    pct_encode_char(&mut out, c, in_fragment_set);
                }
                self.fragment = Some(out);
            }
        }
    }

    pub fn host_str(&self) -> Option<&str> {
        self.host.as_deref()
    }

    pub fn port_or_default(&self) -> Option<u16> {
        self.port.or(default_port(&self.scheme))
    }

    // file URL -> filesystem path
    pub fn to_file_path(&self) -> Option<std::path::PathBuf> {
        if self.scheme != "file" {
            return None;
        }
        match &self.host {
            Some(h) if !h.is_empty() && h != "localhost" => return None,
            _ => {}
        }
        let mut bytes: Vec<u8> = Vec::new();
        for seg in &self.path {
            bytes.push(b'/');
            bytes.extend(percent_decode(seg));
        }
        if bytes.is_empty() {
            bytes.push(b'/');
        }
        use std::os::unix::ffi::OsStringExt;
        Some(std::path::PathBuf::from(std::ffi::OsString::from_vec(bytes)))
    }

    pub fn from_file_path(p: &std::path::Path) -> Url {
        use std::os::unix::ffi::OsStrExt;
        let bytes = p.as_os_str().as_bytes();
        let mut path = vec![];
        for seg in bytes.split(|&b| b == b'/').skip(1) {
            let s = String::from_utf8_lossy(seg);
            let mut out = String::new();
            for c in s.chars() {
                // url crate uses PATH_SEGMENT set plus % for file paths
                if in_path_set(c) || c == '%' || c == '/' {
                    let mut buf = [0u8; 4];
                    for b in c.encode_utf8(&mut buf).bytes() {
                        out.push_str(&format!("%{:02X}", b));
                    }
                } else {
                    out.push(c);
                }
            }
            path.push(out);
        }
        if path.is_empty() {
            path.push(String::new());
        }
        Url {
            scheme: "file".to_string(),
            username: String::new(),
            password: String::new(),
            host: Some(String::new()),
            port: None,
            path,
            opaque_path: None,
            query: None,
            fragment: None,
        }
    }
}

impl std::fmt::Display for Url {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.as_str())
    }
}

fn shorten_path(url: &mut Url) {
    if url.scheme == "file" && url.path.len() == 1 {
        let c: Vec<char> = url.path[0].chars().collect();
        if is_windows_drive_letter(&c, true) {
            return;
        }
    }
    url.path.pop();
}

fn parse_url(input: &str, base: Option<&Url>) -> Result<Url, ParseError> {
    // strip leading/trailing C0 control or space, remove tab/newline
    let trimmed = input.trim_matches(|c: char| (c as u32) <= 0x20);
    let chars: Vec<char> = trimmed.chars().filter(|&c| c != '\t' && c != '\n' && c != '\r').collect();
    let mut url = Url {
        scheme: String::new(),
        username: String::new(),
        password: String::new(),
        host: None,
        port: None,
        path: vec![],
        opaque_path: None,
        query: None,
        fragment: None,
    };
    let mut state = St::SchemeStart;
    let mut buffer = String::new();
    let mut at_sign_seen = false;
    let mut inside_brackets = false;
    let mut password_token_seen = false;
    let mut p: usize = 0;
    let n = chars.len();
    loop {
        let c: Option<char> = if p < n { Some(chars[p]) } else { None };
        match state {
            St::SchemeStart => match c {
                Some(c) if c.is_ascii_alphabetic() => {
                    buffer.push(c.to_ascii_lowercase());
                    state = St::Scheme;
                }
                _ => {
                    state = St::NoScheme;
                    continue; // no increment (p stays)
                }
            },
            St::Scheme => match c {
                Some(c) if c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.' => {
                    buffer.push(c.to_ascii_lowercase());
                }
                Some(':') => {
                    url.scheme = std::mem::take(&mut buffer);
                    if url.scheme == "file" {
                        state = St::File;
                    } else if is_special(&url.scheme) && base.map(|b| b.scheme == url.scheme).unwrap_or(false) {
                        state = St::SpecialRelativeOrAuthority;
                    } else if is_special(&url.scheme) {
                        state = St::SpecialAuthoritySlashes;
                    } else if p + 1 < n && chars[p + 1] == '/' {
                        state = St::PathOrAuthority;
                        p += 1;
                    } else {
                        url.opaque_path = Some(String::new());
                        state = St::OpaquePath;
                    }
                }
                _ => {
                    buffer.clear();
                    state = St::NoScheme;
                    p = 0;
                    continue;
                }
            },
            St::NoScheme => {
                let b = match base {
                    None => return Err(ParseError),
                    Some(b) => b,
                };
                if b.opaque_path.is_some() && c != Some('#') {
                    return Err(ParseError);
                }
                if b.opaque_path.is_some() && c == Some('#') {
                    url.scheme = b.scheme.clone();
                    url.path = b.path.clone();
                    url.opaque_path = b.opaque_path.clone();
                    url.query = b.query.clone();
                    url.fragment = Some(String::new());
                    state = St::Fragment;
                } else if b.scheme != "file" {
                    state = St::Relative;
                    continue;
                } else {
                    state = St::File;
                    continue;
                }
            }
            St::SpecialRelativeOrAuthority => {
                if c == Some('/') && p + 1 < n && chars[p + 1] == '/' {
                    state = St::SpecialAuthorityIgnoreSlashes;
                    p += 1;
                } else {
                    state = St::Relative;
                    continue;
                }
            }
            St::PathOrAuthority => {
                if c == Some('/') {
                    state = St::Authority;
                } else {
                    state = St::Path;
                    continue;
                }
            }
            St::Relative => {
                let b = base.unwrap();
                url.scheme = b.scheme.clone();
                if c == Some('/') {
                    state = St::RelativeSlash;
                } else if url.is_special() && c == Some('\\') {
                    state = St::RelativeSlash;
                } else {
                    url.username = b.username.clone();
                    url.password = b.password.clone();
                    url.host = b.host.clone();
                    url.port = b.port;
                    url.path = b.path.clone();
                    url.query = b.query.clone();
                    if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if c.is_some() {
                        url.query = None;
                        shorten_path(&mut url);
                        state = St::Path;
                        continue;
                    }
                }
            }
            St::RelativeSlash => {
                if url.is_special() && (c == Some('/') || c == Some('\\')) {
                    state = St::SpecialAuthorityIgnoreSlashes;
                } else if c == Some('/') {
                    state = St::Authority;
                } else {
                    let b = base.unwrap();
                    url.username = b.username.clone();
                    url.password = b.password.clone();
                    url.host = b.host.clone();
                    url.port = b.port;
                    state = St::Path;
                    continue;
                }
            }
            St::SpecialAuthoritySlashes => {
                if c == Some('/') && p + 1 < n && chars[p + 1] == '/' {
                    state = St::SpecialAuthorityIgnoreSlashes;
                    p += 1;
                } else {
                    state = St::SpecialAuthorityIgnoreSlashes;
                    continue;
                }
            }
            St::SpecialAuthorityIgnoreSlashes => {
                if c != Some('/') && c != Some('\\') {
                    state = St::Authority;
                    continue;
                }
            }
            St::Authority => {
                if c == Some('@') {
                    if at_sign_seen {
                        buffer.insert_str(0, "%40");
                    }
                    at_sign_seen = true;
                    for bc in buffer.chars() {
                        if bc == ':' && !password_token_seen {
                            password_token_seen = true;
                            continue;
                        }
                        if password_token_seen {
                            pct_encode_char(&mut url.password, bc, in_userinfo_set);
                        } else {
                            pct_encode_char(&mut url.username, bc, in_userinfo_set);
                        }
                    }
                    buffer.clear();
                } else if c.is_none() || c == Some('/') || c == Some('?') || c == Some('#') || (url.is_special() && c == Some('\\')) {
                    if at_sign_seen && buffer.is_empty() {
                        return Err(ParseError);
                    }
                    p -= buffer.chars().count();
                    buffer.clear();
                    state = St::Host;
                    continue;
                } else {
                    buffer.push(c.unwrap());
                }
            }
            St::Host => {
                if c == Some(':') && !inside_brackets {
                    if buffer.is_empty() {
                        return Err(ParseError);
                    }
                    url.host = Some(parse_host(&buffer, !url.is_special())?);
                    buffer.clear();
                    state = St::Port;
                } else if c.is_none() || c == Some('/') || c == Some('?') || c == Some('#') || (url.is_special() && c == Some('\\')) {
                    if url.is_special() && buffer.is_empty() {
                        return Err(ParseError);
                    }
                    url.host = Some(parse_host(&buffer, !url.is_special())?);
                    buffer.clear();
                    state = St::PathStart;
                    continue;
                } else {
                    let ch = c.unwrap();
                    if ch == '[' {
                        inside_brackets = true;
                    }
                    if ch == ']' {
                        inside_brackets = false;
                    }
                    buffer.push(ch);
                }
            }
            St::Port => {
                if let Some(d) = c.filter(|c| c.is_ascii_digit()) {
                    buffer.push(d);
                } else if c.is_none() || c == Some('/') || c == Some('?') || c == Some('#') || (url.is_special() && c == Some('\\')) {
                    if !buffer.is_empty() {
                        let v: u64 = buffer.trim_start_matches('0').parse().unwrap_or(0);
                        if buffer.len() > 10 && buffer.trim_start_matches('0').len() > 5 {
                            return Err(ParseError);
                        }
                        if v > 65535 {
                            return Err(ParseError);
                        }
                        let v = v as u16;
                        if default_port(&url.scheme) == Some(v) {
                            url.port = None;
                        } else {
                            url.port = Some(v);
                        }
                        buffer.clear();
                    }
                    state = St::PathStart;
                    continue;
                } else {
                    return Err(ParseError);
                }
            }
            St::File => {
                url.scheme = "file".to_string();
                url.host = Some(String::new());
                if c == Some('/') || c == Some('\\') {
                    state = St::FileSlash;
                } else if let Some(b) = base.filter(|b| b.scheme == "file") {
                    url.host = b.host.clone();
                    url.path = b.path.clone();
                    url.query = b.query.clone();
                    if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    } else if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    } else if c.is_some() {
                        url.query = None;
                        if !starts_with_windows_drive_letter(&chars[p..]) {
                            shorten_path(&mut url);
                        } else {
                            url.path = vec![];
                        }
                        state = St::Path;
                        continue;
                    }
                } else {
                    state = St::Path;
                    continue;
                }
            }
            St::FileSlash => {
                if c == Some('/') || c == Some('\\') {
                    state = St::FileHost;
                } else {
                    if let Some(b) = base.filter(|b| b.scheme == "file") {
                        url.host = b.host.clone();
                        if !starts_with_windows_drive_letter(&chars[p..]) && !b.path.is_empty() {
                            let c0: Vec<char> = b.path[0].chars().collect();
                            if is_windows_drive_letter(&c0, true) {
                                url.path.push(b.path[0].clone());
                            }
                        }
                    }
                    state = St::Path;
                    continue;
                }
            }
            St::FileHost => {
                if c.is_none() || c == Some('/') || c == Some('\\') || c == Some('?') || c == Some('#') {
                    let bc: Vec<char> = buffer.chars().collect();
                    if is_windows_drive_letter(&bc, false) {
                        state = St::Path;
                    } else if buffer.is_empty() {
                        url.host = Some(String::new());
                        state = St::PathStart;
                    } else {
                        let mut h = parse_host(&buffer, false)?;
                        if h == "localhost" {
                            h = String::new();
                        }
                        url.host = Some(h);
                        buffer.clear();
                        state = St::PathStart;
                    }
                    continue;
                } else {
                    buffer.push(c.unwrap());
                }
            }
            St::PathStart => {
                if url.is_special() {
                    state = St::Path;
                    if c != Some('/') && c != Some('\\') {
                        continue;
                    }
                } else if c == Some('?') {
                    url.query = Some(String::new());
                    state = St::Query;
                } else if c == Some('#') {
                    url.fragment = Some(String::new());
                    state = St::Fragment;
                } else if c.is_some() {
                    state = St::Path;
                    if c != Some('/') {
                        continue;
                    }
                }
            }
            St::Path => {
                let end = c.is_none() || c == Some('/') || (url.is_special() && c == Some('\\')) || c == Some('?') || c == Some('#');
                if end {
                    if is_double_dot(&buffer) {
                        shorten_path(&mut url);
                        if c != Some('/') && !(url.is_special() && c == Some('\\')) {
                            url.path.push(String::new());
                        }
                    } else if is_single_dot(&buffer) && c != Some('/') && !(url.is_special() && c == Some('\\')) {
                        url.path.push(String::new());
                    } else if !is_single_dot(&buffer) {
                        if url.scheme == "file" && url.path.is_empty() {
                            let bc: Vec<char> = buffer.chars().collect();
                            if is_windows_drive_letter(&bc, false) {
                                buffer = format!("{}:", bc[0]);
                            }
                        }
                        url.path.push(std::mem::take(&mut buffer));
                    }
                    buffer.clear();
                    if c == Some('?') {
                        url.query = Some(String::new());
                        state = St::Query;
                    }
                    if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    }
                } else {
                    pct_encode_char(&mut buffer, c.unwrap(), in_path_set);
                }
            }
            St::OpaquePath => {
                if c == Some('?') {
                    url.query = Some(String::new());
                    state = St::Query;
                } else if c == Some('#') {
                    url.fragment = Some(String::new());
                    state = St::Fragment;
                } else if let Some(ch) = c {
                    let op = url.opaque_path.as_mut().unwrap();
                    pct_encode_char(op, ch, in_c0_control_set);
                }
            }
            St::Query => {
                if c == Some('#') || c.is_none() {
                    let special = url.is_special();
                    let q = url.query.get_or_insert_with(String::new);
                    for bc in buffer.chars() {
                        if special {
                            pct_encode_char(q, bc, in_special_query_set);
                        } else {
                            pct_encode_char(q, bc, in_query_set);
                        }
                    }
                    buffer.clear();
                    if c == Some('#') {
                        url.fragment = Some(String::new());
                        state = St::Fragment;
                    }
                } else if let Some(ch) = c {
                    buffer.push(ch);
                }
            }
            St::Fragment => {
                if let Some(ch) = c {
                    let f = url.fragment.get_or_insert_with(String::new);
                    pct_encode_char(f, ch, in_fragment_set);
                }
            }
        }
        if c.is_none() {
            break;
        }
        p += 1;
    }
    // opaque path: strip trailing spaces if no query/fragment (url crate behaviour)
    if let Some(op) = &mut url.opaque_path {
        if url.query.is_none() && url.fragment.is_none() {
            let t = op.trim_end_matches(' ').to_string();
            *op = t;
        }
    }
    Ok(url)
}

fn parse_host(input: &str, not_special: bool) -> Result<String, ParseError> {
    if input.starts_with('[') {
        if !input.ends_with(']') {
            return Err(ParseError);
        }
        let inner = &input[1..input.len() - 1];
        let addr = parse_ipv6(inner).ok_or(ParseError)?;
        return Ok(format!("[{}]", serialize_ipv6(&addr)));
    }
    if not_special {
        // opaque host
        for c in input.chars() {
            if matches!(c, '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '|') {
                return Err(ParseError);
            }
        }
        let mut out = String::new();
        for c in input.chars() {
            pct_encode_char(&mut out, c, in_c0_control_set);
        }
        return Ok(out);
    }
    let decoded = String::from_utf8_lossy(&percent_decode(input)).to_string();
    let ascii = domain_to_ascii(&decoded)?;
    for c in ascii.chars() {
        if matches!(c, '\0' | '\t' | '\n' | '\r' | ' ' | '#' | '/' | ':' | '<' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '|' | '%') || (c as u32) <= 0x1F || c as u32 == 0x7F {
            return Err(ParseError);
        }
    }
    if ends_in_number(&ascii) {
        let v4 = parse_ipv4(&ascii).ok_or(ParseError)?;
        return Ok(format!("{}.{}.{}.{}", v4 >> 24, (v4 >> 16) & 255, (v4 >> 8) & 255, v4 & 255));
    }
    Ok(ascii)
}

fn domain_to_ascii(s: &str) -> Result<String, ParseError> {
    let mapped: String = s
        .chars()
        .map(|c| match c {
            '\u{3002}' | '\u{FF0E}' | '\u{FF61}' => '.',
            _ => c,
        })
        .collect::<String>()
        .to_lowercase();
    if mapped.is_ascii() {
        return Ok(mapped);
    }
    let mut labels = vec![];
    for label in mapped.split('.') {
        if label.is_ascii() {
            labels.push(label.to_string());
        } else {
            labels.push(format!("xn--{}", punycode_encode(label).ok_or(ParseError)?));
        }
    }
    Ok(labels.join("."))
}

fn punycode_encode(input: &str) -> Option<String> {
    let input: Vec<u32> = input.chars().map(|c| c as u32).collect();
    let base = 36u32;
    let tmin = 1u32;
    let tmax = 26u32;
    let skew = 38u32;
    let damp = 700u32;
    let mut n = 128u32;
    let mut delta = 0u32;
    let mut bias = 72u32;
    let mut output = String::new();
    for &c in &input {
        if c < 128 {
            output.push(char::from_u32(c).unwrap());
        }
    }
    let b = output.len() as u32;
    let mut h = b;
    if b > 0 {
        output.push('-');
    }
    let digit = |d: u32| -> char {
        if d < 26 {
            (b'a' + d as u8) as char
        } else {
            (b'0' + (d - 26) as u8) as char
        }
    };
    let adapt = |mut delta: u32, numpoints: u32, first: bool| -> u32 {
        delta = if first { delta / damp } else { delta / 2 };
        delta += delta / numpoints;
        let mut k = 0;
        while delta > ((base - tmin) * tmax) / 2 {
            delta /= base - tmin;
            k += base;
        }
        k + (((base - tmin + 1) * delta) / (delta + skew))
    };
    while (h as usize) < input.len() {
        let m = *input.iter().filter(|&&c| c >= n).min()?;
        delta = delta.checked_add((m - n).checked_mul(h + 1)?)?;
        n = m;
        for &c in &input {
            if c < n {
                delta = delta.checked_add(1)?;
            }
            if c == n {
                let mut q = delta;
                let mut k = base;
                loop {
                    let t = if k <= bias { tmin } else if k >= bias + tmax { tmax } else { k - bias };
                    if q < t {
                        break;
                    }
                    output.push(digit(t + (q - t) % (base - t)));
                    q = (q - t) / (base - t);
                    k += base;
                }
                output.push(digit(q));
                bias = adapt(delta, h + 1, h == b);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    Some(output)
}

fn ends_in_number(s: &str) -> bool {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") {
        if parts.len() == 1 {
            return false;
        }
        parts.pop();
    }
    let last = parts.last().unwrap();
    if !last.is_empty() && last.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }
    parse_ipv4_number(last).is_some()
}

fn parse_ipv4_number(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let (digits, radix) = if s.len() >= 2 && (s.starts_with("0x") || s.starts_with("0X")) {
        (&s[2..], 16)
    } else if s.len() >= 2 && s.starts_with('0') {
        (&s[1..], 8)
    } else {
        (s, 10)
    };
    if digits.is_empty() {
        return Some(0);
    }
    let mut v: u64 = 0;
    for c in digits.chars() {
        let d = c.to_digit(radix)? as u64;
        v = v.saturating_mul(radix as u64).saturating_add(d);
        if v > u32::MAX as u64 * 256 {
            v = u32::MAX as u64 * 256;
        }
    }
    Some(v)
}

fn parse_ipv4(s: &str) -> Option<u32> {
    let mut parts: Vec<&str> = s.split('.').collect();
    if parts.last() == Some(&"") && parts.len() > 1 {
        parts.pop();
    }
    if parts.len() > 4 {
        return None;
    }
    let mut nums = vec![];
    for p in &parts {
        nums.push(parse_ipv4_number(p)?);
    }
    for (i, &n) in nums.iter().enumerate() {
        if n > 255 && i != nums.len() - 1 {
            return None;
        }
    }
    let last = *nums.last().unwrap();
    if last >= 256u64.pow((5 - nums.len()) as u32) {
        return None;
    }
    let mut ipv4: u64 = last;
    for (i, &n) in nums.iter().take(nums.len() - 1).enumerate() {
        ipv4 += n * 256u64.pow((3 - i) as u32);
    }
    Some(ipv4 as u32)
}

fn parse_ipv6(s: &str) -> Option<[u16; 8]> {
    let mut addr = [0u16; 8];
    let chars: Vec<char> = s.chars().collect();
    let mut piece = 0usize;
    let mut compress: Option<usize> = None;
    let mut p = 0usize;
    let n = chars.len();
    if p < n && chars[p] == ':' {
        if p + 1 >= n || chars[p + 1] != ':' {
            return None;
        }
        p += 2;
        piece += 1;
        compress = Some(piece);
    }
    while p < n {
        if piece == 8 {
            return None;
        }
        if chars[p] == ':' {
            if compress.is_some() {
                return None;
            }
            p += 1;
            piece += 1;
            compress = Some(piece);
            continue;
        }
        let mut value: u32 = 0;
        let mut length = 0;
        while length < 4 && p < n && chars[p].is_ascii_hexdigit() {
            value = value * 16 + chars[p].to_digit(16).unwrap();
            p += 1;
            length += 1;
        }
        if p < n && chars[p] == '.' {
            if length == 0 {
                return None;
            }
            p -= length;
            if piece > 6 {
                return None;
            }
            let mut numbers_seen = 0;
            while p < n {
                let mut ipv4_piece: Option<u32> = None;
                if numbers_seen > 0 {
                    if chars[p] == '.' && numbers_seen < 4 {
                        p += 1;
                    } else {
                        return None;
                    }
                }
                if p >= n || !chars[p].is_ascii_digit() {
                    return None;
                }
                while p < n && chars[p].is_ascii_digit() {
                    let num = chars[p].to_digit(10).unwrap();
                    match ipv4_piece {
                        None => ipv4_piece = Some(num),
                        Some(0) => return None,
                        Some(v) => ipv4_piece = Some(v * 10 + num),
                    }
                    if ipv4_piece.unwrap() > 255 {
                        return None;
                    }
                    p += 1;
                }
                addr[piece] = (addr[piece] as u32 * 0x100 + ipv4_piece.unwrap()) as u16;
                numbers_seen += 1;
                if numbers_seen == 2 || numbers_seen == 4 {
                    piece += 1;
                }
            }
            if numbers_seen != 4 {
                return None;
            }
            break;
        } else if p < n && chars[p] == ':' {
            p += 1;
            if p >= n {
                return None;
            }
        } else if p < n {
            return None;
        }
        addr[piece] = value as u16;
        piece += 1;
    }
    if let Some(c) = compress {
        let mut swaps = piece - c;
        piece = 7;
        while piece != 0 && swaps > 0 {
            addr.swap(piece, c + swaps - 1);
            piece -= 1;
            swaps -= 1;
        }
    } else if piece != 8 {
        return None;
    }
    Some(addr)
}

fn serialize_ipv6(addr: &[u16; 8]) -> String {
    // find longest run of zeros (len > 1)
    let mut best_start = None;
    let mut best_len = 1;
    let mut i = 0;
    while i < 8 {
        if addr[i] == 0 {
            let start = i;
            while i < 8 && addr[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len > best_len {
                best_len = len;
                best_start = Some(start);
            }
        } else {
            i += 1;
        }
    }
    let mut out = String::new();
    let mut ignore0 = false;
    let mut i = 0;
    while i < 8 {
        if ignore0 && addr[i] == 0 {
            i += 1;
            continue;
        }
        ignore0 = false;
        if best_start == Some(i) {
            out.push_str(if i == 0 { "::" } else { ":" });
            ignore0 = true;
            i += 1;
            continue;
        }
        out.push_str(&format!("{:x}", addr[i]));
        if i != 7 {
            out.push(':');
        }
        i += 1;
    }
    out
}
