// CSS tokenizer modelled after the `cssparser` crate's tokenizer.

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IDHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number { has_sign: bool, value: f32 },
    Percentage { has_sign: bool, unit_value: f32 },
    Dimension { has_sign: bool, value: f32, unit: String },
    WhiteSpace(String),
    Comment(String), // full slice
