// CSS tokenizer modelled after the `cssparser` crate's tokenizer.

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IDHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number { has_sign: bool, value: f32 },
    Percentage { has_sign: bool, unit_value: f32 },
    Dimension { has_sign: bool, value: f32, unit: String },
    WhiteSpace(String),
    Comment(String), // full slice
    Colon,
    Semicolon,
    Comma,
    IncludeMatch,
    DashMatch,
    PrefixMatch,
    SuffixMatch,
    SubstringMatch,
    CDO,
    CDC,
    Function(String),
    ParenthesisBlock,
    SquareBracketBlock,
    CurlyBracketBlock,
    BadUrl,
    BadString,
    CloseParenthesis,
    CloseSquareBracket,
    CloseCurlyBracket,
}

pub struct CssTokenizer {
    s: Vec<char>,
    pos: usize,
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || !c.is_ascii()
}

fn is_name_char(c: char) -> bool {
    is_name_start(c) || c.is_ascii_digit() || c == '-'
}

fn is_newline(c: char) -> bool {
    c == '\n' || c == '\r' || c == '\x0C'
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t' || is_newline(c)
}

impl CssTokenizer {
    pub fn new(s: &str) -> CssTokenizer {
        CssTokenizer { s: s.chars().collect(), pos: 0 }
    }

    fn at(&self, off: usize) -> Option<char> {
        self.s.get(self.pos + off).copied()
    }

    fn valid_escape_at(&self, off: usize) -> bool {
        self.at(off) == Some('\\') && match self.at(off + 1) {
            None => false,
            Some(c) => !is_newline(c),
        }
    }

    fn starts_ident_at(&self, off: usize) -> bool {
        match self.at(off) {
            Some('-') => match self.at(off + 1) {
                Some(c) if is_name_start(c) || c == '-' => true,
                Some('\\') => self.valid_escape_at(off + 1),
                _ => false,
            },
            Some(c) if is_name_start(c) => true,
            Some('\\') => self.valid_escape_at(off),
            _ => false,
        }
    }

    fn consume_escape(&mut self) -> char {
        // assumes '\\' already consumed
        match self.at(0) {
            None => '\u{FFFD}',
            Some(c) if c.is_ascii_hexdigit() => {
                let mut v: u32 = 0;
                let mut n = 0;
                while n < 6 {
                    match self.at(0) {
                        Some(c) if c.is_ascii_hexdigit() => {
                            v = v * 16 + c.to_digit(16).unwrap();
                            self.pos += 1;
                            n += 1;
                        }
                        _ => break,
                    }
                }
                // consume single whitespace
                match self.at(0) {
                    Some(' ') | Some('\t') | Some('\n') | Some('\x0C') => self.pos += 1,
                    Some('\r') => {
                        self.pos += 1;
                        if self.at(0) == Some('\n') {
                            self.pos += 1;
                        }
                    }
                    _ => {}
                }
                if v == 0 || v > 0x10FFFF || (0xD800..=0xDFFF).contains(&v) {
                    '\u{FFFD}'
                } else {
                    char::from_u32(v).unwrap_or('\u{FFFD}')
                }
            }
            Some(c) => {
                self.pos += 1;
                if c == '\0' {
                    '\u{FFFD}'
                } else {
                    c
                }
            }
        }
    }

    fn consume_name(&mut self) -> String {
        let mut out = String::new();
        loop {
            match self.at(0) {
                Some(c) if is_name_char(c) => {
                    out.push(c);
                    self.pos += 1;
                }
                Some('\0') => {
                    out.push('\u{FFFD}');
                    self.pos += 1;
                }
                Some('\\') if self.valid_escape_at(0) => {
                    self.pos += 1;
                    out.push(self.consume_escape());
                }
                _ => break,
            }
        }
        out
    }

    fn consume_numeric(&mut self) -> Tok {
        let (has_sign, sign) = match self.at(0) {
            Some('-') => (true, -1.0f64),
            Some('+') => (true, 1.0f64),
            _ => (false, 1.0f64),
        };
        if has_sign {
            self.pos += 1;
        }
        let mut integral: f64 = 0.0;
        while let Some(d) = self.at(0).and_then(|c| c.to_digit(10)) {
            integral = integral * 10.0 + d as f64;
            self.pos += 1;
        }
        let mut fractional: f64 = 0.0;
        if self.at(0) == Some('.') && matches!(self.at(1), Some(c) if c.is_ascii_digit()) {
            self.pos += 1;
            let mut factor = 0.1;
            while let Some(d) = self.at(0).and_then(|c| c.to_digit(10)) {
                fractional += d as f64 * factor;
                factor *= 0.1;
                self.pos += 1;
            }
        }
        let mut value = sign * (integral + fractional);
        if matches!(self.at(0), Some('e') | Some('E')) {
            let ok = matches!(self.at(1), Some(c) if c.is_ascii_digit())
                || (matches!(self.at(1), Some('+') | Some('-')) && matches!(self.at(2), Some(c) if c.is_ascii_digit()));
            if ok {
                self.pos += 1;
                let (has_esign, esign) = match self.at(0) {
                    Some('-') => (true, -1.0f64),
                    Some('+') => (true, 1.0f64),
                    _ => (false, 1.0f64),
                };
                if has_esign {
                    self.pos += 1;
                }
                let mut exponent: f64 = 0.0;
                while let Some(d) = self.at(0).and_then(|c| c.to_digit(10)) {
                    exponent = exponent * 10.0 + d as f64;
                    self.pos += 1;
                }
                value *= f64::powf(10.0, esign * exponent);
            }
        }
        if self.at(0) == Some('%') {
            self.pos += 1;
            return Tok::Percentage { has_sign, unit_value: (value / 100.0) as f32 };
        }
        let v = value as f32;
        if self.starts_ident_at(0) {
            let unit = self.consume_name();
            Tok::Dimension { has_sign, value: v, unit }
        } else {
            Tok::Number { has_sign, value: v }
        }
    }

    fn consume_string(&mut self, quote: char) -> Tok {
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.at(0) {
                None => return Tok::QuotedString(out),
                Some(c) if c == quote => {
                    self.pos += 1;
                    return Tok::QuotedString(out);
                }
                Some(c) if is_newline(c) => return Tok::BadString,
                Some('\\') => {
                    self.pos += 1;
                    match self.at(0) {
                        None => {}
                        Some('\n') | Some('\x0C') => self.pos += 1,
                        Some('\r') => {
                            self.pos += 1;
                            if self.at(0) == Some('\n') {
                                self.pos += 1;
                            }
                        }
                        Some(_) => out.push(self.consume_escape()),
                    }
                }
                Some('\0') => {
                    out.push('\u{FFFD}');
                    self.pos += 1;
                }
                Some(c) => {
                    out.push(c);
                    self.pos += 1;
                }
            }
        }
    }

    fn consume_bad_url_remnants(&mut self) {
        loop {
            match self.at(0) {
                None => return,
                Some(')') => {
                    self.pos += 1;
                    return;
                }
                Some('\\') => {
                    self.pos += 1;
                    if self.at(0).is_some() {
                        self.pos += 1;
                    }
                }
                _ => self.pos += 1,
            }
        }
    }

    fn consume_unquoted_url(&mut self) -> Tok {
        let mut out = String::new();
        // skip whitespace
        while matches!(self.at(0), Some(c) if is_ws(c)) {
            self.pos += 1;
        }
        loop {
            match self.at(0) {
                None => return Tok::UnquotedUrl(out),
                Some(')') => {
                    self.pos += 1;
                    return Tok::UnquotedUrl(out);
                }
                Some(c) if is_ws(c) => {
                    while matches!(self.at(0), Some(c) if is_ws(c)) {
                        self.pos += 1;
                    }
                    match self.at(0) {
                        None => return Tok::UnquotedUrl(out),
                        Some(')') => {
                            self.pos += 1;
                            return Tok::UnquotedUrl(out);
                        }
                        _ => {
                            self.consume_bad_url_remnants();
                            return Tok::BadUrl;
                        }
                    }
                }
                Some('"') | Some('\'') | Some('(') => {
                    self.consume_bad_url_remnants();
                    return Tok::BadUrl;
                }
                Some(c) if (c as u32) <= 8 || c as u32 == 0x0B || ((c as u32) >= 0x0E && (c as u32) <= 0x1F) || c as u32 == 0x7F => {
                    self.consume_bad_url_remnants();
                    return Tok::BadUrl;
                }
                Some('\\') => {
                    if self.valid_escape_at(0) {
                        self.pos += 1;
                        out.push(self.consume_escape());
                    } else {
                        self.consume_bad_url_remnants();
                        return Tok::BadUrl;
                    }
                }
                Some('\0') => {
                    out.push('\u{FFFD}');
                    self.pos += 1;
                }
                Some(c) => {
                    out.push(c);
                    self.pos += 1;
                }
            }
        }
    }

    fn consume_ident_like(&mut self) -> Tok {
        let name = self.consume_name();
        if self.at(0) == Some('(') {
            self.pos += 1;
            if name.eq_ignore_ascii_case("url") {
                // look ahead past whitespace for a quote
                let mut off = 0;
                while matches!(self.at(off), Some(c) if is_ws(c)) {
                    off += 1;
                }
                if matches!(self.at(off), Some('"') | Some('\'')) {
                    return Tok::Function(name);
                }
                return self.consume_unquoted_url();
            }
            return Tok::Function(name);
        }
        Tok::Ident(name)
    }

    pub fn next(&mut self) -> Option<Tok> {
        let c = self.at(0)?;
        let start = self.pos;
        let t = match c {
            c if is_ws(c) => {
                while matches!(self.at(0), Some(c) if is_ws(c)) {
                    self.pos += 1;
                }
                Tok::WhiteSpace(self.s[start..self.pos].iter().collect())
            }
            '"' | '\'' => self.consume_string(c),
            '#' => {
                if matches!(self.at(1), Some(c) if is_name_char(c)) || self.valid_escape_at(1) || self.at(1) == Some('\0') {
                    self.pos += 1;
                    let is_id = self.starts_ident_at(0);
                    let name = self.consume_name();
                    if is_id {
                        Tok::IDHash(name)
                    } else {
                        Tok::Hash(name)
                    }
                } else {
                    self.pos += 1;
                    Tok::Delim('#')
                }
            }
            '$' => {
                if self.at(1) == Some('=') {
                    self.pos += 2;
                    Tok::SuffixMatch
                } else {
                    self.pos += 1;
                    Tok::Delim('$')
                }
            }
            '(' => {
                self.pos += 1;
                Tok::ParenthesisBlock
            }
            ')' => {
                self.pos += 1;
                Tok::CloseParenthesis
            }
            '*' => {
                if self.at(1) == Some('=') {
                    self.pos += 2;
                    Tok::SubstringMatch
                } else {
                    self.pos += 1;
                    Tok::Delim('*')
                }
            }
            '+' => {
                if matches!(self.at(1), Some(c) if c.is_ascii_digit()) || (self.at(1) == Some('.') && matches!(self.at(2), Some(c) if c.is_ascii_digit())) {
                    self.consume_numeric()
                } else {
                    self.pos += 1;
                    Tok::Delim('+')
                }
            }
            ',' => {
                self.pos += 1;
                Tok::Comma
            }
            '-' => {
                if matches!(self.at(1), Some(c) if c.is_ascii_digit()) || (self.at(1) == Some('.') && matches!(self.at(2), Some(c) if c.is_ascii_digit())) {
                    self.consume_numeric()
                } else if self.at(1) == Some('-') && self.at(2) == Some('>') {
                    self.pos += 3;
                    Tok::CDC
                } else if self.starts_ident_at(0) {
                    self.consume_ident_like()
                } else {
                    self.pos += 1;
                    Tok::Delim('-')
                }
            }
            '.' => {
                if matches!(self.at(1), Some(c) if c.is_ascii_digit()) {
                    self.consume_numeric()
                } else {
                    self.pos += 1;
                    Tok::Delim('.')
                }
            }
            '/' => {
                if self.at(1) == Some('*') {
                    self.pos += 2;
                    loop {
                        match self.at(0) {
                            None => break,
                            Some('*') if self.at(1) == Some('/') => {
                                self.pos += 2;
                                break;
                            }
                            _ => self.pos += 1,
                        }
                    }
                    Tok::Comment(self.s[start..self.pos].iter().collect())
                } else {
                    self.pos += 1;
                    Tok::Delim('/')
                }
            }
            '0'..='9' => self.consume_numeric(),
            ':' => {
                self.pos += 1;
                Tok::Colon
            }
            ';' => {
                self.pos += 1;
                Tok::Semicolon
            }
            '<' => {
                if self.at(1) == Some('!') && self.at(2) == Some('-') && self.at(3) == Some('-') {
                    self.pos += 4;
                    Tok::CDO
                } else {
                    self.pos += 1;
                    Tok::Delim('<')
                }
            }
            '@' => {
                if self.starts_ident_at(1) {
                    self.pos += 1;
                    Tok::AtKeyword(self.consume_name())
                } else {
                    self.pos += 1;
                    Tok::Delim('@')
                }
            }
            '[' => {
                self.pos += 1;
                Tok::SquareBracketBlock
            }
            '\\' => {
                if self.valid_escape_at(0) {
                    self.consume_ident_like()
                } else {
                    self.pos += 1;
                    Tok::Delim('\\')
                }
            }
            ']' => {
                self.pos += 1;
                Tok::CloseSquareBracket
            }
            '^' => {
                if self.at(1) == Some('=') {
                    self.pos += 2;
                    Tok::PrefixMatch
                } else {
                    self.pos += 1;
                    Tok::Delim('^')
                }
            }
            '{' => {
                self.pos += 1;
                Tok::CurlyBracketBlock
            }
            '|' => {
                if self.at(1) == Some('=') {
                    self.pos += 2;
                    Tok::DashMatch
                } else {
                    self.pos += 1;
                    Tok::Delim('|')
                }
            }
            '}' => {
                self.pos += 1;
                Tok::CloseCurlyBracket
            }
            '~' => {
                if self.at(1) == Some('=') {
                    self.pos += 2;
                    Tok::IncludeMatch
                } else {
                    self.pos += 1;
                    Tok::Delim('~')
                }
            }
            c if is_name_start(c) => self.consume_ident_like(),
            '\0' => self.consume_ident_like(),
            c => {
                self.pos += 1;
                Tok::Delim(c)
            }
        };
        Some(t)
    }
}

// Token tree: blocks contain nested tokens
#[derive(Debug, Clone)]
pub enum Node {
    Tok(Tok),
    // opening token (Function/ParenthesisBlock/...) and its contents
    Block(Tok, Vec<Node>),
}

pub fn parse_tree(css: &str) -> Vec<Node> {
    let mut t = CssTokenizer::new(css);
    let mut stack: Vec<(Tok, Vec<Node>)> = vec![];
    let mut root: Vec<Node> = vec![];
    while let Some(tok) = t.next() {
        let closes = |open: &Tok, tok: &Tok| -> bool {
            match open {
                Tok::Function(_) | Tok::ParenthesisBlock => *tok == Tok::CloseParenthesis,
                Tok::SquareBracketBlock => *tok == Tok::CloseSquareBracket,
                Tok::CurlyBracketBlock => *tok == Tok::CloseCurlyBracket,
                _ => false,
            }
        };
        if let Some((open, _)) = stack.last() {
            if closes(open, &tok) {
                let (open, children) = stack.pop().unwrap();
                let node = Node::Block(open, children);
                match stack.last_mut() {
                    Some((_, c)) => c.push(node),
                    None => root.push(node),
                }
                continue;
            }
        }
        match tok {
            Tok::Function(_) | Tok::ParenthesisBlock | Tok::SquareBracketBlock | Tok::CurlyBracketBlock => {
                stack.push((tok, vec![]));
            }
            _ => {
                let node = Node::Tok(tok);
                match stack.last_mut() {
                    Some((_, c)) => c.push(node),
                    None => root.push(node),
                }
            }
        }
    }
    while let Some((open, children)) = stack.pop() {
        let node = Node::Block(open, children);
        match stack.last_mut() {
            Some((_, c)) => c.push(node),
            None => root.push(node),
        }
    }
    root
}

fn hex_escape(b: u8, out: &mut String) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    out.push('\\');
    if b > 0x0F {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0F) as usize] as char);
    } else {
        out.push(HEX[b as usize] as char);
    }
    out.push(' ');
}

pub fn serialize_name(value: &str, out: &mut String) {
    for c in value.chars() {
        match c {
            '0'..='9' | 'A'..='Z' | 'a'..='z' | '_' | '-' => out.push(c),
            '\0' => out.push('\u{FFFD}'),
            c if !c.is_ascii() => out.push(c),
            c if (c as u32 >= 1 && c as u32 <= 0x1F) || c as u32 == 0x7F => hex_escape(c as u8, out),
            c => {
                out.push('\\');
                out.push(c);
            }
        }
    }
}

pub fn serialize_identifier(value: &str, out: &mut String) {
    if value.is_empty() {
        return;
    }
    if let Some(rest) = value.strip_prefix("--") {
        out.push_str("--");
        serialize_name(rest, out);
    } else if value == "-" {
        out.push_str("\\-");
    } else {
        let mut v = value;
        if v.starts_with('-') {
            out.push('-');
            v = &v[1..];
        }
        if let Some(c) = v.chars().next() {
            if c.is_ascii_digit() {
                hex_escape(c as u8, out);
                v = &v[1..];
            }
        }
        serialize_name(v, out);
    }
}

pub fn serialize_string(value: &str, out: &mut String) {
    out.push('"');
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\0' => out.push('\u{FFFD}'),
            c if (c as u32 >= 1 && c as u32 <= 0x1F) || c as u32 == 0x7F => hex_escape(c as u8, out),
            c => out.push(c),
        }
    }
    out.push('"');
}

pub fn format_quoted_string(s: &str) -> String {
    let mut out = String::new();
    serialize_string(s, &mut out);
    out
}

pub fn format_ident(s: &str) -> String {
    let mut out = String::new();
    serialize_identifier(s, &mut out);
    out.trim_end().to_string()
}
