pub fn detect_media_type(data: &[u8], url: &Url) -> String {
    for (magic, mt) in MAGIC {
        if data.starts_with(magic) {
            return mt.to_string();
        }
    }
    detect_media_type_by_file_name(&url.path_str())
}

pub fn detect_media_type_by_file_name(path: &str) -> String {
    let lower = path.to_ascii_lowercase();
    for (ext, mt) in EXTS {
        if lower.ends_with(&format!(".{}", ext)) {
            return mt.to_string();
        }
    }
    String::new()
}

pub fn is_plaintext_media_type(mt: &str) -> bool {
    let m = mt.to_ascii_lowercase();
    m.starts_with("text/") || matches!(m.as_str(), "application/javascript" | "application/json" | "image/svg+xml")
}

