// Misc helpers: base64, data URLs, media type detection, hashing

use crate::url::{percent_decode, Url};

const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn base64_encode(data: &[u8]) -> String {
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(B64[((n >> 18) & 63) as usize] as char);
        out.push(B64[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            out.push(B64[((n >> 6) & 63) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(B64[(n & 63) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

fn b64_val(c: u8) -> Option<u32> {
    match c {
        b'A'..=b'Z' => Some((c - b'A') as u32),
        b'a'..=b'z' => Some((c - b'a' + 26) as u32),
        b'0'..=b'9' => Some((c - b'0' + 52) as u32),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

// Strict decoding (padding required, canonical trailing bits)
pub fn base64_decode(input: &[u8]) -> Option<Vec<u8>> {
    if input.len() % 4 != 0 {
        return None;
    }
    let mut out = Vec::with_capacity(input.len() / 4 * 3);
    let nchunks = input.len() / 4;
    for (ci, chunk) in input.chunks(4).enumerate() {
        let last = ci == nchunks - 1;
        let mut pad = 0;
        let mut vals = [0u32; 4];
        for i in 0..4 {
            if chunk[i] == b'=' {
                if !last || i < 2 {
                    return None;
                }
                pad += 1;
                vals[i] = 0;
            } else {
                if pad > 0 {
                    return None;
                }
                vals[i] = b64_val(chunk[i])?;
            }
        }
        let n = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        out.push((n >> 16) as u8);
        if pad < 2 {
            out.push((n >> 8) as u8);
        } else if (n >> 8) & 0xFF != 0 {
            return None;
        }
        if pad < 1 {
            out.push(n as u8);
        } else if n & 0xFF != 0 {
            return None;
        }
    }
    Some(out)
}

pub fn create_data_url(media_type: &str, charset: &str, data: &[u8], final_url: &Url) -> Url {
    let _ = final_url;
    let mut s = String::from("data:");
    s.push_str(media_type);
    if !charset.is_empty() {
        s.push_str(";charset=");
        s.push_str(charset);
    }
    s.push_str(";base64,");
    s.push_str(&base64_encode(data));
    Url::parse(&s).unwrap_or_else(|_| Url::parse("data:,").unwrap())
}

// returns (media_type, charset, data)
pub fn parse_data_url(url: &Url) -> (String, String, Vec<u8>) {
    let path = url.path_str();
    let (header, data_part) = match path.find(',') {
        Some(i) => (&path[..i], &path[i + 1..]),
        None => (path.as_str(), ""),
    };
    let mut parts = header.split(';');
    let mut media_type = parts.next().unwrap_or("").to_string();
    let mut charset = String::new();
    let mut is_base64 = false;
    for p in parts {
        if p.eq_ignore_ascii_case("base64") {
            is_base64 = true;
        } else if p.len() >= 8 && p[..8].eq_ignore_ascii_case("charset=") {
            charset = p[8..].to_string();
        }
    }
    if media_type.is_empty() {
        media_type = "text/plain".to_string();
    }
    let decoded = percent_decode(data_part);
    let data = if is_base64 {
        base64_decode(&decoded).unwrap_or_default()
    } else {
        decoded
    };
    (media_type, charset, data)
}

