}

pub fn check_integrity(data: &[u8], integrity: &str) -> bool {
    if let Some(h) = integrity.strip_prefix("sha256-") {
        base64_encode(&sha256(data)) == h
    } else if let Some(h) = integrity.strip_prefix("sha384-") {
        base64_encode(&sha384(data)) == h
    } else if let Some(h) = integrity.strip_prefix("sha512-") {
        base64_encode(&sha512(data)) == h
    } else {
        false
    }
}
