    pub quiet: bool,
    pub timeout: Option<u64>,
    pub user_agent: Option<String>,
    pub no_video: bool,
    pub target: String,
}

fn display(d: &Def) -> String {
    match d.value_name {
        Some(v) => format!("--{} <{}>", d.long, v),
        None => format!("--{}", d.long),
    }
}

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && *ac == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut bi = 0;
        for (i, ac) in a.iter().enumerate() {
            if a_flags[i] {
                while bi < b_len {
                    let j = bi;
                    bi += 1;
                    if !b_flags[j] {
                        continue;
                    }
                    if *ac != b[j] {
                        transpositions += 1;
                    }
                    break;
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64) + (matches as f64 / b_len as f64) + ((matches - transpositions) as f64 / matches as f64)) / 3.0
    }
}

struct Parser {
    bin: String,
    used: Vec<usize>, // indices into DEFS in order of first use
    present: Vec<bool>,
    args: Args,
}

fn fail(msg: String) -> ! {
    eprint!("{}", msg);
    std::process::exit(2);
}

impl Parser {
    fn usage_used(&self, used: &[usize]) -> String {
        if used.is_empty() {
            return format!("Usage: {} [OPTIONS] <TARGET>", self.bin);
        }
        let mut s = format!("Usage: {}", self.bin);
        for &u in used {
            s.push(' ');
            s.push_str(&display(&DEFS[u]));
        }
        s.push_str(" <TARGET>");
        s
    }

    fn usage_required(&self) -> String {
        // used for missing-required error
        let mut s = format!("Usage: {}", self.bin);
        for &u in &self.used {
            s.push(' ');
            s.push_str(&display(&DEFS[u]));
        }
        s.push_str(" <TARGET>");
        s
    }

    fn mark_used(&mut self, i: usize) {
        if !self.used.contains(&i) {
            self.used.push(i);
        }
    }

    fn err_unknown(&self, arg: &str, suggestion: Option<&str>, usage: String) -> ! {
        let mut s = format!("error: unexpected argument '{}' found\n\n", arg);
        match suggestion {
            Some(sug) => s.push_str(&format!("  tip: a similar argument exists: '{}'\n\n", sug)),
            None => s.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", arg, arg)),
        }
        s.push_str(&usage);
        s.push_str("\n\nFor more information, try '--help'.\n");
        fail(s)
    }

    fn err_value_required(&self, d: &Def) -> ! {
        fail(format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n", display(d)))
    }

    fn err_multiple(&self, d: &Def) -> ! {
        fail(format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.\n",
            display(d),
            self.usage_used(&[])
        ))
    }

    fn print_help(&self) -> ! {
        let h = include_str!("help.txt").replace("Usage: executable ", &format!("Usage: {} ", self.bin));
        print!("{}", h);
        std::process::exit(0);
    }

    fn print_version(&self) -> ! {
        println!("monolith 2.11.0");
        std::process::exit(0);
    }

    fn react(&mut self, i: usize, value: Option<String>) {
        let d = &DEFS[i];
        match d.kind {
            Kind::Help => self.print_help(),
            Kind::Version => self.print_version(),
            Kind::Flag | Kind::Set => {
                if self.present[i] {
                    self.err_multiple(d);
                }
            }
            Kind::Append => {}
        }
        self.present[i] = true;
        self.mark_used(i);
        let v = value.unwrap_or_default();
        let a = &mut self.args;
        match d.id {
            "no_audio" => a.no_audio = true,
            "base_url" => a.base_url = Some(v),
            "blacklist_domains" => a.blacklist_domains = true,
            "no_css" => a.no_css = true,
            "cookie_file" => a.cookie_file = Some(v),
            "domain" => a.domains.push(v),
            "ignore_errors" => a.ignore_errors = true,
            "encoding" => a.encoding = Some(v),
            "no_frames" => a.no_frames = true,
            "no_fonts" => a.no_fonts = true,
            "no_images" => a.no_images = true,
            "isolate" => a.isolate = true,
            "no_js" => a.no_js = true,
            "insecure" => a.insecure = true,
            "mhtml" => a.mhtml = true,
            "no_metadata" => a.no_metadata = true,
            "unwrap_noscript" => a.unwrap_noscript = true,
            "output" => a.output = Some(v),
            "quiet" => a.quiet = true,
            "timeout" => {
                match parse_u64(&v) {
                    Ok(n) => a.timeout = Some(n),
                    Err(e) => fail(format!("error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n", v, display(d), e)),
                }
            }
            "user_agent" => a.user_agent = Some(v),
            "no_video" => a.no_video = true,
            _ => {}
        }
    }

    fn suggest(&self, name: &str) -> Option<usize> {
        let mut cands: Vec<(f64, String, usize)> = vec![];
        for (i, d) in DEFS.iter().enumerate() {
            let c = jaro(name, d.long);
            if c > 0.7 {
                cands.push((c, d.long.to_string(), i));
            }
        }
        cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap().then(a.1.cmp(&b.1)));
        cands.pop().map(|c| c.2)
    }

    fn unknown_long(&mut self, name: &str) -> ! {
        let arg = format!("--{}", name);
        match self.suggest(name) {
            Some(i) => {
                let mut used = self.used.clone();
                if !used.contains(&i) {
                    used.push(i);
                }
                let u = self.usage_used(&used);
                self.err_unknown(&arg, Some(&format!("--{}", DEFS[i].long)), u)
            }
            None => {
                let u = self.usage_used(&self.used.clone());
                self.err_unknown(&arg, None, u)
            }
        }
    }
}

fn parse_u64(s: &str) -> Result<u64, &'static str> {
    if s.is_empty() {
        return Err("cannot parse integer from empty string");
    }
    let digits = s.strip_prefix('+').unwrap_or(s);
    if digits.is_empty() {
        return Err("invalid digit found in string");
    }
    let mut v: u64 = 0;
    let mut overflow = false;
    for c in digits.chars() {
        let d = match c.to_digit(10) {
            Some(d) => d as u64,
            None => return Err("invalid digit found in string"),
        };
        match v.checked_mul(10).and_then(|x| x.checked_add(d)) {
            Some(x) => v = x,
            None => overflow = true,
        }
    }
    if overflow {
        return Err("number too large to fit in target type");
    }
    Ok(v)
}

fn find_long(name: &str) -> Option<usize> {
    DEFS.iter().position(|d| d.long == name)
}

fn find_short(c: char) -> Option<usize> {
    DEFS.iter().position(|d| d.short == c)
}

fn looks_like_flag(a: &str) -> bool {
    a.starts_with('-') && a.len() > 1
}

pub fn parse() -> Args {
    let raw: Vec<String> = std::env::args_os().map(|s| s.to_string_lossy().to_string()).collect();
    let bin = raw
        .first()
        .map(|s| std::path::Path::new(s).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| s.clone()))
        .unwrap_or_else(|| "monolith".to_string());
    let mut p = Parser { bin, used: vec![], present: vec![false; DEFS.len()], args: Args::default() };
    let mut target: Option<String> = None;
    let mut trailing = false;
    let mut pending: Option<usize> = None;
    let mut i = 1;
    while i < raw.len() {
        let arg = raw[i].clone();
        i += 1;
        if let Some(pd) = pending {
            if trailing || !looks_like_flag(&arg) {
                pending = None;
                p.react(pd, Some(arg));
                continue;
            }
            // next arg looks like a flag: check it's known
            if arg == "--" {
                p.err_value_required(&DEFS[pd]);
            }
            if let Some(name) = arg.strip_prefix("--") {
                let n = name.split('=').next().unwrap();
                if find_long(n).is_none() {
                    p.unknown_long(n);
                }
            } else {
                let c = arg[1..].chars().next().unwrap();
                if find_short(c).is_none() {
                    let u = p.usage_used(&[]);
                    p.err_unknown(&format!("-{}", c), None, u);
                }
            }
            p.err_value_required(&DEFS[pd]);
        }
        if !trailing && arg == "--" {
            trailing = true;
            continue;
        }
        if !trailing && arg.starts_with("--") {
            let body = &arg[2..];
            let (name, value) = match body.find('=') {
                Some(k) => (&body[..k], Some(body[k + 1..].to_string())),
                None => (body, None),
            };
            let idx = match find_long(name) {
                Some(x) => x,
                None => p.unknown_long(name),
            };
            let d = &DEFS[idx];
            match d.kind {
                Kind::Flag | Kind::Help | Kind::Version => {
                    if let Some(v) = value {
                        let usage = if p.present[idx] {
                            let mut s = format!("Usage: {} <", p.bin);
                            let parts: Vec<String> = DEFS.iter().filter(|d| d.kind != Kind::Help && d.kind != Kind::Version).map(display).collect();
                            s.push_str(&parts.join("|"));
                            s.push_str("|TARGET>");
                            s
                        } else {
                            let mut used = p.used.clone();
                            used.push(idx);
                            p.usage_used(&used)
                        };
                        fail(format!(
                            "error: unexpected value '{}' for '{}' found; no more were expected\n\n{}\n\nFor more information, try '--help'.\n",
                            v,
                            display(d),
                            usage
                        ));
                    }
                    p.react(idx, None);
                }
                _ => match value {
                    Some(v) => p.react(idx, Some(v)),
                    None => pending = Some(idx),
                },
            }
            continue;
        }
        if !trailing && arg.starts_with('-') && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                let idx = match find_short(c) {
                    Some(x) => x,
                    None => {
                        let u = p.usage_used(&[]);
                        p.err_unknown(&format!("-{}", c), None, u);
                    }
                };
                let d = &DEFS[idx];
                match d.kind {
                    Kind::Flag | Kind::Help | Kind::Version => {
                        p.react(idx, None);
                        j += 1;
                    }
                    _ => {
                        let mut rest: String = chars[j + 1..].iter().collect();
                        let had_eq = rest.starts_with('=');
                        if had_eq {
                            rest = rest[1..].to_string();
                        }
                        if !rest.is_empty() || had_eq {
                            p.react(idx, Some(rest));
                        } else {
                            pending = Some(idx);
                        }
                        break;
                    }
                }
            }
            continue;
        }
        // positional
        if target.is_none() {
            target = Some(arg);
        } else {
            let u = p.usage_used(&[]);
            fail(format!("error: unexpected argument '{}' found\n\n{}\n\nFor more information, try '--help'.\n", arg, u));
        }
    }
    if let Some(pd) = pending {
        p.err_value_required(&DEFS[pd]);
    }
    match target {
        Some(t) => p.args.target = t,
        None => {
            let u = p.usage_required();
            fail(format!("error: the following required arguments were not provided:\n  <TARGET>\n\n{}\n\nFor more information, try '--help'.\n", u));
        }
    }
    p.args
}
EOF
echo ok"}

