    fn unknown_long(&mut self, name: &str) -> ! {
        let arg = format!("--{}", name);
        match self.suggest(name) {
            Some(i) => {
                let mut used = self.used.clone();
                if !used.contains(&i) {
                    used.push(i);
                }
                let u = self.usage_used(&used);
                self.err_unknown(&arg, Some(&format!("--{}", DEFS[i].long)), u)
            }
            None => {
                let u = self.usage_used(&self.used.clone());
                self.err_unknown(&arg, None, u)
            }
        }
    }
}

fn parse_u64(s: &str) -> Result<u64, &'static str> {
    if s.is_empty() {
        return Err("cannot parse integer from empty string");
    }
    let digits = s.strip_prefix('+').unwrap_or(s);
    if digits.is_empty() {
        return Err("invalid digit found in string");
    }
    let mut v: u64 = 0;
    let mut overflow = false;
    for c in digits.chars() {
        let d = match c.to_digit(10) {
            Some(d) => d as u64,
            None => return Err("invalid digit found in string"),
        };
        match v.checked_mul(10).and_then(|x| x.checked_add(d)) {
            Some(x) => v = x,
            None => overflow = true,
        }
    }
    if overflow {
        return Err("number too large to fit in target type");
    }
    Ok(v)
}

fn find_long(name: &str) -> Option<usize> {
    DEFS.iter().position(|d| d.long == name)
}

fn find_short(c: char) -> Option<usize> {
    DEFS.iter().position(|d| d.short == c)
}

fn looks_like_flag(a: &str) -> bool {
    a.starts_with('-') && a.len() > 1
}

pub fn parse() -> Args {
    let raw: Vec<String> = std::env::args_os().map(|s| s.to_string_lossy().to_string()).collect();
    let bin = raw
        .first()
        .map(|s| std::path::Path::new(s).file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_else(|| s.clone()))
        .unwrap_or_else(|| "monolith".to_string());
    let mut p = Parser { bin, used: vec![], present: vec![false; DEFS.len()], args: Args::default() };
    let mut target: Option<String> = None;
    let mut trailing = false;
    let mut pending: Option<usize> = None;
    let mut i = 1;
    while i < raw.len() {
        let arg = raw[i].clone();
        i += 1;
        if let Some(pd) = pending {
            if trailing || !looks_like_flag(&arg) {
                pending = None;
                p.react(pd, Some(arg));
                continue;
            }
            // next arg looks like a flag: check it's known
            if arg == "--" {
                p.err_value_required(&DEFS[pd]);
            }
            if let Some(name) = arg.strip_prefix("--") {
                let n = name.split('=').next().unwrap();
                if find_long(n).is_none() {
                    p.unknown_long(n);
                }
            } else {
                let c = arg[1..].chars().next().unwrap();
                if find_short(c).is_none() {
                    let u = p.usage_used(&[]);
                    p.err_unknown(&format!("-{}", c), None, u);
                }
            }
            p.err_value_required(&DEFS[pd]);
        }
        if !trailing && arg == "--" {
            trailing = true;
            continue;
        }
        if !trailing && arg.starts_with("--") {
            let body = &arg[2..];
            let (name, value) = match body.find('=') {
                Some(k) => (&body[..k], Some(body[k + 1..].to_string())),
                None => (body, None),
            };
            let idx = match find_long(name) {
                Some(x) => x,
                None => p.unknown_long(name),
            };
            let d = &DEFS[idx];
            match d.kind {
                Kind::Flag | Kind::Help | Kind::Version => {
                    if let Some(v) = value {
                        let usage = if p.present[idx] {
                            let mut s = format!("Usage: {} <", p.bin);
                            let parts: Vec<String> = DEFS.iter().filter(|d| d.kind != Kind::Help && d.kind != Kind::Version).map(display).collect();
                            s.push_str(&parts.join("|"));
                            s.push_str("|TARGET>");
                            s
                        } else {
                            let mut used = p.used.clone();
                            used.push(idx);
                            p.usage_used(&used)
                        };
                        fail(format!(
                            "error: unexpected value '{}' for '{}' found; no more were expected\n\n{}\n\nFor more information, try '--help'.\n",
                            v,
                            display(d),
                            usage
                        ));
                    }
                    p.react(idx, None);
                }
                _ => match value {
                    Some(v) => p.react(idx, Some(v)),
                    None => pending = Some(idx),
                },
            }
            continue;
        }
        if !trailing && arg.starts_with('-') && arg != "-" {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                let idx = match find_short(c) {
                    Some(x) => x,
                    None => {
                        let u = p.usage_used(&[]);
                        p.err_unknown(&format!("-{}", c), None, u);
                    }
                };
                let d = &DEFS[idx];
                match d.kind {
                    Kind::Flag | Kind::Help | Kind::Version => {
                        p.react(idx, None);
                        j += 1;
                    }
                    _ => {
                        let mut rest: String = chars[j + 1..].iter().collect();
                        let had_eq = rest.starts_with('=');
                        if had_eq {
                            rest = rest[1..].to_string();
                        }
                        if !rest.is_empty() || had_eq {
                            p.react(idx, Some(rest));
                        } else {
                            pending = Some(idx);
                        }
                        break;
                    }
                }
            }
            continue;
        }
        // positional
        if target.is_none() {
            target = Some(arg);
        } else {
            let u = p.usage_used(&[]);
            fail(format!("error: unexpected argument '{}' found\n\n{}\n\nFor more information, try '--help'.\n", arg, u));
        }
    }
    if let Some(pd) = pending {
        p.err_value_required(&DEFS[pd]);
    }
    match target {
        Some(t) => p.args.target = t,
        None => {
            let u = p.usage_required();
            fail(format!("error: the following required arguments were not provided:\n  <TARGET>\n\n{}\n\nFor more information, try '--help'.\n", u));
        }
    }
    p.args
}
