pub fn for_label(label: &str) -> Option<Enc> {
    let l = label.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\x0C' || c == '\r').to_ascii_lowercase();
    let name = LABELS.iter().find(|(k, _)| *k == l).map(|(_, v)| *v)?;
    Some(match name {
        "UTF-8" => Enc::Utf8,
        "UTF-16LE" => Enc::Utf16Le,
        "UTF-16BE" => Enc::Utf16Be,
        "GBK" => Enc::Gbk,
        "gb18030" => Enc::Gb18030,
        "Big5" => Enc::Big5,
        "EUC-JP" => Enc::EucJp,
        "ISO-2022-JP" => Enc::Iso2022Jp,
        "Shift_JIS" => Enc::ShiftJis,
        "EUC-KR" => Enc::EucKr,
        "replacement" => Enc::Replacement,
        "x-user-defined" => Enc::XUserDefined,
        n => Enc::Single(SBCS.iter().position(|(k, _)| *k == n)?),
    })
}

fn decode_utf8_lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

// Decode with BOM sniffing (like encoding_rs::Encoding::decode)
pub fn decode(enc: Enc, bytes: &[u8]) -> String {
    if bytes.starts_with(b"\xEF\xBB\xBF") {
        return decode_utf8_lossy(&bytes[3..]);
    }
    if bytes.starts_with(b"\xFF\xFE") {
        return decode_utf16(&bytes[2..], false);
    }
    if bytes.starts_with(b"\xFE\xFF") {
        return decode_utf16(&bytes[2..], true);
    }
    decode_without_bom(enc, bytes)
}

pub fn decode_without_bom(enc: Enc, bytes: &[u8]) -> String {
    match enc {
        Enc::Utf8 => decode_utf8_lossy(bytes),
        Enc::Utf16Le => decode_utf16(bytes, false),
        Enc::Utf16Be => decode_utf16(bytes, true),
        Enc::Single(i) => {
            let tbl = &SBCS[i].1;
            let mut s = String::with_capacity(bytes.len());
            for &b in bytes {
                if b < 0x80 {
                    s.push(b as char);
                } else {
                    s.push(char::from_u32(tbl[(b - 0x80) as usize] as u32).unwrap_or('\u{FFFD}'));
                }
            }
            s
        }
        Enc::XUserDefined => bytes.iter().map(|&b| if b < 0x80 { b as char } else { char::from_u32(0xF780 + b as u32 - 0x80).unwrap() }).collect(),
        Enc::Replacement => {
            if bytes.is_empty() {
                String::new()
            } else {
                "\u{FFFD}".to_string()
            }
        }
        _ => crate::cjk::decode(enc, bytes),
    }
}

fn decode_utf16(bytes: &[u8], be: bool) -> String {
    let mut units = vec![];
    let mut i = 0;
    while i + 1 < bytes.len() {
        let u = if be { u16::from_be_bytes([bytes[i], bytes[i + 1]]) } else { u16::from_le_bytes([bytes[i], bytes[i + 1]]) };
        units.push(u);
        i += 2;
    }
    let mut s: String = char::decode_utf16(units.into_iter()).map(|r| r.unwrap_or('\u{FFFD}')).collect();
    if bytes.len() % 2 == 1 {
        s.push('\u{FFFD}');
    }
    s
}

fn push_ncr(out: &mut Vec<u8>, c: char) {
    out.extend_from_slice(format!("&#{};", c as u32).as_bytes());
}

pub fn encode(enc: Enc, s: &str) -> Vec<u8> {
    match enc {
        Enc::Utf8 | Enc::Utf16Le | Enc::Utf16Be | Enc::Replacement => s.as_bytes().to_vec(),
        Enc::Single(i) => {
            let tbl = &SBCS[i].1;
            let mut out = Vec::with_capacity(s.len());
            for c in s.chars() {
                if (c as u32) < 0x80 {
                    out.push(c as u8);
                } else {
                    match tbl.iter().position(|&v| v as u32 == c as u32 && v != 0xFFFD) {
                        Some(p) => out.push(0x80 + p as u8),
                        None => push_ncr(&mut out, c),
                    }
                }
            }
            out
        }
        Enc::XUserDefined => {
            let mut out = vec![];
            for c in s.chars() {
                let u = c as u32;
                if u < 0x80 {
                    out.push(u as u8);
                } else if (0xF780..=0xF7FF).contains(&u) {
                    out.push((u - 0xF780 + 0x80) as u8);
                } else {
                    push_ncr(&mut out, c);
                }
            }
            out
        }
        _ => crate::cjk::encode(enc, s),
    }
}
