fn domain_matches(domain: &str, pattern: &str) -> bool {
    // pattern may start with '.' to match subdomains
    let d = domain.trim_end_matches('.').to_ascii_lowercase();
    let p = pattern.trim_end_matches('.').to_ascii_lowercase();
    if p.starts_with('.') {
        let base = &p[1..];
        d == base || d.ends_with(&p)
    } else {
        d == p
    }
}

pub fn parse_content_type(ct: &str) -> (String, String) {
    let mut parts = ct.split(';');
    let mt = parts.next().unwrap_or("").trim().to_string();
    let mut charset = String::new();
    for p in parts {
        let p = p.trim();
        if p.len() >= 8 && p[..8].eq_ignore_ascii_case("charset=") {
            charset = p[8..].trim_matches('"').to_string();
        }
    }
    (mt, charset)
}

