impl Session {
    pub fn log(&self, s: &str) {
        if !self.o.quiet {
            eprintln!("{}", s);
        }
    }

    pub fn retrieve_asset(&mut self, parent_url: &Url, url: &Url) -> Result<Asset, ()> {
        match url.scheme.as_str() {
            "data" => {
                let (mt, cs, data) = parse_data_url(url);
                Ok((data, url.clone(), mt, cs))
            }
            "file" => {
                let cu = clean_url(url);
                if parent_url.scheme != "file" {
                    self.log(&format!("{} (security error)", cu));
                    return Err(());
                }
                let path = match url.to_file_path() {
                    Some(p) => p,
                    None => {
                        self.log(&format!("{} (file not found)", cu));
                        return Err(());
                    }
                };
                if path.exists() {
                    if path.is_dir() {
                        self.log(&format!("{} (is a directory)", cu));
                        Err(())
                    } else {
                        self.log(&cu.to_string());
                        match std::fs::read(&path) {
                            Ok(data) => {
                                let mt = detect_media_type(&data, url);
                                Ok((data, url.clone(), mt, String::new()))
                            }
                            Err(_) => Err(()),
                        }
                    }
                } else {
                    self.log(&format!("{} (file not found)", cu));
                    Err(())
                }
            }
            _ => {
                let cu = clean_url(url);
                let key = cu.to_string();
                if let Some(entry) = self.cache.get(&key) {
                    self.log(&format!("{} (from cache)", key));
                    return Ok(entry.clone());
                }
                // domain filtering
                if !self.o.domains.is_empty() {
                    let host = url.host_str().unwrap_or("").to_string();
                    let listed = self.o.domains.iter().any(|d| domain_matches(&host, d));
                    let allowed = if self.o.blacklist_domains { !listed } else { listed };
                    if !allowed {
                        return Err(());
                    }
                }
                let mut headers: Vec<(String, String)> = vec![];
                if parent_url.scheme == "http" || parent_url.scheme == "https" {
                    if parent_url != url {
                        headers.push(("referer".to_string(), clean_url(parent_url).to_string()));
                    }
                }
                headers.push(("accept".to_string(), "*/*".to_string()));
                let ua = self.o.user_agent.clone().unwrap_or_else(|| "Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:135.0) Gecko/20100101 Firefox/135.0".to_string());
                headers.push(("user-agent".to_string(), ua));
                if let Some(c) = self.cookie_header(url) {
                    headers.push(("cookie".to_string(), c));
                }
                let timeout = match self.o.timeout {
                    Some(0) => None,
                    Some(t) => Some(std::time::Duration::from_secs(t)),
                    None => Some(std::time::Duration::from_secs(60)),
                };
                match crate::http::get(&cu, &headers, timeout) {
                    Ok(resp) => {
                        let final_url = resp.url.clone();
                        let line = if final_url.to_string() != key { format!("{} -> {}", key, final_url) } else { key.clone() };
                        if !self.o.ignore_errors && !(200..300).contains(&resp.status) {
                            self.log(&format!("{} ({})", line, crate::http::status_text(resp.status)));
                            return Err(());
                        }
                        self.log(&line);
                        let (mut mt, cs) = match resp.header("content-type") {
                            Some(ct) => parse_content_type(ct),
                            None => (String::new(), String::new()),
                        };
                        if mt.is_empty() {
                            mt = detect_media_type(&resp.body, &final_url);
                        }
                        let entry = (resp.body, final_url, mt, cs);
                        self.cache.insert(key, entry.clone());
                        Ok(entry)
                    }
                    Err(crate::http::HttpError::Builder) => {
                        self.log(&format!("{} (builder error for url ({}))", key, key));
                        Err(())
                    }
                    Err(crate::http::HttpError::Request) => {
                        self.log(&format!("{} (error sending request for url ({}))", key, key));
                        Err(())
                    }
                }
            }
        }
    }

    fn cookie_header(&self, url: &Url) -> Option<String> {
        if self.cookies.is_empty() {
            return None;
        }
        let host = url.host_str().unwrap_or("").to_ascii_lowercase();
        let path = url.path_str();
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
        let mut parts = vec![];
        for c in &self.cookies {
            let d = c.domain.trim_start_matches('.').to_ascii_lowercase();
            let dm = host == d || (c.include_subdomains && host.ends_with(&format!(".{}", d)));
            if !dm {
                continue;
            }
            if !path.starts_with(&c.path) {
                continue;
            }
            if c.secure && url.scheme != "https" {
                continue;
            }
            if c.expires != 0 && c.expires < now {
                continue;
            }
            parts.push(format!("{}={}", c.name, c.value));
        }
        if parts.is_empty() {
            None
        } else {
            Some(parts.join("; "))
        }
    }

