        let mut result = String::new();
        let mut curr_rule = rule_name.to_string();
        let mut curr_prop = prop_name.to_string();
        for node in nodes {
            match node {
                CNode::Block(open, children) => match open {
                    Tok::Function(name) => {
                        result.push_str(name);
                        result.push('(');
                        let r = self.process_css(document_url, children, &curr_rule.clone(), &curr_prop.clone(), name);
                        result.push_str(&r);
                        result.push(')');
                    }
                    _ => {
                        if self.o.no_fonts && curr_rule == "font-face" {
                            continue;
                        }
                        let closure = match open {
                            Tok::ParenthesisBlock => {
                                result.push('(');
                                ")"
                            }
                            Tok::SquareBracketBlock => {
                                result.push('[');
                                "]"
                            }
                            _ => {
                                result.push('{');
                                "}"
                            }
                        };
                        let r = self.process_css(document_url, children, rule_name, &curr_prop.clone(), func_name);
                        result.push_str(&r);
                        result.push_str(closure);
                    }
                },
                CNode::Tok(t) => match t {
                    Tok::Comment(s) => result.push_str(s),
                    Tok::Semicolon => result.push(';'),
                    Tok::Colon => result.push(':'),
                    Tok::Comma => result.push(','),
                    Tok::CloseParenthesis => result.push(')'),
                    Tok::CloseSquareBracket => result.push(']'),
                    Tok::CloseCurlyBracket => result.push('}'),
                    Tok::IncludeMatch => result.push_str("~="),
                    Tok::DashMatch => result.push_str("|="),
                    Tok::PrefixMatch => result.push_str("^="),
                    Tok::SuffixMatch => result.push_str("$="),
                    Tok::SubstringMatch => result.push_str("*="),
                    Tok::CDO => result.push_str("<!--"),
                    Tok::CDC => result.push_str("-->"),
                    Tok::WhiteSpace(s) => result.push_str(s),
                    Tok::Ident(v) => {
                        curr_rule = String::new();
                        curr_prop = v.clone();
                        result.push_str(&format_ident(v));
                    }
                    Tok::AtKeyword(v) => {
                        curr_rule = v.clone();
                        if self.o.no_fonts && curr_rule == "font-face" {
                            continue;
                        }
                        result.push('@');
                        result.push_str(v);
                    }
                    Tok::Hash(v) => {
                        result.push('#');
                        result.push_str(v);
                    }
                    Tok::IDHash(v) => {
                        curr_rule = String::new();
                        result.push('#');
                        result.push_str(&format_ident(v));
                    }
                    Tok::QuotedString(v) => {
                        if curr_rule == "import" {
                            curr_rule = String::new();
                            if v.is_empty() {
                                result.push_str("''");
                                continue;
                            }
                            self.css_import(document_url, v, &mut result);
                        } else if func_name == "url" {
                            if v.is_empty() {
                                continue;
                            }
                            if self.o.no_images && is_image_url_prop(&curr_prop) {
                                result.push_str(&format_quoted_string(EMPTY_IMAGE_DATA_URL));
                            } else {
                                self.css_asset(document_url, v, &mut result);
                            }
                        } else {
                            result.push_str(&format_quoted_string(v));
                        }
                    }
                    Tok::Number { has_sign, value } => {
                        if *has_sign && *value >= 0.0 {
                            result.push('+');
                        }
                        result.push_str(&value.to_string());
                    }
                    Tok::Percentage { has_sign, unit_value } => {
                        if *has_sign && *unit_value >= 0.0 {
                            result.push('+');
                        }
                        result.push_str(&(unit_value * 100.0).to_string());
                        result.push('%');
                    }
                    Tok::Dimension { has_sign, value, unit } => {
                        if *has_sign && *value >= 0.0 {
                            result.push('+');
                        }
                        result.push_str(&value.to_string());
                        result.push_str(unit);
                    }
                    Tok::UnquotedUrl(v) => {
                        let is_import = curr_rule == "import";
                        if is_import {
                            curr_rule = String::new();
                        }
                        if v.is_empty() {
                            result.push_str("url()");
                            continue;
                        } else if v.starts_with('#') {
                            result.push_str("url(");
                            result.push_str(v);
                            result.push(')');
                            continue;
                        }
                        result.push_str("url(");
                        if is_import {
                            self.css_import(document_url, v, &mut result);
                        } else if self.o.no_images && is_image_url_prop(&curr_prop) {
                            result.push_str(&format_quoted_string(EMPTY_IMAGE_DATA_URL));
                        } else {
                            self.css_asset(document_url, v, &mut result);
                        }
                        result.push(')');
                    }
                    Tok::Delim(c) => result.push(*c),
                    Tok::BadUrl | Tok::BadString => {}
                    Tok::Function(_) | Tok::ParenthesisBlock | Tok::SquareBracketBlock | Tok::CurlyBracketBlock => {}
                },
            }
        }
        if !result.is_empty() && result.trim().is_empty() {
            result = result.trim().to_string();
        }
        result
    }

    // ---------------- HTML ----------------
    pub fn html_to_dom(&self, data: &[u8], charset: &str) -> Dom {
        let s = match encoding::for_label(charset) {
            Some(enc) if !charset.is_empty() => encoding::decode(enc, data),
            _ => String::from_utf8_lossy(data).into_owned(),
        };
        crate::treebuilder::parse_document(&s)
    }

    fn embed_srcset(&mut self, document_url: &Url, srcset: &str) -> String {
        let items = parse_srcset(srcset);
        let mut result = String::new();
        let n = items.len();
        for (i, (path, descriptor)) in items.into_iter().enumerate() {
            if self.o.no_images {
                result.push_str(EMPTY_IMAGE_DATA_URL);
            } else {
                let full = resolve_url(document_url, &path);
                match self.retrieve_asset(document_url, &full) {
                    Ok((data, final_url, mt, cs)) => {
                        let mut du = create_data_url(&mt, &cs, &data, &final_url);
                        du.fragment = full.fragment.clone();
                        result.push_str(&du.to_string());
                    }
                    Err(_) => {
                        if full.scheme == "http" || full.scheme == "https" {
                            result.push_str(&full.to_string());
                        } else {
                            result.push_str(EMPTY_IMAGE_DATA_URL);
                        }
                    }
                }
            }
            if !descriptor.is_empty() {
                result.push(' ');
                result.push_str(&descriptor);
            }
            if i + 1 < n {
                result.push_str(", ");
            }
        }
        result
    }

    // returns false if integrity check failed
    fn check_node_integrity(&self, dom: &mut Dom, node: usize, data: &[u8]) -> bool {
        if let Some(integrity) = dom.get_attr(node, "integrity") {
            let ok = integrity.is_empty() || check_integrity(data, &integrity);
            dom.set_attr(node, "integrity", None);
            return ok;
        }
        true
    }

    fn embed_attr(&mut self, dom: &mut Dom, node: usize, attr: &str, value: &str, document_url: &Url, with_fragment: bool) {
        let resolved = resolve_url(document_url, value);
        match self.retrieve_asset(document_url, &resolved) {
            Ok((data, final_url, mt, cs)) => {
                let name = dom.local_name(node).to_string();
                if name == "link" || name == "script" {
                    if !self.check_node_integrity(dom, node, &data) {
                        return;
                    }
                }
                let is_stylesheet = name == "link" && dom.get_attr(node, "rel").map(|r| r.to_ascii_lowercase().split_ascii_whitespace().any(|t| t == "stylesheet")).unwrap_or(false);
                if is_stylesheet {
                    let css = self.embed_css(&final_url, &String::from_utf8_lossy(&data));
                    let du = create_data_url(&mt, &cs, css.as_bytes(), &final_url);
                    dom.set_attr(node, attr, Some(&du.to_string()));
                } else if name == "frame" || name == "iframe" {
                    let mut fdom = self.html_to_dom(&data, &cs);
                    self.walk(&mut fdom, DOCUMENT, &final_url);
                    let s = crate::serialize::serialize_document(&fdom);
                    let bytes = match encoding::for_label(&cs) {
                        Some(e) if !cs.is_empty() => encoding::encode(e, &s),
                        _ => s.into_bytes(),
                    };
                    let mut du = create_data_url(&mt, &cs, &bytes, &final_url);
                    du.fragment = resolved.fragment.clone();
                    dom.set_attr(node, attr, Some(&du.to_string()));
                } else {
                    let mut du = create_data_url(&mt, &cs, &data, &final_url);
                    if with_fragment {
                        du.fragment = resolved.fragment.clone();
                    }
                    dom.set_attr(node, attr, Some(&du.to_string()));
                }
            }
            Err(_) => {
                if resolved.scheme == "http" || resolved.scheme == "https" {
                    dom.set_attr(node, attr, Some(&resolved.to_string()));
                } else {
                    dom.set_attr(node, attr, None);
                }
            }
        }
    }

    fn parent_name(dom: &Dom, node: usize) -> String {
        match dom.nodes[node].parent {
            Some(p) => dom.local_name(p).to_string(),
            None => String::new(),
        }
    }

    pub fn walk(&mut self, dom: &mut Dom, node: usize, document_url: &Url) {
        let is_elem = dom.is_element(node);
        if is_elem {
            let name = dom.local_name(node).to_string();
            match name.as_str() {
                "meta" => {
                    if let Some(he) = dom.get_attr(node, "http-equiv") {
                        let v = he.trim().to_ascii_lowercase();
                        if v == "refresh" || v == "location" {
                            dom.set_attr(node, "http-equiv", None);
                        }
                    }
                }
                "link" => {
                    let rel = dom.get_attr(node, "rel").unwrap_or_default().to_ascii_lowercase();
                    let tokens: Vec<&str> = rel.split_ascii_whitespace().collect();
                    if tokens.contains(&"stylesheet") {
                        if let Some(href) = dom.get_attr(node, "href") {
                            if self.o.no_css {
                                dom.set_attr(node, "href", None);
                            } else if !href.is_empty() {
                                self.embed_attr(dom, node, "href", &href, document_url, true);
                            }
                        }
                    } else if tokens.iter().any(|t| *t == "icon" || *t == "apple-touch-icon") {
                        if let Some(href) = dom.get_attr(node, "href") {
                            if self.o.no_images || href.is_empty() {
                                dom.set_attr(node, "href", None);
                            } else {
                                self.embed_attr(dom, node, "href", &href, document_url, true);
                            }
                        }
                    } else if tokens.iter().any(|t| *t == "preload" || *t == "dns-prefetch") {
                        dom.set_attr(node, "rel", None);
                    } else if let Some(href) = dom.get_attr(node, "href") {
                        let r = resolve_url(document_url, &href);
                        dom.set_attr(node, "href", Some(&r.to_string()));
                    }
                }
                "base" => {
                    if document_url.scheme == "http" || document_url.scheme == "https" {
                        if let Some(href) = dom.get_attr(node, "href") {
                            let r = resolve_url(document_url, &href);
                            dom.set_attr(node, "href", Some(&r.to_string()));
                        }
                    }
                }
                "body" => {
                    if let Some(bg) = dom.get_attr(node, "background") {
                        dom.set_attr(node, "background", None);
                        if !self.o.no_images && !bg.is_empty() {
                            self.embed_attr(dom, node, "background", &bg, document_url, true);
                        }
                    }
                }
                "img" => {
                    if self.o.no_images {
                        if dom.has_attr(node, "src") {
                            dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                        }
                        if dom.has_attr(node, "data-src") {
                            dom.set_attr(node, "data-src", Some(EMPTY_IMAGE_DATA_URL));
                        }
                    } else {
                        let ds = dom.get_attr(node, "data-src").unwrap_or_default();
                        let src = if !ds.is_empty() { ds } else { dom.get_attr(node, "src").unwrap_or_default() };
                        if src.is_empty() {
                            dom.set_attr(node, "src", Some(""));
                        } else {
                            self.embed_attr(dom, node, "src", &src, document_url, true);
                        }
                    }
                    if let Some(ss) = dom.get_attr(node, "srcset") {
                        if !ss.is_empty() {
                            let r = self.embed_srcset(document_url, &ss);
                            dom.set_attr(node, "srcset", Some(&r));
                        }
                    }
                }
                "input" => {
                    if dom.get_attr(node, "type").map(|t| t.eq_ignore_ascii_case("image")).unwrap_or(false) {
                        if let Some(src) = dom.get_attr(node, "src") {
                            if !src.is_empty() {
                                if self.o.no_images {
                                    dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                                } else {
                                    self.embed_attr(dom, node, "src", &src, document_url, true);
                                }
                            }
                        }
                    }
                }
                "svg" => {
                    if self.o.no_images {
                        let children = dom.nodes[node].children.clone();
                        for c in children {
                            dom.detach(c);
                        }
                    }
                }
                "image" | "use" => {
                    if let Some(href) = dom.get_attr(node, "href") {
                        if self.o.no_images {
                            dom.set_attr(node, "href", None);
                        } else {
                            self.embed_attr(dom, node, "href", &href, document_url, false);
                        }
                    }
                }
                "source" => {
                    let parent = Self::parent_name(dom, node);
                    if parent == "audio" || parent == "video" {
                        let disabled = if parent == "audio" { self.o.no_audio } else { self.o.no_video };
                        if let Some(src) = dom.get_attr(node, "src") {
                            if disabled {
                                dom.set_attr(node, "src", None);
                            } else {
                                self.embed_attr(dom, node, "src", &src, document_url, true);
                            }
                        }
                    } else if parent == "picture" {
                        if let Some(ss) = dom.get_attr(node, "srcset") {
                            if !ss.is_empty() {
                                let r = self.embed_srcset(document_url, &ss);
                                dom.set_attr(node, "srcset", Some(&r));
                            }
                        }
                    }
                }
                "audio" | "video" => {
                    let disabled = if name == "audio" { self.o.no_audio } else { self.o.no_video };
                    if let Some(src) = dom.get_attr(node, "src") {
                        if disabled {
                            dom.set_attr(node, "src", None);
                        } else {
                            self.embed_attr(dom, node, "src", &src, document_url, true);
                        }
                    }
                    if name == "video" {
                        if let Some(poster) = dom.get_attr(node, "poster") {
                            if !poster.is_empty() {
                                if self.o.no_images {
                                    dom.set_attr(node, "poster", Some(EMPTY_IMAGE_DATA_URL));
                                } else {
                                    self.embed_attr(dom, node, "poster", &poster, document_url, true);
                                }
                            }
                        }
                    }
                }
                "frame" | "iframe" => {
                    if let Some(src) = dom.get_attr(node, "src") {
                        if self.o.no_frames {
                            dom.set_attr(node, "src", Some(""));
                        } else if !src.trim().is_empty() {
                            self.embed_attr(dom, node, "src", &src, document_url, true);
                        }
                    }
                }
                "noscript" => {
                    let children = dom.nodes[node].children.clone();
                    for c in children {
                        let text = match &dom.nodes[c].data {
                            NodeData::Text(t) => t.clone(),
                            _ => continue,
                        };
                        let mut ndom = crate::treebuilder::parse_document(&text);
                        self.walk(&mut ndom, DOCUMENT, document_url);
                        let body = find_body(&ndom);
                        let s = match body {
                            Some(b) => crate::serialize::serialize_children(&ndom, b),
                            None => String::new(),
                        };
                        dom.nodes[c].data = NodeData::Text(s);
                    }
                }
                "a" | "area" => {
                    if let Some(href) = dom.get_attr(node, "href") {
                        if self.o.no_js && href.trim().to_ascii_lowercase().starts_with("javascript:") {
                            dom.set_attr(node, "href", Some("javascript:;"));
                        } else if href.starts_with('#') || Url::parse(&href).is_ok() {
                            // keep as is
                        } else {
                            let r = resolve_url(document_url, &href);
                            dom.set_attr(node, "href", Some(&r.to_string()));
                        }
                    }
                }
                "form" => {
                    if let Some(action) = dom.get_attr(node, "action") {
                        let r = resolve_url(document_url, &action);
                        dom.set_attr(node, "action", Some(&r.to_string()));
                    }
                }
                "script" => {
                    let stype = dom.get_attr(node, "type");
                    let src = dom.get_attr(node, "src");
                    if self.o.no_js {
                        let children = dom.nodes[node].children.clone();
                        for c in children {
                            dom.detach(c);
                        }
                        dom.set_attr(node, "src", None);
                    } else if let Some(src) = src {
                        if !src.is_empty() {
                            let resolved = resolve_url(document_url, &src);
                            match self.retrieve_asset(document_url, &resolved) {
                                Ok((data, final_url, mt, cs)) => {
                                    if self.check_node_integrity(dom, node, &data) {
                                        let inline = match &stype {
                                            None => true,
                                            Some(t) => t == "text/javascript" || t == "application/javascript",
                                        };
                                        if inline {
                                            let text = match encoding::for_label(&cs) {
                                                Some(e) if !cs.is_empty() => encoding::decode(e, &data),
                                                _ => String::from_utf8_lossy(&data).into_owned(),
                                            };
                                            let t = dom.create(NodeData::Text(text));
                                            dom.append(node, t);
                                            dom.set_attr(node, "src", None);
                                        } else {
                                            let st = stype.clone().unwrap_or_default();
                                            let m = if !st.is_empty() { st } else { mt };
                                            let du = create_data_url(&m, &cs, &data, &final_url);
                                            dom.set_attr(node, "src", Some(&du.to_string()));
                                        }
                                    }
                                }
                                Err(_) => {
                                    if resolved.scheme == "http" || resolved.scheme == "https" {
                                        dom.set_attr(node, "src", Some(&resolved.to_string()));
                                    } else {
                                        dom.set_attr(node, "src", None);
                                    }
                                }
                            }
                        }
                    }
                }
                "style" => {
                    if self.o.no_css {
                        let children = dom.nodes[node].children.clone();
                        for c in children {
                            dom.detach(c);
                        }
                    } else {
                        let children = dom.nodes[node].children.clone();
                        for c in children {
                            let text = match &dom.nodes[c].data {
                                NodeData::Text(t) => t.clone(),
                                _ => continue,
                            };
                            let r = self.embed_css(document_url, &text);
                            dom.nodes[c].data = NodeData::Text(r);
                        }
                    }
                }
                _ => {}
            }
            // style attribute
            if self.o.no_css {
                dom.set_attr(node, "style", None);
            } else if let Some(style) = dom.get_attr(node, "style") {
                let r = self.embed_css(document_url, &style);
                dom.set_attr(node, "style", Some(&r));
            }
            // event handlers
            if self.o.no_js {
                if let Some(attrs) = dom.attrs_mut(node) {
                    attrs.retain(|a| !a.name.starts_with("on"));
                }
            }
        }
        let children = dom.nodes[node].children.clone();
        for c in children {
            self.walk(dom, c, document_url);
        }
    }
}

pub fn find_body(dom: &Dom) -> Option<usize> {
    let html = dom.find_child_element(DOCUMENT, "html")?;
    dom.find_child_element(html, "body")
}

pub fn find_head(dom: &Dom) -> Option<usize> {
    let html = dom.find_child_element(DOCUMENT, "html")?;
    dom.find_child_element(html, "head")
}

fn ends_with_descriptor_char(s: &str) -> bool {
    s.ends_with('x') || s.ends_with('w')
}

pub fn parse_srcset(srcset: &str) -> Vec<(String, String)> {
    let tokens: Vec<&str> = srcset.split_ascii_whitespace().collect();
    let mut items = vec![];
    let mut i = 0;
    let n = tokens.len();
    let mut guard = 0;
    while i < n {
        guard += 1;
        if guard > 100000 {
            break;
        }
        let url = tokens[i];
        if let Some(u) = url.strip_suffix(',') {
            items.push((u.to_string(), String::new()));
            i += 1;
            continue;
        }
        if i + 1 >= n {
            items.push((url.to_string(), String::new()));
            i += 1;
            continue;
        }
        let d = tokens[i + 1];
        if let Some(dd) = d.strip_suffix(',') {
            items.push((url.to_string(), dd.to_string()));
            i += 2;
        } else if ends_with_descriptor_char(d) {
            items.push((url.to_string(), d.to_string()));
            i += 2;
        } else if let Some(k) = d.find(',') {
            let pre = &d[..k];
            if ends_with_descriptor_char(pre) {
                items.push((url.to_string(), pre.to_string()));
                i += 1;
            } else {
                // original implementation loops forever here; bail out
                items.push((url.to_string(), String::new()));
                i += 1;
            }
        } else {
            items.push((url.to_string(), String::new()));
            i += 1;
        }
    }
    items
}

pub fn make_meta(dom: &mut Dom, attrs: Vec<(&str, &str)>) -> usize {
    let a: Vec<Attr> = attrs.into_iter().map(|(k, v)| Attr::new(k, v)).collect();
    dom.create_element(Ns::None, "meta", a)
}
