fn head_children_named(dom: &Dom, name: &str) -> Vec<usize> {
    match find_head(dom) {
        Some(h) => dom.nodes[h].children.iter().copied().filter(|&c| dom.local_name(c) == name && dom.is_element(c)).collect(),
        None => vec![],
    }
}

fn get_base_href(dom: &Dom) -> Option<String> {
    let bases = head_children_named(dom, "base");
    let first = *bases.first()?;
    dom.get_attr(first, "href")
}

fn get_charset(dom: &Dom) -> Option<String> {
    let metas = head_children_named(dom, "meta");
    for &m in &metas {
        if let Some(c) = dom.get_attr(m, "charset") {
            return Some(c);
        }
    }
    for &m in &metas {
        if dom.get_attr(m, "http-equiv").map(|v| v.eq_ignore_ascii_case("content-type")).unwrap_or(false) {
            let content = dom.get_attr(m, "content").unwrap_or_default();
            let (_, cs) = embed::parse_content_type(&content);
            return Some(cs);
        }
    }
    None
}

fn set_charset(dom: &mut Dom, charset: &str) {
    let metas = head_children_named(dom, "meta");
    let mut found = false;
    for &m in &metas {
        if dom.has_attr(m, "charset") {
            dom.set_attr(m, "charset", Some(charset));
            found = true;
        } else if dom.get_attr(m, "http-equiv").map(|v| v.eq_ignore_ascii_case("content-type")).unwrap_or(false) {
            dom.set_attr(m, "content", Some(&format!("text/html;charset={}", charset)));
            found = true;
        }
    }
    if !found {
        if let Some(h) = find_head(dom) {
            let m = make_meta(dom, vec![("charset", charset)]);
            dom.append(h, m);
        }
    }
}

fn set_robots(dom: &mut Dom) {
    let metas = head_children_named(dom, "meta");
    let mut found = false;
    for &m in &metas {
        if dom.get_attr(m, "name").map(|v| v.eq_ignore_ascii_case("robots")).unwrap_or(false) {
            dom.set_attr(m, "content", Some("none"));
            found = true;
        }
    }
    if !found {
        if let Some(h) = find_head(dom) {
            let m = make_meta(dom, vec![("name", "robots"), ("content", "none")]);
            dom.append(h, m);
        }
    }
}

fn set_base_url(dom: &mut Dom, href: &str) {
    let bases = head_children_named(dom, "base");
    if let Some(&b) = bases.first() {
        dom.set_attr(b, "href", Some(href));
    } else if let Some(h) = find_head(dom) {
        let b = dom.create_element(Ns::None, "base", vec![Attr::new("href", href)]);
        dom.append(h, b);
    }
}

fn has_favicon(dom: &Dom, node: usize) -> bool {
    if dom.is_element(node) && dom.local_name(node) == "link" {
        if let Some(rel) = dom.get_attr(node, "rel") {
            let r = rel.to_ascii_lowercase();
            if r.split_ascii_whitespace().any(|t| t == "icon" || t == "apple-touch-icon") {
                return true;
            }
        }
    }
    dom.nodes[node].children.iter().any(|&c| has_favicon(dom, c))
}

fn get_title(dom: &Dom) -> Option<String> {
    let titles = head_children_named(dom, "title");
    let t = *titles.first()?;
    Some(dom.text_content(t))
}

fn csp_string(o: &cli::Args) -> String {
    let mut parts = vec![];
    if o.isolate {
        parts.push("default-src 'unsafe-eval' 'unsafe-inline' data:;");
    }
    if o.no_css {
        parts.push("style-src 'none';");
    }
    if o.no_fonts {
        parts.push("font-src 'none';");
    }
    if o.no_frames {
        parts.push("frame-src 'none'; child-src 'none';");
    }
    if o.no_js {
        parts.push("script-src 'none';");
    }
    if o.no_images {
        parts.push("img-src data:;");
    }
    parts.join(" ")
}

fn read_cookies(path: &str) -> Result<Vec<embed::Cookie>, ()> {
    let content = std::fs::read_to_string(path).map_err(|_| ())?;
    let mut out = vec![];
    for line in content.lines() {
        let mut l = line;
        let mut http_only = false;
        if let Some(rest) = l.strip_prefix("#HttpOnly_") {
            l = rest;
            http_only = true;
        }
        let _ = http_only;
        if l.starts_with('#') || l.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = l.split('\t').collect();
        if f.len() < 7 {
            continue;
        }
        out.push(embed::Cookie {
            domain: f[0].to_string(),
            include_subdomains: f[1].eq_ignore_ascii_case("TRUE"),
            path: f[2].to_string(),
            secure: f[3].eq_ignore_ascii_case("TRUE"),
            expires: f[4].parse().unwrap_or(0),
            name: f[5].to_string(),
            value: f[6].to_string(),
        });
    }
    Ok(out)
}

fn main() {
    let args = cli::parse();
    let quiet = args.quiet;

    if let Some(e) = &args.encoding {
        if encoding::for_label(e).is_none() {
            die(quiet, &format!("Error: unknown encoding \"{}\"", e));
        }
    }

    let mut sess = Session { o: args.clone(), cache: HashMap::new(), cookies: vec![] };
    if args.mhtml {
        sess.o.no_js = true;
    }

    let target = args.target.clone();
    let mut is_stdin = false;
    let target_url: Url;
    if target == "-" {
        is_stdin = true;
        target_url = Url::parse("data:text/html,").unwrap();
    } else {
        match Url::parse(&target) {
            Ok(u) => match u.scheme.as_str() {
                "data" | "file" | "http" | "https" => target_url = u,
                s => die(quiet, &format!("Error: unsupported target URL scheme \"{}\"", s)),
            },
            Err(_) => {
                let p = std::path::Path::new(&target);
                if p.exists() {
                    if p.is_file() {
                        let abs = std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
                        target_url = Url::from_file_path(&abs);
                    } else {
                        die(quiet, &format!("Error: local target \"{}\" is not a file", target));
                    }
                } else {
                    match Url::parse(&format!("http://{}", target)) {
                        Ok(u) => target_url = u,
                        Err(_) => die(quiet, &format!("Error: could not parse target URL \"{}\"", target)),
                    }
                }
            }
        }
    }

    if let Some(cf) = &args.cookie_file {
        match read_cookies(cf) {
            Ok(c) => sess.cookies = c,
            Err(_) => die(quiet, &format!("Error: could not read specified cookie file")),
        }
    }

    let (data, final_url, media_type, charset) = if is_stdin {
        let mut buf = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut buf);
        (buf, target_url.clone(), "text/html".to_string(), String::new())
    } else {
        match sess.retrieve_asset(&target_url, &target_url) {
            Ok(r) => r,
            Err(_) => die(quiet, "Error: could not retrieve target document"),
        }
    };

    let mt_lower = media_type.to_ascii_lowercase();
    let is_html = mt_lower == "text/html" || mt_lower == "application/xhtml+xml";

    let output_bytes: Vec<u8>;
    let mut title: Option<String> = None;
    if is_html {
        let mut document_encoding = charset.clone();
        let mut dom = sess.html_to_dom(&data, &document_encoding);
        if let Some(cs) = get_charset(&dom) {
            if !cs.is_empty() {
                if let Some(enc) = encoding::for_label(&cs) {
                    let _ = enc;
                    document_encoding = cs.clone();
                    dom = sess.html_to_dom(&data, &document_encoding);
                }
            }
        }

        // determine base URL
        let mut base_url = final_url.clone();
        if let Some(custom) = &args.base_url {
            match Url::parse(custom) {
                Ok(u) => {
                    if u.scheme == "file" {
                        if final_url.scheme == "file" {
                            base_url = u;
                        }
                    } else {
                        base_url = u;
                    }
                }
                Err(_) => {
                    if final_url.scheme == "file" {
                        let p = std::path::Path::new(custom);
                        if p.exists() {
                            if let Ok(abs) = std::fs::canonicalize(p) {
                                base_url = Url::from_file_path(&abs);
                            }
                        }
                    }
                }
            }
        } else if let Some(href) = get_base_href(&dom) {
            base_url = resolve_url(&final_url, &href);
        }

        sess.walk(&mut dom, DOCUMENT, &base_url);

        if let Some(custom) = &args.base_url {
            set_base_url(&mut dom, custom);
        }

        // favicon
        if (target_url.scheme == "http" || target_url.scheme == "https") && !sess.o.no_images && !has_favicon(&dom, DOCUMENT) {
            let fav = resolve_url(&base_url, "/favicon.ico");
            if let Ok((fdata, ffinal, fmt, fcs)) = sess.retrieve_asset(&base_url, &fav) {
                let du = util::create_data_url(&fmt, &fcs, &fdata, &ffinal);
                if let Some(h) = find_head(&dom) {
                    let l = dom.create_element(Ns::None, "link", vec![Attr::new("rel", "icon"), Attr::new("href", &du.to_string())]);
                    dom.append(h, l);
                }
            }
        }

        let csp = csp_string(&sess.o);
        if !csp.is_empty() {
            if let Some(h) = find_head(&dom) {
                let m = make_meta(&mut dom, vec![("http-equiv", "Content-Security-Policy"), ("content", &csp)]);
                dom.prepend(h, m);
            }
        }

        set_robots(&mut dom);

        if let Some(e) = &args.encoding {
            set_charset(&mut dom, e);
            document_encoding = e.clone();
        }

        title = get_title(&dom);

        let mut html = serialize::serialize_document(&dom);
        if args.unwrap_noscript {
            html = unwrap_noscript(&html);
        }

        if !args.no_metadata && !is_stdin {
            let from = if target_url.scheme == "http" || target_url.scheme == "https" {
                let mut u = target_url.clone();
                u.username.clear();
                u.password.clear();
                u.fragment = None;
                u.to_string()
            } else {
                "local source".to_string()
            };
            html = format!("<!-- Saved from {} at {} using monolith v2.11.0 -->\n{}", from, timestamp(), html);
        }

        let enc = if document_encoding.is_empty() { None } else { encoding::for_label(&document_encoding) };
        let mut body = match enc {
            Some(e) => encoding::encode(e, &html),
            None => html.into_bytes(),
        };
        if args.mhtml {
            let mut out = Vec::new();
            out.extend_from_slice(b"MIME-Version: 1.0\r\nContent-Type: multipart/related; boundary=\"----=_NextPart_000_0000\"\r\n\r\n------=_NextPart_000_0000\r\nContent-Type: text/html; charset=\"utf-8\"\r\nContent-Location: http://example.com/\r\n\r\n");
            out.extend_from_slice(&body);
            out.extend_from_slice(b"\r\n------=_NextPart_000_0000--\r\n");
            body = out;
        } else {
            body.push(b'\n');
        }
        output_bytes = body;
    } else {
        output_bytes = data;
    }

    let _ = NodeData::Document;
    match &args.output {
        None => write_stdout(&output_bytes),
        Some(o) if o.is_empty() || o == "-" => write_stdout(&output_bytes),
        Some(o) => {
            let mut path = o.clone();
            if path.contains("%title%") {
                let t = title.clone().unwrap_or_default();
                let t = t.replace(':', " - ").replace('/', "_").replace('\\', "_").replace('|', "-").replace('<', "[").replace('>', "]").replace('"', "").replace('?', "");
                path = path.replace("%title%", &t);
            }
            if path.contains("%timestamp%") {
                path = path.replace("%timestamp%", &timestamp().replace(':', "_"));
            }
            match std::fs::File::create(&path) {
                Ok(mut f) => {
                    let _ = f.write_all(&output_bytes);
                }
                Err(e) => {
                    eprintln!("\nthread 'main' panicked at src/main.rs:305:18:\ncould not prepare output: {:?}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", e);
                    std::process::exit(101);
                }
            }
        }
    }
}

fn write_stdout(b: &[u8]) {
    let stdout = std::io::stdout();
    let mut l = stdout.lock();
    let _ = l.write_all(b);
    let _ = l.flush();
}

fn unwrap_noscript(s: &str) -> String {
    // replace <noscript...> and </noscript...> with comments
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let b = s.as_bytes();
    while i < b.len() {
        if b[i] == b'<' {
            let rest = &s[i + 1..];
            let (is_tag, skip) = if rest.starts_with("noscript") {
                (true, 0)
            } else if rest.starts_with("/noscript") {
                (true, 1)
            } else {
                (false, 0)
            };
            let _ = skip;
            if is_tag {
                if let Some(end) = rest.find('>') {
                    out.push_str("<!--");
                    out.push_str(&rest[..end]);
                    out.push_str("-->");
                    i += 1 + end + 1;
                    continue;
                }
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}
