// returns (media_type, charset, is_base64)
pub fn parse_content_type(content_type: &str) -> (String, String, bool) {
    let mut media_type = "text/plain".to_string();
    let mut charset = "US-ASCII".to_string();
    let mut is_base64 = false;
    for (i, item) in content_type.split(';').enumerate() {
        let item = item.trim();
        if i == 0 {
            if !item.is_empty() {
                media_type = item.to_string();
            }
        } else if item.eq_ignore_ascii_case("base64") {
            is_base64 = true;
        } else if let Some(c) = item.strip_prefix("charset=") {
            charset = c.to_string();
        }
    }
    (media_type, charset, is_base64)
}

// returns (media_type, charset, data)
pub fn parse_data_url(url: &Url) -> (String, String, Vec<u8>) {
    let path = url.path_str();
    let (header, data_part) = match path.find(',') {
        Some(i) => (&path[..i], &path[i + 1..]),
        None => (path.as_str(), ""),
    };
