def parse(fn):
    out = open(os.path.join(SRC, fn), 'rb').read().decode('utf-8')
    body = out.split('<pre>', 1)[1].split('</pre>')[0]
    res = {}
    for line in body.split('\n'):
        if ':' in line:
            k, v = line.split(':', 1)
            res[k] = v.replace('&lt;', '<').replace('&gt;', '>').replace('&amp;', '&').replace('&nbsp;', '\xa0')
    return res

def write(name, arr):
    with open(os.path.join(OUT, name), 'wb') as f:
        for v in arr:
            f.write(struct.pack('<I', v))

