fn domain_to_ascii(s: &str) -> Result<String, ParseError> {
    if s.is_ascii() {
        let lower = s.to_ascii_lowercase();
        for label in lower.split('.') {
            check_ace_label(label)?;
        }
        return Ok(lower);
    }
    let map = idna_map();
    let mut mapped = String::new();
    for c in s.chars() {
        let cp = c as u32;
        if cp < 0x80 {
            mapped.push(c.to_ascii_lowercase());
            continue;
        }
        if cp == 0x200C || cp == 0x200D {
            return Err(ParseError);
        }
        match map.get(&cp) {
            Some(m) => mapped.push_str(m),
            None => mapped.push(c),
        }
    }
    let mapped: String = mapped
        .chars()
        .map(|c| match c {
            '\\u{3002}' | '\\u{FF0E}' | '\\u{FF61}' => '.',
            _ => c,
        })
        .collect();
    let mut labels = vec![];
    for label in mapped.split('.') {
        if label.is_ascii() {
            check_ace_label(label)?;
            labels.push(label.to_string());
        } else {
            if label.chars().any(|c| (c as u32) < 0x20 || c.is_whitespace()) {
                return Err(ParseError);
            }
            labels.push(format!("xn--{}", punycode_encode(label).ok_or(ParseError)?));
        }
    }
    Ok(labels.join("."))
}

fn check_ace_label(label: &str) -> Result<(), ParseError> {
    if label.len() >= 4 && label[..4].eq_ignore_ascii_case("xn--") {
        let rest = &label[4..];
        match punycode_decode(rest) {
            Some(d) => {
                if d.is_empty() || d.chars().all(|c| c.is_ascii()) || d.chars().any(|c| (c as u32) < 0xA0) {
                    return Err(ParseError);
                }
            }
            None => return Err(ParseError),
        }
    }
    Ok(())
}

fn punycode_decode(input: &str) -> Option<String> {
    let base = 36u32;
    let tmin = 1u32;
    let tmax = 26u32;
    let skew = 38u32;
    let damp = 700u32;
    let (basic, rest) = match input.rfind('-') {
        Some(i) => (&input[..i], &input[i + 1..]),
        None => ("", input),
    };
    let mut output: Vec<u32> = basic.chars().map(|c| c as u32).collect();
    if !basic.is_ascii() {
        return None;
    }
    let mut n = 128u32;
    let mut i = 0u32;
